/**
 * JSON configurado para persistir GameState.
 * `allowStructuredMapKeys` es indispensable porque `grid: Map<Position, CellContent>` usa
 * una data class como clave — sin esto kotlinx-serialization lanza JsonEncodingException
 * y el guardado del modo infinito nunca llega a DataStore.
 * `ignoreUnknownKeys` tolera saves de esquemas anteriores (campos eliminados como isStar/isFrozen).
 */
private val GameStateJson = Json {
    allowStructuredMapKeys = true
    ignoreUnknownKeys = true
    encodeDefaults = true
}

/** Qué operación de cuenta está en curso, para el texto de la pantalla de carga inmersiva. */
enum class AccountLoadingKind { LOADING, LOGGING_OUT, DELETING_ACCOUNT }

/** Desenlace del borrado de cuenta, para que Ajustes diga exactamente qué pasó. */
enum class AccountDeletionOutcome { DELETED, REQUIRES_RECENT_LOGIN, OFFLINE, FAILED }

/** Proveedor de identidad con el que el jugador respalda su progreso en la nube. */
enum class LinkedProvider { GOOGLE }

/**
 * Resumen de progreso de una cuenta para que el jugador compare la nube (cuenta anterior) contra su
 * progreso local antes de decidir cuál conservar al vincular la cuenta.
 */
data class CloudAccountConflict(
    val cloudLevel: Int,
    val cloudCoins: Int,
    val cloudXp: Int,
    val cloudName: String,
    val localLevel: Int,
    val localCoins: Int,
    val localXp: Int,
    val localName: String
)

/**
 * El motor lógico del juego. Procesa las reglas, valida movimientos,
 * y maneja las fusiones (Suika mechanics) de forma inmutable.
 */
class GameViewModel(
    private val prefs: PreferencesManager,
    val soundManager: SoundManager,
    private val appContext: android.content.Context
) : ViewModel() {

    private val _gameState = MutableStateFlow(GameState.initial().copy(status = com.cukiti.teikafusion.model.GameStatus.SPLASH))
    val gameState: StateFlow<GameState> = _gameState.asStateFlow()

    /**
     * **EL AZAR DE LA PARTIDA, EN UN SOLO SITIO** (2026-09-25, P-287). Todo lo que el motor sortea
     * —el reparto de la bandeja, sus colores, los blancos de los biomas, el eco de las habilidades— sale
     * de aquí. En el juego es `Random.Default`, igual que antes; el bot de niveles lo SIEMBRA por
     * partida para que el mismo nivel con la misma semilla se juegue igual y un A/B compare las MISMAS
     * partidas. Sin esto, dos pasadas idénticas daban 3/10 y 7/10 en los mismos niveles.
     */
    internal var rng: kotlin.random.Random = kotlin.random.Random.Default

    /**
     * **EL RELOJ DEL JUEGO** (2026-09-28), hermano de [rng]: las esperas de juego medidas en milisegundos
     * de pared (la quietud de los cuerpos antes del derrumbe con gravedad, los topes de la cámara lenta
     * y de las cápsulas) lo leen de aquí. En la app es el reloj del sistema; el bot de niveles pone su
     * reloj VIRTUAL, porque juega decenas de veces más rápido que el tiempo real y con el de pared esas
     * esperas no llegaban nunca (o duraban una eternidad) dentro de su partida.
     */
    internal var clockMs: () -> Long = { System.currentTimeMillis() }

    /** Siembra los ids de los cuerpos de Teika (ver `TeikaPhysicsWorld.seedBodyIds`): partidas del bot repetibles. */
    internal fun seedTeikaBodyIds(seed: Long) = physicsWorld.seedBodyIds(seed)

    // Estrellas (1-3) del MEJOR resultado por nivel superado: nivel → estrellas. Alimenta el mapa
    // (los cuadritos del mural brillan según su calificación) y se persiste en DataStore.
    private val _levelStars = MutableStateFlow<Map<Int, Int>>(emptyMap())
    val levelStars: StateFlow<Map<Int, Int>> = _levelStars.asStateFlow()

    // Cinemática de "mural completo": se setea al superar el ÚLTIMO nivel de un capítulo (una sola
    // vez por mural, gobernado por prefs.markMuralRewarded). La UI la observa, celebra y la limpia.
    private val _muralCelebration = MutableStateFlow<com.cukiti.teikafusion.model.MuralCelebration?>(null)
    val muralCelebration: StateFlow<com.cukiti.teikafusion.model.MuralCelebration?> = _muralCelebration.asStateFlow()

    fun dismissMuralCelebration() { _muralCelebration.value = null }

    // Única invitación automática a respaldar la partida: aparece al terminar el tutorial 4 y nunca
    // vuelve a encolarse por ganar niveles. Ajustes y Ranking conservan sus accesos manuales a Google.
    /**
     * **LA OFERTA DEL PAQUETE INICIAL** (P-210, 2026-09-07, decisión del usuario).
     *
     * El pack es el producto que más convierte y hasta hoy solo lo veía quien entraba a la pestaña
     * Tienda por su cuenta. Se enseña **una sola vez**, al cerrar el primer capítulo —el momento en
     * que el jugador ya sabe si el juego le gusta— y **sin cuenta atrás**: si la cierra, el pack
     * sigue en la tienda para siempre. Se eligió así, y no con el reloj del género, para no meterle
     * prisa a alguien que acaba de empezar.
     */
    private val _showStarterPackOffer = MutableStateFlow(false)
    val showStarterPackOffer: StateFlow<Boolean> = _showStarterPackOffer.asStateFlow()

    /** Cerrar la oferta. La marca de «ya se ofreció» se guardó al ABRIRLA, no aquí: ver abajo. */
    fun dismissStarterPackOffer() { _showStarterPackOffer.value = false }

    private val _showPostTutorialBackupPrompt = MutableStateFlow(false)
    val showPostTutorialBackupPrompt: StateFlow<Boolean> = _showPostTutorialBackupPrompt.asStateFlow()

    fun dismissPostTutorialBackupPrompt() { _showPostTutorialBackupPrompt.value = false }

    /**
     * Se completa cuando el saldo real de teikoins ya se cargó de DataStore al estado.
     * Cualquier concesión/cobro de monedas (racha diaria, compras de Billing, etc.) debe
     * esperar esta compuerta para no operar sobre el valor por defecto (100) ni sobrescribir
     * el saldo guardado del jugador. Sin esto, el jugador perdía su dinero en cada arranque.
     */
    private val coinsLoaded = kotlinx.coroutines.CompletableDeferred<Unit>()
    private val cloudStateLoaded = kotlinx.coroutines.CompletableDeferred<Unit>()
    // Se completa cuando la identidad canónica está resuelta: inmediatamente si el arranque confirma
    // que NO hay sesión de nube (anónimo, que nunca escribe), o tras authenticateWithGoogle
    // (UID canónico fijado). Hasta entonces NADIE escribe player_stats — así se evita crear un perfil
    // bajo el UID anónimo transitorio mientras el login resuelve.
    private val cloudIdentityResolved = kotlinx.coroutines.CompletableDeferred<Unit>()
    private fun markCloudIdentityResolved() {
        if (!cloudIdentityResolved.isCompleted) cloudIdentityResolved.complete(Unit)
    }
    private val cloudSyncMutex = Mutex()

    private val _playerId = MutableStateFlow("")
    val playerId: StateFlow<String> = _playerId.asStateFlow()

    private val _dragState = MutableStateFlow<DragState>(DragState.Idle)
    val dragState: StateFlow<DragState> = _dragState.asStateFlow()

    // Ajustes de audio/vibración independientes, observables por la UI.
    // Música y efectos son VOLUMEN (0f..1f), controlados con sliders en Ajustes.
    private val _musicVolume = MutableStateFlow(0.6f)
    val musicVolume: StateFlow<Float> = _musicVolume.asStateFlow()
    private val _sfxVolume = MutableStateFlow(1f)
    val sfxVolume: StateFlow<Float> = _sfxVolume.asStateFlow()
    private val _vibrationEnabled = MutableStateFlow(true)
    val vibrationEnabled: StateFlow<Boolean> = _vibrationEnabled.asStateFlow()
    // Inclinación: los Teikas ruedan al inclinar el teléfono. Se respeta en tiempo real (el sensor
    // de GameScreen solo se registra si está activo).
    private val _tiltEnabled = MutableStateFlow(true)
    val tiltEnabled: StateFlow<Boolean> = _tiltEnabled.asStateFlow()

    /**
     * Avisos de reenganche encendidos (P-166, 2026-09-04). **Segunda puerta**: la primera es el
     * permiso del sistema, que el jugador concede a mano en el overlay «¡Sin vidas!». Esta es la que
     * puede cerrar sin salir del juego.
     */
    private val _notificationsEnabled = MutableStateFlow(true)
    val notificationsEnabled: StateFlow<Boolean> = _notificationsEnabled.asStateFlow()

    /**
     * **REDUCIR EFECTOS** (P-12, 2026-07-31): menos partículas, destellos y sacudidas. Sirve a dos
     * públicos a la vez — móviles justos de potencia y jugadores con sensibilidad al movimiento — y
     * por eso arranca respetando el ajuste del SISTEMA: si el teléfono tiene las animaciones
     * desactivadas en Accesibilidad, el juego entra en modo reducido sin que nadie lo pida. En
     * cuanto el jugador toca el interruptor, manda él (la preferencia deja de ser `null`).
     */
    private val _reducedFx = MutableStateFlow(false)
    val reducedFx: StateFlow<Boolean> = _reducedFx.asStateFlow()

    // ── CUPO DE ANUNCIOS DE MONEDAS (P-18) ───────────────────────────────────────────────────────
    // El botón de la barra no tenía límite: se podían encadenar anuncios y farmear teikoins sin
    // pasar por la tienda. Ahora hay tope diario + enfriamiento (`RewardedAdQuota`), y la UI enseña
    // lo que queda en vez de dejar un botón que a veces hace algo y a veces no (P-19).
    private val _adQuota = MutableStateFlow(com.cukiti.teikafusion.model.RewardedAdQuota.State())
    val adQuota: StateFlow<com.cukiti.teikafusion.model.RewardedAdQuota.State> = _adQuota.asStateFlow()

    // ── DOBLAR LA RECOMPENSA DEL NIVEL (P-20) ────────────────────────────────────────────────────
    // Monedas que el último nivel completado dio y que un anuncio puede DUPLICAR. Se limpia al
    // cobrarlo o al salir de la pantalla de victoria, así que no puede cobrarse dos veces ni
    // arrastrarse al nivel siguiente.
    private val _pendingDoubleCoins = MutableStateFlow(0)
    val pendingDoubleCoins: StateFlow<Int> = _pendingDoubleCoins.asStateFlow()

    /** Cobra la duplicación (llamar SOLO desde el callback de recompensa del anuncio). */
    fun claimDoubledLevelCoins() {
        val extra = _pendingDoubleCoins.value
        if (extra <= 0) return
        _pendingDoubleCoins.value = 0
        grantTeikoins(extra)
        Analytics.trackRewardedAdWatched("nivel_x2", extra)
    }

    /** El jugador pasa de la oferta (o cierra la victoria): la duplicación caduca. */
    fun dismissDoubleCoins() { _pendingDoubleCoins.value = 0 }

    /** ¿Se le puede ofrecer AHORA un anuncio de monedas? (cupo + enfriamiento). */
    fun canWatchCoinAd(nowMs: Long = System.currentTimeMillis()): Boolean =
        com.cukiti.teikafusion.model.RewardedAdQuota.canWatch(_adQuota.value, nowMs)

    /** Anota que el jugador acaba de ver un anuncio de monedas (gasta cupo y arranca el enfriamiento). */
    fun consumeCoinAdQuota(nowMs: Long = System.currentTimeMillis()) {
        val next = com.cukiti.teikafusion.model.RewardedAdQuota.consume(_adQuota.value, nowMs)
        _adQuota.value = next
        viewModelScope.launch { prefs.saveAdQuota(next) }
    }

    // Master mute (botón rápido 🔊/🔇): silencia todo sin perder los niveles de los sliders.
    private val _isMuted = MutableStateFlow(false)
    val isMuted: StateFlow<Boolean> = _isMuted.asStateFlow()

    // Tutorial: true mientras el jugador no lo haya completado
    private val _showTutorial = MutableStateFlow(false)
    val showTutorial: StateFlow<Boolean> = _showTutorial.asStateFlow()

    // Victorias de nivel CONSECUTIVAS de la sesión (reveal estilo Block Blast "Consecutive Victories").
    // De sesión (NO se persiste): +1 al completar un nivel, se resetea al ir a HOME o perder.
    private val _consecutiveWins = MutableStateFlow(0)
    val consecutiveWins: StateFlow<Int> = _consecutiveWins.asStateFlow()

    // Racha PERSISTENTE de victorias de niveles (2026-07-20): sube al ganar, se corta al perder,
    // sobrevive a sesiones (DataStore). La mejor racha y el mejor combo alimentan los LOGROS.
    private val _winStreak = MutableStateFlow(0)
    val winStreak: StateFlow<Int> = _winStreak.asStateFlow()
    private val _bestWinStreak = MutableStateFlow(0)
    val bestWinStreak: StateFlow<Int> = _bestWinStreak.asStateFlow()
    private val _bestCombo = MutableStateFlow(0)
    val bestCombo: StateFlow<Int> = _bestCombo.asStateFlow()
    // Racha diaria
    private val _dailyStreak = MutableStateFlow(0)
    val dailyStreak: StateFlow<Int> = _dailyStreak.asStateFlow()
    // Recompensa de racha recién otorgada hoy (para el banner de bienvenida); null = nada que mostrar.
    // Celebración de racha diaria en Home (valor = racha a celebrar; null = nada que celebrar).
    // Se dispara UNA vez por día nuevo con racha real (≥2). Sin moneda: la economía tiburón sigue.
    private val _dailyStreakCelebration = MutableStateFlow<Int?>(null)
    val dailyStreakCelebration: StateFlow<Int?> = _dailyStreakCelebration.asStateFlow()
    fun consumeDailyStreakCelebration() { _dailyStreakCelebration.value = null }

    /**
     * **La fanfarria de la racha, esperando a que se vea su ventana** (2026-09-04, pedido del
     * usuario).
     *
     * La racha se calcula en el arranque del ViewModel, o sea **con el splash puesto**, y su
     * celebracion tiene dos caras y las dos viven en HOME: el banner de «Dia N» y, los dias de
     * hito, el cofre de vidas infinitas. Tocar el cue ahi mismo era el «sonido de logro sin
     * ventana» que se oia mientras cargaba la barra.
     *
     * Asi que el arranque **apunta** la fanfarria y la UI la cobra cuando la celebracion esta de
     * verdad en pantalla. Vale para las dos caras: quien la consume es el que la ve.
     */
    private val _pendingStreakFanfare = MutableStateFlow(false)
    val pendingStreakFanfare: StateFlow<Boolean> = _pendingStreakFanfare.asStateFlow()
    fun consumeStreakFanfare() { _pendingStreakFanfare.value = false }

    // V-03: subida de rango — overlay global (AppNavigation). Null = sin celebración pendiente.
    private val _rankUpCelebration =
        MutableStateFlow<com.cukiti.teikafusion.model.RankInfo?>(null)
    val rankUpCelebration:
        StateFlow<com.cukiti.teikafusion.model.RankInfo?> = _rankUpCelebration.asStateFlow()
    fun consumeRankUpCelebration() { _rankUpCelebration.value = null }

    // Récord de puntuación: XP una sola vez por ronda al superar el highScore de al arrancar.
    private var personalScoreRecordFloor = 0
    private var personalScoreRecordXpGiven = false
    private val xpMutex = Mutex()

    private val _wildcardSelectionsLeft = MutableStateFlow(0)
    val wildcardSelectionsLeft: StateFlow<Int> = _wildcardSelectionsLeft.asStateFlow()

    private val _remoteConfig = MutableStateFlow(RemoteConfigSnapshot.DEFAULTS)
    val remoteConfig: StateFlow<RemoteConfigSnapshot> = _remoteConfig.asStateFlow()

    private val _showLeaderboard = MutableStateFlow(false)
    val showLeaderboard: StateFlow<Boolean> = _showLeaderboard.asStateFlow()

    private val _leaderboardEntries = MutableStateFlow<List<com.cukiti.teikafusion.model.LeaderboardEntry>>(emptyList())
    val leaderboardEntries: StateFlow<List<com.cukiti.teikafusion.model.LeaderboardEntry>> = _leaderboardEntries.asStateFlow()

    // (RETIRADO 2026-08-09) `_leaderboardXpEntries`: la pestaña XP del ranking se eliminó por
    // decisión del usuario y con ella su consulta. El ranking global es UNA tabla, la de NIVEL.

    private val _leaderboardLoading = MutableStateFlow(false)
    val leaderboardLoading: StateFlow<Boolean> = _leaderboardLoading.asStateFlow()

    private val _leaderboardError = MutableStateFlow(false)
    val leaderboardError: StateFlow<Boolean> = _leaderboardError.asStateFlow()

    // El ranking exige una cuenta respaldada con Google: un anónimo NO tiene sesión en la nube,
    // así que abrir el ranking le muestra un panel "vincula para competir" en vez de una sesión vacía.
    private val _leaderboardRequiresLink = MutableStateFlow(false)
    val leaderboardRequiresLink: StateFlow<Boolean> = _leaderboardRequiresLink.asStateFlow()


    // ── Revelado de «EL ABISMO» en ELIGE TU MUNDO ─────────────────────────────────
    // La tarjeta del próximo mundo solo EXISTE tras superar el último nivel (eso lo decide el
    // propio mapa con maxUnlockedLevel). Este flag solo dice si toca el destello de estreno.
    private val _abyssCardRevealSeen = MutableStateFlow(true)   // true hasta cargar prefs: no parpadea
    val abyssCardRevealSeen: StateFlow<Boolean> = _abyssCardRevealSeen.asStateFlow()

    /** El destello de estreno de la tarjeta del Abismo ya se reprodujo: en adelante sale en reposo. */
    // ── P-369 · «Reducir efectos» automático si el juego va a tirones SOSTENIDOS (2026-09-30) ─────────
    // La medición la hace `JankWatchDriver` (solo en partida) con la regla de [JankWatch]; aquí se actúa
    // UNA sola vez por aparato: si el jugador vuelve a quitarlo, el juego no insiste.
    private val _autoReducedFxDone = MutableStateFlow(true)   // true hasta cargar prefs: no mide a ciegas
    val autoReducedFxDone: StateFlow<Boolean> = _autoReducedFxDone.asStateFlow()
    private val _perfNotice = MutableStateFlow<String?>(null)
    /** Aviso de que se activó solo (banda superior, no bloquea). */
    val perfNotice: StateFlow<String?> = _perfNotice.asStateFlow()

    fun consumePerfNotice() { _perfNotice.value = null }

    /** El juego lleva un rato claramente por debajo de lo jugable: activa «Reducir efectos» y lo dice. */
    fun onSustainedJank() {
        if (_autoReducedFxDone.value || _reducedFx.value) return
        _autoReducedFxDone.value = true
        viewModelScope.launch { prefs.saveAutoReducedFxDone(true) }
        setReducedFx(true)
        _perfNotice.value = "El juego iba a tirones: hemos activado «Reducir efectos». Puedes quitarlo en Ajustes."
    }

    fun markAbyssCardRevealSeen() {
        if (_abyssCardRevealSeen.value) return
        _abyssCardRevealSeen.value = true
        viewModelScope.launch { prefs.saveAbyssCardRevealSeen(true) }
    }
    private val _isSavingName = MutableStateFlow(false)
    val isSavingName: StateFlow<Boolean> = _isSavingName.asStateFlow()

    private val _displayName = MutableStateFlow("")
    val displayName: StateFlow<String> = _displayName.asStateFlow()

    private val _playerProfileLoaded = MutableStateFlow(false)
    val playerProfileLoaded: StateFlow<Boolean> = _playerProfileLoaded.asStateFlow()

    private val _initialAccountSyncFinished = MutableStateFlow(false)
    val initialAccountSyncFinished: StateFlow<Boolean> = _initialAccountSyncFinished.asStateFlow()

    // Consentimiento versionado de los documentos de la app. Es independiente del consentimiento
