    /** Ya se ha medido este arranque: la Activity puede recrearse, el proceso no. */
    @Volatile private var startupReported = false

    fun finishSplash() {
        // P-179 · La única medida de arranque que existe. Se reporta UNA vez por proceso: recrear la
        // Activity (girar el móvil, volver de segundo plano) vuelve a pasar por aquí y mediría un
        // arranque que no ha ocurrido.
        if (!startupReported) {
            startupReported = true
            val started = com.cukiti.teikafusion.TeikaFusionApp.processStartMs
            if (started > 0L) {
                val ms = android.os.SystemClock.elapsedRealtime() - started
                android.util.Log.i("GameViewModel", "Arranque: ${'$'}ms ms hasta Inicio")
                Analytics.trackStartupReady(ms, cold = true)
            }
        }
        if (_legalConsentAccepted.value && _showTutorial.value) {
            startGame(com.cukiti.teikafusion.model.TutorialCampaign.FIRST_LEVEL)
        } else {
            _gameState.update { it.copy(status = com.cukiti.teikafusion.model.GameStatus.HOME) }
        }
        // El playerId es el UID de Firebase, o vacío mientras no haya sesión; el observador del UID
        // (en init) lo resuelve cuando la auth se confirme.
        viewModelScope.launch(kotlinx.coroutines.Dispatchers.IO) {
            _playerId.value = com.cukiti.teikafusion.data.PlayerOverrideManager.getPlayerId().orEmpty()
        }
    }

