    fun selectReactorGroup(origin: Position) {
        if(_reactorAim.value==null) return
        val s=_gameState.value
        if(s.status!=com.cukiti.teikafusion.model.GameStatus.PLAYING) return
        val plan=ReactorRules.plan(s,teikaBlockedCells(),origin)
        val feedback=when {
            origin in ReactorRules.blocked(s,teikaBlockedCells()) -> "Casilla protegida"
            s.grid[origin] !is CellContent.Wood -> "Toca un bloque de color"
            plan==null -> "Necesitas 3 del mismo color"
            else -> "${plan.cells.size} bloques conectados"
        }
        _reactorAim.value=ReactorAim(origin,feedback)
    }
    fun previewReactor(): ReactorPlan? = _reactorAim.value?.origin?.let {
        ReactorRules.plan(_gameState.value,teikaBlockedCells(),it)
    }
    fun confirmReactor(): Job = launchRoundJob {
        var committed=false
        var durationMs=0L
        try {
            gameMutex.withLock {
                val s=_gameState.value
                if(!s.reactorCharged || s.reactorPending || !ReactorRules.appliesTo(s.level) ||
                    s.status!=com.cukiti.teikafusion.model.GameStatus.PLAYING) return@withLock
                val plan=previewReactor() ?: return@withLock
                val originals=plan.cells.map { it to (s.grid.getValue(it) as CellContent.Wood) }
                val grid=s.grid.toMutableMap(); val collected=s.targetsCollected.toMutableMap()
                val events=s.events.toMutableList(); val reduced=_reducedFx.value
                durationMs=if(reduced) 120L else plan.durationMs.toLong()
                originals.forEachIndexed { i,(p,w) ->
                    grid[p]=CellContent.Empty
                    w.targetColor?.let { t ->
                        collected[t]=(collected[t] ?: 0)+1
                        events.add(GameEvent.TargetCollected(t,p,delayMs=if(reduced) 0 else plan.hit(i)))
                    }
                }
                val beforeIds=physicsWorld.snapshot().mapTo(HashSet()) { it.id }
                val seeds=originals.filter { it.second.teikaSeed }
                // Each selected seed has a cleared, body-free cell. Keep all other wood intact.
                val protected=ReactorRules.blocked(s,teikaBlockedCells()) + grid.filterValues { it is CellContent.Wood }.keys
                seeds.forEach { (p,_) ->
                    events.add(GameEvent.TeikaSeedBurst(p,1,delayMs=if(reduced) 0 else plan.hit(plan.cells.indexOf(p))))
                    spawnLineClearTeika(grid,events,collected,p.x+.5f,p.y+.5f,alongX=true,
                        protectedCells=protected,type=TeikaType.TEIKA_1)
                }
                val born=physicsWorld.snapshot().filter { it.id !in beforeIds }.map { it.id }
                events.add(GameEvent.RulePulse("reactor",plan.cells,points=listOf(plan.cells.first()),moves=plan.links,
                    wood=originals,hitTimes=plan.cells.indices.map { if(reduced) 0 else plan.hit(it) },
                    bodyIds=born,durationMs=durationMs.toInt()))
                val stats=s.teikasCreatedInLevel.toMutableMap()
                if(born.isNotEmpty()) stats[TeikaType.TEIKA_1]=(stats[TeikaType.TEIKA_1] ?: 0)+born.size
                _reactorAim.value=null; reactorAimBusy=false; committed=true
                holdRulePhysics(durationMs)
                _gameState.value=s.copy(grid=grid,targetsCollected=collected,teikasCreatedInLevel=stats,
                    reactorCharged=false,reactorPending=true,events=events)
                saveCurrentState(_gameState.value)
                soundManager.playRuleCue(if(reduced) "reactor_reduced" else "reactor",lastHitMs=plan.hit(plan.cells.lastIndex))
                if(seeds.isNotEmpty()) soundManager.playTeikaSeedBreak(if(reduced) 0 else plan.hit(plan.cells.lastIndex).toLong())
            }
            if(!committed) return@launchRoundJob
            kotlinx.coroutines.delay(durationMs)
            while(_gameState.value.status==com.cukiti.teikafusion.model.GameStatus.PAUSED) kotlinx.coroutines.delay(100L)
            if(_gameState.value.status==com.cukiti.teikafusion.model.GameStatus.PLAYING) resolveBoardChain(initialDelayMs=0L)
            finishPendingBoardTools(elapsedFxMs=durationMs)
            markUnplayableTrayPieces()
            saveCurrentState(_gameState.value)
        } finally {
            if(committed) boardBusyExit()
        }
    }

    /** Reactor has already paid its stars/seeds before saving; recovery only acknowledges completion. */
    private suspend fun finishPendingBoardTools(elapsedFxMs: Long=0L) = gameMutex.withLock {
        // Preserve events concurrently retired by their UI owners. Completion scheduling is idempotent.
        _gameState.update { s ->
            val completed=s.copy(forgePending=false,compactorPending=false,orbitPending=false,portalSwapPending=false,reactorPending=false,ballPending=false)
            if(s.forgePending || s.reactorPending || s.ballPending) checkObjectiveCompletion(completed,elapsedFxMs) else completed
        }
    }

    private val _orbitAim = MutableStateFlow<OrbitAim?>(null)
    val orbitAim = _orbitAim.asStateFlow()
    private var orbitAimBusy=false
    private fun orbitBodyCells() = OrbitRules.bodyCells(physicsWorld.snapshot().map(::clawSave),_gameState.value.gridW,_gameState.value.gridH)
    fun beginOrbitAim(): Boolean {
        val s=_gameState.value
        if(!OrbitRules.appliesTo(s.level) || !s.orbitCharged || pinballInputLocked() ||
            s.status!=com.cukiti.teikafusion.model.GameStatus.PLAYING || _boardBusy.value ||
            workshopActive || workshopCraftInFlight || companionAbilityInFlight || floraProjectileId!=null ||
            _dragState.value !is DragState.Idle || clockMs()<rulePhysicsHoldUntilMs) return false
        _teikaBodies.value=physicsWorld.snapshot()
        boardBusyEnter(); orbitAimBusy=true
        _orbitAim.value=OrbitAim(feedback=if(OrbitRules.hasMove(s,orbitBodyCells())) "Elige una zona" else "Sin zonas disponibles")
        return true
    }
    fun cancelOrbitAim() {
        _orbitAim.value=null
        if(orbitAimBusy) { orbitAimBusy=false; boardBusyExit() }
    }
    fun selectOrbitZone(center: Position) {
        val a=_orbitAim.value ?: return
        val s=_gameState.value
        if(s.status!=com.cukiti.teikafusion.model.GameStatus.PLAYING) return
        _orbitAim.value=a.copy(center=center,feedback=OrbitRules.error(s,orbitBodyCells(),center,a.clockwise) ?: "Listo para girar")
    }
    fun toggleOrbitDirection() {
        val a=_orbitAim.value ?: return
        _orbitAim.value=a.copy(clockwise=!a.clockwise)
        a.center?.let(::selectOrbitZone)
    }
    fun previewOrbit(): OrbitPlan? {
        val a=_orbitAim.value ?: return null
        return OrbitRules.plan(_gameState.value,orbitBodyCells(),a.center ?: return null,a.clockwise)
    }
    fun confirmOrbit() = launchRoundJob {
        var committed=false
        var landed=emptySet<Position>()
        var duration=0L
        try {
            gameMutex.withLock {
                val s=_gameState.value
                if(!orbitAimBusy || !s.orbitCharged || s.orbitPending || !OrbitRules.appliesTo(s.level) ||
                    s.status!=com.cukiti.teikafusion.model.GameStatus.PLAYING) return@withLock
                val plan=previewOrbit() ?: return@withLock
                val grid=OrbitRules.apply(s.grid,plan).mapValues { (p,c) ->
                    if(p in plan.cells && c is CellContent.Wood) c.copy(skipSpawnAnimation=true) else c
                }
                landed=plan.moves.mapTo(HashSet()) { it.second }
                val reduced=_reducedFx.value
                duration=if(reduced) 120L else OrbitRules.TOTAL_MS.toLong()
                val events=plan.moves.map { (from,to) ->
                    val w=s.grid.getValue(from) as CellContent.Wood
                    GameEvent.WoodFall(from,to,w.colorType,targetColor=w.targetColor,wood=w,slide=true,
                        orbitCenter=plan.center,orbitClockwise=plan.clockwise,
                        delayMs=if(reduced) 0 else OrbitRules.PREPARE_MS,durationMs=if(reduced) 120 else OrbitRules.MOVE_MS)
                }+GameEvent.RulePulse("orbit",plan.cells,points=listOf(plan.center),direction=if(plan.clockwise) 1 else -1,
                    hitTimes=listOf(if(reduced) 0 else 820),durationMs=duration.toInt())
                // Keep a concurrently consumed event retired; never overwrite a concurrent pause.
                _gameState.update { latest -> latest.copy(grid=grid,orbitCharged=false,orbitPending=true,
                    hiddenWoodCells=latest.hiddenWoodCells+landed,events=latest.events+events) }
                committed=true; _orbitAim.value=null; orbitAimBusy=false
                holdRulePhysics(duration)
                soundManager.playRuleCue(if(reduced) "orbit_reduced" else "orbit")
                saveCurrentState(_gameState.value)
            }
            if(!committed) return@launchRoundJob
            kotlinx.coroutines.delay(duration)
            _gameState.update { it.copy(hiddenWoodCells=it.hiddenWoodCells-landed) }
            while(_gameState.value.status==com.cukiti.teikafusion.model.GameStatus.PAUSED) kotlinx.coroutines.delay(100L)
            if(_gameState.value.status==com.cukiti.teikafusion.model.GameStatus.PLAYING) resolveBoardChain(initialDelayMs=0L)
            finishPendingBoardTools()
            markUnplayableTrayPieces(); saveCurrentState(_gameState.value)
        } finally { if(committed) boardBusyExit() }
    }

    private val _portalSwapAim = MutableStateFlow<PortalSwapAim?>(null)
    val portalSwapAim: StateFlow<PortalSwapAim?> = _portalSwapAim.asStateFlow()
    private var portalSwapAimBusy = false
    fun beginPortalSwapAim(): Boolean {
        val s=_gameState.value
        if(!PortalSwapRules.appliesTo(s.level) || !s.portalSwapCharged || pinballInputLocked() ||
            s.status!=com.cukiti.teikafusion.model.GameStatus.PLAYING || _boardBusy.value ||
            workshopActive || workshopCraftInFlight || companionAbilityInFlight || floraProjectileId!=null ||
            _dragState.value !is DragState.Idle || clockMs()<rulePhysicsHoldUntilMs) return false
        _teikaBodies.value=physicsWorld.snapshot()
        _portalSwapAim.value=PortalSwapAim(feedback=if(PortalSwapRules.hasMove(s,teikaBlockedCells())) "Toca la esquina de la zona" else "No hay dos zonas disponibles")
        boardBusyEnter(); portalSwapAimBusy=true
        return true
    }
    fun cancelPortalSwapAim() {
        _portalSwapAim.value=null
        if(portalSwapAimBusy) { portalSwapAimBusy=false; boardBusyExit() }
    }
    fun selectPortalSwapZone(anchor: Position) {
        val aim=_portalSwapAim.value ?: return
        val s=_gameState.value
        if(s.status!=com.cukiti.teikafusion.model.GameStatus.PLAYING) return
        val bodies=teikaBlockedCells()
        PortalSwapRules.zoneError(s,bodies,anchor)?.let { _portalSwapAim.value=aim.copy(feedback=it); return }
        if(aim.first==null || aim.second!=null) {
            _portalSwapAim.value=PortalSwapAim(first=anchor,feedback="Elige otra zona de 2×2"); return
        }
        PortalSwapRules.error(s,bodies,aim.first,anchor)?.let { _portalSwapAim.value=aim.copy(feedback=it); return }
        _portalSwapAim.value=aim.copy(second=anchor,feedback="Vista previa del intercambio")
    }
    fun previewPortalSwap(): PortalSwapPlan? {
        val aim=_portalSwapAim.value ?: return null
        return PortalSwapRules.plan(_gameState.value,teikaBlockedCells(),aim.first ?: return null,aim.second ?: return null)
    }
    fun confirmPortalSwap(): Job = launchRoundJob {
        var committed=false
        var landed=emptySet<Position>()
        var durationMs=0L
        try {
            gameMutex.withLock {
                val s=_gameState.value
                if(!s.portalSwapCharged || s.portalSwapPending || !PortalSwapRules.appliesTo(s.level) ||
                    s.status!=com.cukiti.teikafusion.model.GameStatus.PLAYING) return@withLock
                val plan=previewPortalSwap() ?: return@withLock
                val carried=plan.moves.map { it to (s.grid.getValue(it.first) as CellContent.Wood) }
                val grid=PortalSwapRules.apply(s.grid,plan).mapValues { (_,c) -> if(c is CellContent.Wood && carried.any { it.second.id==c.id }) c.copy(skipSpawnAnimation=true) else c }
                landed=plan.moves.mapTo(HashSet()) { it.second }
                val reduced=_reducedFx.value
                durationMs=if(reduced) 120L else PortalSwapRules.TOTAL_MS.toLong()
                val events=s.events.toMutableList()
                carried.forEach { (m,w) ->
                    val forward=m.first in PortalSwapRules.cells(plan.first)
                    events.add(GameEvent.WoodFall(from=m.first,to=m.second,colorType=w.colorType,wood=w,
                        targetColor=w.targetColor,poisoned=w.poisoned,armor=w.armor,slide=true,
                        portalOrigin=if(forward) plan.first else plan.second,portalDestination=if(forward) plan.second else plan.first,
                        delayMs=if(reduced) 0 else PortalSwapRules.PREPARE_MS,
                        durationMs=if(reduced) 120 else PortalSwapRules.TRANSFER_MS))
                }
                events.add(GameEvent.RulePulse("portal_swap",plan.cells,points=listOf(plan.first,plan.second),moves=plan.moves,
                    hitTimes=listOf(if(reduced) 0 else 780),durationMs=durationMs.toInt()))
                _portalSwapAim.value=null; portalSwapAimBusy=false // busy ownership transfers to this job
                committed=true
                holdRulePhysics(durationMs)
                _gameState.value=s.copy(grid=grid,portalSwapCharged=false,portalSwapPending=true,
                    hiddenWoodCells=s.hiddenWoodCells+landed,events=events)
                soundManager.playRuleCue(if(reduced) "portal_swap_reduced" else "portal_swap")
                saveCurrentState(_gameState.value)
            }
            if(!committed) return@launchRoundJob
            kotlinx.coroutines.delay(durationMs)
            _gameState.update { it.copy(hiddenWoodCells=it.hiddenWoodCells-landed) }
            while(_gameState.value.status==com.cukiti.teikafusion.model.GameStatus.PAUSED) kotlinx.coroutines.delay(100L)
            if(_gameState.value.status==com.cukiti.teikafusion.model.GameStatus.PLAYING) resolveBoardChain(initialDelayMs=0L)
            _gameState.update { it.copy(portalSwapPending=false) }
            markUnplayableTrayPieces()
            saveCurrentState(_gameState.value)
        } finally {
            if(committed) boardBusyExit()
            // An invalid confirmation keeps selection and charge; cancellation is always explicit.
        }
    }

    private val _compactorAiming = MutableStateFlow(false)
    val compactorAiming: StateFlow<Boolean> = _compactorAiming.asStateFlow()
    private var compactorAimBusy = false
    fun beginCompactorAim(): Boolean {
        val s=_gameState.value
        if(!CompactorRules.appliesTo(s.level) || !s.compactorCharged || pinballInputLocked() ||
            s.status!=com.cukiti.teikafusion.model.GameStatus.PLAYING || _boardBusy.value ||
            workshopActive || workshopCraftInFlight || companionAbilityInFlight || floraProjectileId!=null ||
            _dragState.value !is DragState.Idle || clockMs()<rulePhysicsHoldUntilMs) return false
        _compactorAiming.value=true
        _teikaBodies.value=physicsWorld.snapshot()
        boardBusyEnter(); compactorAimBusy=true
        return true
    }
    fun cancelCompactorAim() {
        _compactorAiming.value=false
        if(compactorAimBusy) { compactorAimBusy=false; boardBusyExit() }
    }
    fun previewCompactor(x: Int,y: Int,direction: Int): CompactorPlan? {
        if(!_compactorAiming.value) return null
        return CompactorRules.plan(_gameState.value,teikaBlockedCells(),x,y,direction)
    }
    fun releaseCompactor(x: Int,y: Int,direction: Int): Job = launchRoundJob {
        var committed=false
        var landed=emptySet<Position>()
        var durationMs=0L
        try {
            gameMutex.withLock {
                val s=_gameState.value
                if(!_compactorAiming.value || !s.compactorCharged || s.compactorPending ||
                    !CompactorRules.appliesTo(s.level) || s.status!=com.cukiti.teikafusion.model.GameStatus.PLAYING) return@withLock
                val plan=CompactorRules.plan(s,teikaBlockedCells(),x,y,direction) ?: return@withLock
                if(plan.moves.isEmpty()) return@withLock
                val grid=s.grid.toMutableMap()
                val carried=plan.moves.map { it to (grid.getValue(it.first) as CellContent.Wood) }
                carried.forEach { (move,_) -> grid[move.first]=CellContent.Empty }
                carried.forEach { (move,w) -> grid[move.second]=w.copy(skipSpawnAnimation=true) }
                landed=plan.moves.mapTo(HashSet()) { it.second }
                val events=s.events.toMutableList()
                val reduced=_reducedFx.value
                durationMs=if(reduced) 120L else CompactorRules.TOTAL_MS.toLong()
                carried.forEach { (move,w) -> events.add(GameEvent.WoodFall(from=move.first,to=move.second,
                    colorType=w.colorType,wood=w,targetColor=w.targetColor,poisoned=w.poisoned,armor=w.armor,
                    delayMs=if(reduced) 0 else CompactorRules.PREPARE_MS,
                    durationMs=if(reduced) 120 else CompactorRules.MOVE_MS,slide=true)) }
                events.add(GameEvent.RulePulse("compactor",plan.cells,moves=plan.moves,direction=direction,hitTimes=listOf(if(reduced) 0 else 800),
                    durationMs=if(reduced) 120 else CompactorRules.TOTAL_MS))
                _compactorAiming.value=false; compactorAimBusy=false // transfer the busy ownership to this job
                committed=true
                holdRulePhysics(durationMs)
                _gameState.value=s.copy(grid=grid,compactorCharged=false,compactorPending=true,
                    hiddenWoodCells=s.hiddenWoodCells+landed,events=events)
                soundManager.playRuleCue("compactor")
                saveCurrentState(_gameState.value)
            }
            if(!committed) return@launchRoundJob
            kotlinx.coroutines.delay(durationMs)
            _gameState.update { it.copy(hiddenWoodCells=it.hiddenWoodCells-landed) }
            // Pausing retains the committed board and pending chain, without granting a new charge.
            while(_gameState.value.status==com.cukiti.teikafusion.model.GameStatus.PAUSED) kotlinx.coroutines.delay(100L)
            if(_gameState.value.status==com.cukiti.teikafusion.model.GameStatus.PLAYING) resolveBoardChain(initialDelayMs=0L)
            _gameState.update { it.copy(compactorPending=false) }
            markUnplayableTrayPieces()
            saveCurrentState(_gameState.value)
        } finally {
            if(committed) boardBusyExit() else cancelCompactorAim()
        }
    }

    private var pinballAimBodyId: String? = null
    private var pinballAimBusy=false
    private var pinballFlightBusy=false
    private fun pinballInputLocked() = _forgeAim.value!=null || _gameState.value.forgePending || _turbineAim.value!=null || _gameState.value.turbineGust!=null || _clawAim.value!=null || _gameState.value.clawTrip!=null || _ballAim.value!=null || _gameState.value.ballPending || _reactorAim.value!=null || _gameState.value.reactorPending || pinballAimBodyId!=null || _gameState.value.pinballFlight!=null || _compactorAiming.value || _gameState.value.compactorPending || _orbitAim.value!=null || _portalSwapAim.value!=null || _gameState.value.orbitPending || _gameState.value.portalSwapPending

    fun beginPinballAim(id: String): Boolean {
        val s=_gameState.value
        if(!PinballRules.appliesTo(s.level) || !s.pinballCharged || pinballInputLocked() ||
            s.status!=com.cukiti.teikafusion.model.GameStatus.PLAYING || _boardBusy.value ||
            workshopActive || workshopCraftInFlight || companionAbilityInFlight || floraProjectileId!=null ||
            _dragState.value !is DragState.Idle || clockMs()<rulePhysicsHoldUntilMs) return false
        val b=physicsWorld.getBody(id) ?: return false
        if(b.frozenTurns>0 || b.kinematic || b.bubble>0) return false
        pinballAimBodyId=id
        _teikaBodies.value=physicsWorld.snapshot()
        boardBusyEnter(); pinballAimBusy=true
        return true
    }
    fun cancelPinballAim() {
        pinballAimBodyId=null
        if(pinballAimBusy) { pinballAimBusy=false; boardBusyExit() }
    }
    fun releasePinball(id: String,pullX: Float,pullY: Float) {
        if(pinballAimBodyId!=id) return
        cancelPinballAim()
        val velocity=PinballRules.velocity(pullX,pullY) ?: return
        launchRoundJob {
            gameMutex.withLock {
                val s=_gameState.value
                if(!PinballRules.appliesTo(s.level) || !s.pinballCharged || s.pinballFlight!=null ||
                    s.status!=com.cukiti.teikafusion.model.GameStatus.PLAYING || _boardBusy.value ||
                    workshopActive || workshopCraftInFlight || companionAbilityInFlight || floraProjectileId!=null || _dragState.value !is DragState.Idle) return@withLock
                if(!physicsWorld.launchPinball(PinballFlight(id,velocity.first,velocity.second))) return@withLock
                boardBusyEnter(); pinballFlightBusy=true
                _gameState.value=s.copy(pinballCharged=false,pinballFlight=physicsWorld.pinballSnapshot())
                soundManager.playRuleCue("pinball_launch")
                saveCurrentState(_gameState.value)
            }
        }
    }
    private fun pinballProtected(s: GameState) = s.unplaceableCells+s.gluttonDeadCells.keys+s.frozenCells+
        s.glacierFrostCells+s.starAstroTargetCells+s.starAstroMoonWoodCells+s.hiddenWoodCells+lavaCoveredCells(s)
    private suspend fun commitPinballFrame(before: GameState) {
        val impacts=physicsWorld.drainPinballImpacts()
        val contacts=physicsWorld.drainPinballContacts()
        val flight=physicsWorld.pinballSnapshot()
        var ended=false
        gameMutex.withLock {
            val s=_gameState.value
            if(!PinballRules.appliesTo(s.level) || s.status!=com.cukiti.teikafusion.model.GameStatus.PLAYING) return@withLock
            if(s.pinballFlight==null && impacts.isEmpty() && contacts.isEmpty()) return@withLock
            // Flight position stays in the body flow; do not recompose the whole screen every tick.
            // The central save stamp reads the exact live velocity and remaining simulation time.
            if(flight!=null && impacts.isEmpty() && contacts.isEmpty() && flight.bouncesLeft==s.pinballFlight?.bouncesLeft) return@withLock
            val blocked=pinballProtected(s)
            val grid=s.grid.toMutableMap(); val collected=s.targetsCollected.toMutableMap(); val events=s.events.toMutableList()
            impacts.forEach { p ->
                val wood=grid[p]
                if(!PinballRules.canBreak(wood,p in blocked) || (wood as? CellContent.Wood)?.id!=(before.grid[p] as? CellContent.Wood)?.id) return@forEach
                wood as CellContent.Wood
                grid[p]=CellContent.Empty
                wood.targetColor?.let { t -> collected[t]=(collected[t] ?: 0)+1; events.add(GameEvent.TargetCollected(t,p)) }
                events.add(GameEvent.LineCellShatter(p,wood.colorType,targetColor=null))
            }
            contacts.forEach { (x,y,id) -> events.add(GameEvent.PinballImpact(x,y,id)) }
            ended=s.pinballFlight!=null && flight==null
            _gameState.value=checkObjectiveCompletion(s.copy(grid=grid,targetsCollected=collected,events=events,pinballFlight=flight))
            if(contacts.isNotEmpty()) soundManager.playRuleCue("pinball_hit")
        }
        if(ended) {
            if(pinballFlightBusy) { pinballFlightBusy=false; boardBusyExit() }
            saveCurrentState(_gameState.value); markUnplayableTrayPieces()
        }
    }

    private suspend fun tickReplacementRules() {
        refreshRoutesAndReserve()

        var presentation = false
        gameMutex.withLock {
            val s = _gameState.value
            if (s.status != com.cukiti.teikafusion.model.GameStatus.PLAYING || !ConstellationRules.appliesTo(s.level)) return@withLock
            val grid = s.grid.toMutableMap()
            val blocked = s.unplaceableCells + teikaBlockedCells() + lavaCoveredCells(s)
            fun free() = grid.filterValues { it is CellContent.Empty }.keys - blocked
            if (s.constellationPoints.size == 3 && s.constellationCovered.containsAll(s.constellationPoints)) {
                val trace = ConstellationRules.trace(s.constellationPoints)
                val path = trace.distinct()
                val originals = path.mapNotNull { p -> (grid[p] as? CellContent.Wood)?.let { p to it } }
                presentation = true
                holdRulePhysics(ruleDuration(RuleMotion.CONSTELLATION_MS).toLong())
                val collected = s.targetsCollected.toMutableMap()
                val events = s.events.toMutableList()
                path.forEachIndexed { index, p ->
                    val hitAt = ruleHit(RuleMotion.constellationHit(trace.indexOf(p),trace.size))
                    val w = grid[p] as? CellContent.Wood ?: return@forEachIndexed
                    if (p in blocked || p in s.frozenCells || p in s.glacierFrostCells || w.coil > 0) return@forEachIndexed
                    when {
                        w.armor > 0 -> {
                            val left = w.armor - 1
                            grid[p] = w.copy(armor = left, rock = w.rock && left > 0)
                            if (left > 0) events.add(GameEvent.CrystalCrack(p, left,delayMs = hitAt))
                            else events.add(GameEvent.CrystalShatter(p, w.colorType,delayMs = hitAt))
                        }
                        w.poisoned -> { grid[p] = w.copy(poisoned = false); events.add(GameEvent.PoisonWash(p,delayMs = hitAt)) }
                        else -> {
                            grid[p] = CellContent.Empty
                            w.targetColor?.let { t -> collected[t] = (collected[t] ?: 0) + 1; events.add(GameEvent.TargetCollected(t, p, delayMs = hitAt)) }
                            events.add(GameEvent.LineCellShatter(p, w.colorType, delayMs = hitAt, targetColor = w.targetColor))
                        }
                    }
                }
                events.add(GameEvent.RulePulse("constellation",trace,points = s.constellationPoints,wood = originals,
                    hitTimes = trace.indices.map { ruleHit(RuleMotion.constellationHit(it,trace.size)) },durationMs = ruleDuration(RuleMotion.CONSTELLATION_MS)))
                val wave = s.constellationWave + 1
                _gameState.value = checkObjectiveCompletion(s.copy(grid = grid, targetsCollected = collected, events = events,
                    constellationPoints = ConstellationRules.points(s.level, wave, free(),grid.filterValues { it is CellContent.Wood }.keys), constellationCovered = emptySet(), constellationWave = wave))
                soundManager.playRuleCue("constellation")
            } else {
                val covered = s.constellationCovered intersect s.constellationPoints.toSet()
                val available = free()
                val kept = s.constellationPoints.filter { it in covered || it in available }
                val replacements = if (kept.size >= 3) emptyList() else ConstellationRules.points(s.level, s.constellationWave, available - kept.toSet(),grid.filterValues { it is CellContent.Wood }.keys)
                _gameState.value = s.copy(constellationPoints = kept + replacements.take(3 - kept.size), constellationCovered = covered)
            }
        }
        if (presentation) kotlinx.coroutines.delay(ruleDuration(RuleMotion.CONSTELLATION_MS).toLong())
    }

    /** Dónde se vio el imán por última vez: para avisar de su rotura aunque ya no esté. */
    private var lastSeenMagnetCell: Position? = null

    // ── P-366 · LA PARADA, UNA SOLA COPIA (2026-09-29) ─────────────────────────────────────────────
    // Las zonas de parada de P-353 vivían incrustadas en el tick. Aquí quedan las que no tenían función
    // propia en `model/`, y las usan a la vez [applyBiomeTick] y [parryForNextPlacement] (el bot): si
    // una cambia, cambia para los dos («dos copias de un dibujo» es el bug clásico de este repo).

    /** Lo que rompe una colocación, tal como lo miran los biomas para la parada. */
    internal data class ParryProbe(
        val rows: Set<Int>,
        val cols: Set<Int>,
        val cells: Set<Position>,
        val pieceId: String?,
    ) {
        val brokeLine: Boolean get() = rows.isNotEmpty() || cols.isNotEmpty()
    }

    /** Dojo: el tajo se para rompiendo una columna de la COSTURA (las dos del centro). */
    private fun ninjaSeamParried(cols: Set<Int>): Boolean =
        cols.any { it == NINJA_CUT_COL - 1 || it == NINJA_CUT_COL }

    /** Trono: la espada se para rompiendo una de sus dos líneas. */
    private fun kingSwordParried(axis: Int, line: Int, rows: Set<Int>, cols: Set<Int>): Boolean {
        if (axis == com.cukiti.teikafusion.model.KingSword.NONE) return false
        val lines = setOf(line, com.cukiti.teikafusion.model.KingSword.partner(line))
        return if (axis == com.cukiti.teikafusion.model.KingSword.ROW) rows.any { it in lines }
        else cols.any { it in lines }
    }

    /** Mansión: el destello se para rompiendo una línea entera DENTRO de la mitad que se refleja. */
    private fun ghostHalfParried(source: Int, rows: Set<Int>, cols: Set<Int>): Boolean {
        val half = GameState.GRID_SIZE / 2
        return when (source) {
            com.cukiti.teikafusion.model.HauntedMirror.NONE -> false
            com.cukiti.teikafusion.model.HauntedMirror.LEFT -> cols.any { it < half }
            com.cukiti.teikafusion.model.HauntedMirror.RIGHT -> cols.any { it >= half }
            com.cukiti.teikafusion.model.HauntedMirror.TOP -> rows.any { it < half }
            else -> rows.any { it >= half }
        }
    }

    /** Jardín: el Teika marcado o, sin Teika, la franja del borde marcado. `null` = aún sin marca. */
    private fun gardenParryZone(markTeikaId: String?, edge: PlantEdge?): Set<Position>? {
        val marked = markTeikaId?.let { id -> _teikaBodies.value.firstOrNull { it.id == id } }
        if (marked != null) return physicsWorld.occupiedCells().filterValues { it == marked.id }.keys
        return edge?.let { gardenEdgeBand(it) }
    }

    /** Cielo Estelar: las estrellas que marcó la Luna y el Teika que marcó el Sol. */
    private fun starParryZone(moonWoods: Set<Position>, targetTeikaId: String?): Set<Position> =
        moonWoods + (targetTeikaId?.let { id ->
            physicsWorld.occupiedCells().filterValues { it == id }.keys
        } ?: emptySet())

    /**
     * **P-366 · LA PARADA QUE BUSCA EL BOT.** Si la PRÓXIMA colocación es el golpe de algún bioma con
     * parada, devuelve la pregunta «¿esta jugada lo para?»; si no, `null`. Incluye echar la pieza del Rey
     * que se quedó en el tablero, que se puede hacer en cualquier turno.
     *
     * Las zonas son las mismas funciones que mira [applyBiomeTick]. Lo único que se repite aquí es el
     * «¿cae en la siguiente?»: el tick suma uno al contador y compara, así que aquí es contador + 1 ≥
     * umbral (el Glotón ya compara así en el tick). Solo lo usa el bot (`app/src/test/.../bot/`): el
     * jugador no tiene esta ayuda.
     */
    internal fun parryForNextPlacement(): ((ParryProbe) -> Boolean)? {
        val s = _gameState.value
        if (s.status != com.cukiti.teikafusion.model.GameStatus.PLAYING) return null
        val lv = s.level
        val checks = ArrayList<(ParryProbe) -> Boolean>(2)
        s.kingRestCell?.let { rest ->
            checks += { p -> com.cukiti.teikafusion.model.KingPiece.restFreedBy(rest, p.rows, p.cols) }
        }
        when (s.biomePrimary) {
            com.cukiti.teikafusion.model.BiomeType.SLEEP -> {
                val marked = s.drowsyMarkedId
                if (s.drowsyTurns == 0 && marked != null &&
                    s.sleepIdleTurns + 1 >= com.cukiti.teikafusion.model.BiomeCycle.strikeAt(lv)
                ) checks += { p -> p.pieceId == marked && p.brokeLine }
            }
            com.cukiti.teikafusion.model.BiomeType.NINJA -> {
                if (!s.ninjaCutActive && s.ninjaTruceTurns <= 0 &&
                    s.ninjaIdleTurns + 1 >= LevelDirector.ninjaCutThreshold(lv)
                ) checks += { p -> ninjaSeamParried(p.cols) }
            }
            com.cukiti.teikafusion.model.BiomeType.GARDEN -> {
                val zone = gardenParryZone(s.plantMarkTeikaId, s.plantMarkEdge)
                if (s.plantAbduction == null && zone != null &&
                    s.plantIdleTurns + 1 >= com.cukiti.teikafusion.model.BiomeCycle.strikeAt(lv)
                ) checks += { p -> zone.any { it in p.cells } }
            }
            com.cukiti.teikafusion.model.BiomeType.GALACTIC -> {
                val craters = listOfNotNull(s.meteorAt, s.meteorAt2)
                    .flatMap { com.cukiti.teikafusion.model.MeteorShower.craterCells(it) }.toSet()
                if (craters.isNotEmpty() &&
                    com.cukiti.teikafusion.model.BiomeCycle.advance(galacticIdleCounter) >= LevelDirector.meteorThreshold(lv)
                ) checks += { p -> craters.any { it in p.cells } }
            }
            com.cukiti.teikafusion.model.BiomeType.KING -> {
                if (s.kingSwordIdle + 1 >= LevelDirector.swordThreshold(lv)) {
                    val axis = s.kingSwordAxis; val line = s.kingSwordLine
                    val kind = s.kingPieceKind; val a = s.kingPieceA; val b = s.kingPieceB
                    val fromEnd = s.kingPieceFromEnd
                    checks += { p ->
                        kingSwordParried(axis, line, p.rows, p.cols) ||
                            com.cukiti.teikafusion.model.KingPiece.parriedBy(kind, a, b, fromEnd, p.rows, p.cols)
                    }
                }
            }
            com.cukiti.teikafusion.model.BiomeType.GLUTTON -> {
                val corner = s.gluttonCorner
                if (!gluttonFeastSinceTick && corner in 0..3 &&
                    s.gluttonCounter + 1 >= LevelDirector.gluttonBiteThreshold(lv)
                ) {
                    val cells = GameState.gluttonCornerCells(corner)
                    checks += { p -> cells.any { it in p.cells } }
                }
            }
            com.cukiti.teikafusion.model.BiomeType.GHOST -> {
                val source = s.mirrorSource
                if (source != com.cukiti.teikafusion.model.HauntedMirror.NONE &&
                    s.ghostIdleTurns + 1 >= LevelDirector.mirrorThreshold(lv)
                ) checks += { p -> ghostHalfParried(source, p.rows, p.cols) }
            }
            com.cukiti.teikafusion.model.BiomeType.STAR -> {
                val zone = starParryZone(s.starAstroMoonWoodCells, s.starAstroTargetTeikaId)
                if (!s.starAstroEmerged && s.starAstroCooldown <= 0 && zone.isNotEmpty() &&
                    s.starAstroIdleCounter + 1 >= LevelDirector.starIdleThreshold(lv)
                ) checks += { p -> zone.any { it in p.cells } }
            }
            com.cukiti.teikafusion.model.BiomeType.VOLCANO -> {
                val pressure = nextVolcanoPressure(
                    currentDryTurns = s.volcanoDryTurns,
                    linesCleared = 0,
                    lavaRow = s.lavaRow,
                    firstThreshold = LevelDirector.volcanoFirstThreshold(lv),
                    surfacedThreshold = LevelDirector.volcanoSurfacedThreshold(lv),
                )
                if (pressure.advanceLava) checks += { p -> p.rows.size + p.cols.size >= VOLCANO_PARRY_LINES }
            }
            else -> Unit
        }
        if (checks.isEmpty()) return null
        return { p -> checks.any { it(p) } }
    }

    private suspend fun applyBiomeTick() {
        gameMutex.withLock {
          try {
            val s = _gameState.value
            val placedForBiomeTick = lastPlacedCellsForBiomeTick
            lastPlacedCellsForBiomeTick = emptySet()
            if (s.status != com.cukiti.teikafusion.model.GameStatus.PLAYING) return@withLock
            val active = listOf(s.biomePrimary)
            // P-228: el hueco jugable ANTES del castigo. Al final del tick se compara con el de
            // después: si ha bajado, el bioma te ha quitado sitio y el cartel de derrota lo dirá.
            val freeCellsBeforeTick = s.playableFreeCells
            val turn = s.biomeTurnCounter + 1
            val events = s.events.toMutableList()
            // ── P-243 · LOS PORTALES SE MUDAN, Y SE AVISA (2026-09-22) ──────────────────────────
            // Sustituye al aviso de LA PORTERÍA MÓVIL. En la segunda mitad del juego los portales
            // cambian de altura cada pocas colocaciones: sin este acuse lo harían a escondidas.
            if (com.cukiti.teikafusion.model.Portals.movesOn(s.level, s.placementsInLevel)) {
                val antes = com.cukiti.teikafusion.model.Portals.rowsFor(s.level, s.placementsInLevel - 1)
                val ahora = com.cukiti.teikafusion.model.Portals.rowsFor(s.level, s.placementsInLevel)
                if (antes != null && ahora != null && antes != ahora) {
                    events.add(GameEvent.PortalsMoved(antes.first, antes.second, ahora.first, ahora.second))
                }
            }
            // Actividad del turno anterior = Σ LÍNEAS ROTAS (pase normal + descarga del circuito, y la
            // fila que la Tormenta convierte en circuito, que también se completó). Las FUSIONES ya no
            // suman desde el 2026-09-05: se producen solas entre turnos y regalaban el turno que el
            // reloj del bioma necesitaba — ver la nota larga en `processContactFusion` y el KDoc de
            // [com.cukiti.teikafusion.model.BiomeRhythm].
            val activityWeight = activityWeightSinceTick
            activityWeightSinceTick = 0
            // Señal única que leen TODAS las secciones de bioma de abajo: "¿rompió línea este turno?".
            val boardActive = activityWeight > 0
            // P-353 · LA PARADA PERFECTA: lo que se rompió en ESTE turno (filas, columnas, casillas) y la
            // ficha que se colocó. Cada bioma mira si pasa por su zona amenazada en el turno del golpe.
            val parryRows: Set<Int> = HashSet(clearedRowsSinceTick)
            val parryCols: Set<Int> = HashSet(clearedColsSinceTick)
            val parryCells: Set<Position> = HashSet(clearedCellsSinceTick)
            clearedRowsSinceTick.clear(); clearedColsSinceTick.clear(); clearedCellsSinceTick.clear()
            val placedPieceId = lastPlacedPieceIdForBiomeTick
            lastPlacedPieceIdForBiomeTick = null
            fun parry(biome: com.cukiti.teikafusion.model.BiomeType) {
                events.add(GameEvent.BiomeParry(biome))
                soundManager.playTrayReward()
            }
            // Glotón: ¿se rompió línea este turno? (calma al glotón). `gluttonFedSinceTick` lo ponen
            // hoy las dos rutas de rotura y el banquete de Chueta —su habilidad, que el jugador SÍ
            // decide—; la fusión dejó de ponerlo el 2026-09-05, como el resto del reloj.
            val gluttonFed = gluttonFedSinceTick || boardActive
            gluttonFedSinceTick = false
            val gluttonFeast = gluttonFeastSinceTick
            gluttonFeastSinceTick = false
            // Volcán: SOLO las roturas reales (líneas/circuitos) mueven la lava — ver bloque VOLCANO.
            val volcanoClears = volcanoClearsSinceTick
            volcanoClearsSinceTick = 0
            // Galáctico: ¿se rompió alguna línea este turno? (las fusiones NO cuentan). Único contrajuego
            // "de tablero" del agujero — se consume aquí.
            val galacticCleared = galacticClearsSinceTick > 0
            galacticClearsSinceTick = 0
            // Cuenta OCIOSA del galáctico: colocaciones sin romper línea. El meteorito (P-294) asoma e
            // impacta según LevelDirector.meteorWarnThreshold / meteorThreshold.
            // EL RELOJ QUE SE CONGELA (2026-09-23): romper una línea en un aviso lo congela; solo en el
            // turno de despresurizar la cancela. Ver [com.cukiti.teikafusion.model.BiomeClock].
            // P-353: el reloj de los meteoritos SIEMPRE avanza (el castigo siempre llega).
            galacticIdleCounter = if (s.biomePrimary == com.cukiti.teikafusion.model.BiomeType.GALACTIC)
                com.cukiti.teikafusion.model.BiomeCycle.advance(galacticIdleCounter) else 0
            // Tormenta: si ESTA colocación convirtió su fila en circuito (energización), el turno NO
            // cuenta para las presiones idle (rapto del jardín, presión del volcán): completar la fila
            // fue "jugar bien" aunque la rotura quede pendiente de resolver el circuito.
            val stormEnergized = stormEnergizedSinceTick
            stormEnergizedSinceTick = false

            // PERF: nivel SIN bioma (1–4 e infinito) → no hay mecánica que correr. Evita la copia del
            // grid (s.grid.toMutableMap) y las ~15 ramas de bioma; solo avanza el reloj y evalúa el
            // objetivo. Los flags xxxSinceTick ya se consumieron arriba, así que no se acumulan.
            // Fase 3 (2026-07-24): el INFINITO ya no toma prestada NINGUNA mecánica de los niveles
            // — se arrancó la escalera entera (cristal, corte ninja, astro, agujeros negros, lava).
            // Su única amenaza es la MAREA, que corre en su propio tick (ver tickInfiniteTide) y no
            // necesita nada de aquí. Así que el Infinito vuelve a salir SIEMPRE por el fast path.
            if (active.all { it == com.cukiti.teikafusion.model.BiomeType.NONE }) {
                // Sin bioma no hay castigo que pueda quitar sitio: la culpa es siempre del jugador.
                val bumped = s.copy(biomeTurnCounter = turn, events = events, lastSqueezeBiome = null)
                _gameState.value = if (bumped.status == com.cukiti.teikafusion.model.GameStatus.PLAYING)
                    checkObjectiveCompletion(bumped) else bumped
                return@withLock
            }

            // Bosque del Sueño / "Maite" (idle-gated): tras DROWSY_PERIOD turnos SIN romper filas
            // entra la Maite durante DROWSY_DURATION turnos. Romper una fila reinicia la cuenta.
            //
            // (2026-09-07) Su castigo era «no puedes rotar». El giro se retiró del juego entero, así
            // que ahora **duerme una ficha de la bandeja**: la MÁS GRANDE de las que hay en la mano,
            // que es la que más sitio pide y la que más duele perder durante unos turnos. Se elige
            // la más grande y no una al azar a propósito — una regla que el jugador puede aprender
            // ("guarda la grande antes de que te alcance") es contrajugada; el azar, no.
            val wasDrowsy = s.drowsyTurns > 0
            var drowsy = s.drowsyTurns
            var drowsyPiece = s.drowsyPieceId
            var sleepIdle = s.sleepIdleTurns
            var drowsyMarked = s.drowsyMarkedId
            if (com.cukiti.teikafusion.model.BiomeType.SLEEP in active) {
                if (wasDrowsy) {
                    // Maite activa → decrementar (dura DROWSY_DURATION turnos).
                    drowsy = (s.drowsyTurns - 1).coerceAtLeast(0)
                    if (drowsy == 0 && s.availablePieces.any { it.id == drowsyPiece }) {
                        soundManager.playSleepWake()
                    }
                    // Al despertar se suelta la ficha; y si la dormida ya se fue de la bandeja
                    // —sale del juego por una habilidad, un descarte— el sueño se queda sin objeto.
                    if (drowsy == 0 || s.availablePieces.none { it.id == drowsyPiece }) {
                        drowsy = 0
                        drowsyPiece = null
                    }
                } else {
                    // P-353: la Maite SIEMPRE llega. En el aviso MARCA la ficha más grande; jugarla antes la
                    // aparta (duerme otra, un solo turno). Parada perfecta: colocar la marcada rompiendo línea.
                    val sleepAt = com.cukiti.teikafusion.model.BiomeCycle.strikeAt(s.level)
                    sleepIdle += 1
                    if (drowsyMarked == null && sleepIdle in (sleepAt - 2) until sleepAt) {
                        drowsyMarked = s.availablePieces.takeIf { it.size > 1 }?.maxByOrNull { it.shape.size }?.id
                    }
                    if (sleepIdle >= sleepAt && drowsyMarked != null && placedPieceId == drowsyMarked && boardActive) {
                        parry(com.cukiti.teikafusion.model.BiomeType.SLEEP)
                        sleepIdle = 0
                        drowsyMarked = null
                    }
                    if (sleepIdle >= sleepAt) {
                        // Sin al menos DOS fichas en la mano no hay nada que dormir: dormir la única
                        // que queda sería congelar la partida, no castigarla (ver `isPieceAsleep`).
                        val marked = s.availablePieces.firstOrNull { it.id == drowsyMarked }
                        val victim = s.availablePieces
                            .takeIf { it.size > 1 }
                            ?.let { tray -> marked ?: tray.maxByOrNull { it.shape.size } }
                        if (victim != null) {
                            // Jugar la marcada MITIGA: la que duerme en su lugar lo hace un solo turno.
                            val sleepDuration = if (marked != null) LevelDirector.sleepDuration(s.level) else 1
                            drowsy = sleepDuration
                            drowsyPiece = victim.id
                            sleepIdle = 0
                            drowsyMarked = null
                            events.add(GameEvent.DrowsyOnset(sleepDuration))
                            soundManager.playSleepDrowsy()
                        }
                        // Si no había víctima, el contador se queda arriba y la Maite lo intenta al
                        // turno siguiente: el castigo se aplaza, no se perdona.
                    }
                }
            } else {
                sleepIdle = 0
                drowsy = 0
                drowsyPiece = null
                drowsyMarked = null
            }

            // Grid de trabajo del tick (histórico: nació para el ninja; hoy lo usan TODAS las
            // secciones de bioma de abajo).
            val ninjaGrid = s.grid.toMutableMap()
            // "El jugador hizo algo a tiempo" → reinicia los relojes ociosos (rompió fila o fusionó).
            val ninjaLineCleared = boardActive
            // Compatibilidad del estado antiguo: ya no hay calma ni espera entre huidas.
            val fearCalm = LevelDirector.fearCalmTurns(s.level)
            // Dojo en Sombras (rework 2026-07-16 · CORTE NINJA): idle-gated, solo bioma primario.
            // La 1ª y 2ª colocación ociosa alimentan el AVISO creciente (ninjaIdleTurns → la UI lo
            // dibuja con NinjaCutThreatOverlay, transición fluida); a la NINJA_CUT_AT el ninja PARTE
            // el tablero por la columna central (muro físico + fichas sin poder cruzar). Con el
            // tablero ya partido el contador queda DORMIDO: la reparación no vive aquí sino en
            // resolveLineClearPass (`LevelDirector.ninjaRepairLines` líneas) o en la fusión → MEGA.
            var ninjaIdle = s.ninjaIdleTurns
            var ninjaCutOn = s.ninjaCutActive
            var ninjaCutLeft = s.ninjaCutLinesLeft
            var ninjaCutTurns = s.ninjaCutTurns
            var ninjaTruce = s.ninjaTruceTurns
            // Fase 3: el corte ninja es SOLO del Dojo. El Infinito dejó de encenderlo por fase.
            val ninjaCutAt = LevelDirector.ninjaCutThreshold(s.level)
            val ninjaRepairLines = LevelDirector.ninjaRepairLines(s.level)
            if (s.biomePrimary == com.cukiti.teikafusion.model.BiomeType.NINJA) {
                if (!ninjaCutOn && ninjaTruce > 0) {
                    // P-254 · LA TREGUA: la katana no avisa; cada colocación consume un turno, rompas
                    // líneas o no (la que reparó la grieta siempre rompe una: si eso la acabara, la
                    // tregua no existiría). El reloj de la casa arranca limpio al acabar.
                    ninjaTruce -= 1
                    ninjaIdle = 0
                } else if (!ninjaCutOn) {
                    // P-353: la katana SIEMPRE avanza. Parada perfecta: en el turno del tajo, romper una
                    // columna de la COSTURA (las dos del centro).
                    ninjaIdle += 1
                    if (ninjaIdle >= ninjaCutAt && ninjaSeamParried(parryCols)) {
                        ninjaIdle = 0
                        parry(com.cukiti.teikafusion.model.BiomeType.NINJA)
                    }
                    if (ninjaIdle >= ninjaCutAt) {
                        ninjaCutOn = true
                        ninjaCutLeft = ninjaRepairLines
                        ninjaCutTurns = 0
                        ninjaIdle = 0
                        // El muro físico lo levanta onTeikaPhysicsFrame en el próximo frame (se
                        // deriva del estado): los cuerpos que pisaban la frontera son empujados a
                        // su mitad por el clamp de collideWalls (el empujón del tajo).
                        events.add(GameEvent.NinjaBoardSlash(ninjaRepairLines))
                        soundManager.playNinjaSlash()
                        // El SHAKE llega con el IMPACTO de la hoja (~45% del tajo), no con el
                        // inicio de la caída — la sacudida debe coincidir con el flash del slash.
                        viewModelScope.launch {
                            kotlinx.coroutines.delay(NINJA_CUT_IMPACT_MS)
                            _gameState.update {
                                if (it.status != com.cukiti.teikafusion.model.GameStatus.PLAYING) it
                                else it.copy(events = it.events + GameEvent.ScreenShake(2.4f))
                            }
                        }
                    }
                } else {
                    ninjaIdle = 0
                    // P-254 · LA GRIETA SE CIERRA SOLA (2026-09-24, decisión del usuario): el castigo
                    // tiene fin. Romper columnas la cierra antes; si no, a las
                    // `ninjaCutHealTurns` colocaciones se sella igual, con el mismo kintsugi.
                    // Si esta misma colocación ya la reparó con líneas, el estado llega apagado y
                    // no se cuenta nada (no hay doble reparación).
                    ninjaCutTurns += 1
                    if (ninjaCutTurns >= LevelDirector.ninjaCutHealTurns(s.level)) {
                        ninjaCutOn = false
                        ninjaCutLeft = 0
                        ninjaCutTurns = 0
                        ninjaTruce = LevelDirector.ninjaTruceTurns(s.level)
                        events.add(GameEvent.NinjaBoardRepair())
                        soundManager.playNinjaRepair()
                        scheduleKintsugiScar()
                        viewModelScope.launch {
                            kotlinx.coroutines.delay(NINJA_REPAIR_SNAP_MS)
                            _gameState.update {
                                if (it.status != com.cukiti.teikafusion.model.GameStatus.PLAYING) it
                                else it.copy(events = it.events + GameEvent.ScreenShake(1.2f))
                            }
                        }
                    }
                }
            } else {
                ninjaIdle = 0
                // Saneo: el corte no debe sobrevivir a un cambio de bioma (no ocurre dentro de un
                // nivel, pero un save raro no debe dejar un muro fantasma sin quién lo repare).
                if (ninjaCutOn) {
                    ninjaCutOn = false; ninjaCutLeft = 0; ninjaCutTurns = 0
                }
                ninjaTruce = 0
            }

            var plantIdleTurns = s.plantIdleTurns
            var plantMarkEdge = s.plantMarkEdge
            var plantMarkTeika = s.plantMarkTeikaId
            var plantAbduction = s.plantAbduction
            var plantBusyIds = s.busyTeikaIds
            val plantTargetGains = mutableMapOf<TargetColor, Int>()
            if (com.cukiti.teikafusion.model.BiomeType.GARDEN in active) {
                // P-324 (2026-09-26): el reloj corre HAYA o no Teika. Sin Teika que agarrar, al tercer
                // turno la enredadera invade desde un borde (antes el contador se quedaba a 0 y el bioma no
                // hacía nada en las partidas sin Teikas).
                val hasAbductable = _teikaBodies.value.any { it.frozenTurns == 0 && !it.kinematic }
                if (plantAbduction == null) {
                    // P-353: la raíz SIEMPRE llega. En el aviso MARCA el borde y el Teika que se llevará;
                    // parada perfecta: en el turno del golpe, una línea que toque al marcado (o, sin Teika,
                    // la franja del borde).
                    val gardenAt = com.cukiti.teikafusion.model.BiomeCycle.strikeAt(s.level)
                    plantIdleTurns += 1
                    if (plantMarkEdge == null && plantIdleTurns in (gardenAt - 2) until gardenAt) {
                        val e = PlantEdge.entries.random(rng)
                        plantMarkEdge = e
                        plantMarkTeika = if (hasAbductable) selectPlantTarget(e)?.id else null
                    }
                    if (plantIdleTurns >= gardenAt) {
                        val zone: Set<Position> = gardenParryZone(plantMarkTeika, plantMarkEdge)
                            ?: gardenEdgeBand(PlantEdge.entries.random(rng))
                        if (zone.any { it in parryCells }) {
                            parry(com.cukiti.teikafusion.model.BiomeType.GARDEN)
                            plantIdleTurns = 0
                            plantMarkEdge = null; plantMarkTeika = null
                        }
                    }
                    if (plantIdleTurns >= gardenAt) {
                        val edge = plantMarkEdge ?: PlantEdge.entries.random(rng)
                        // Mitigar: si el marcado ya no está (fundido) o no se puede agarrar, la raíz busca otro.
                        val markedFree = _teikaBodies.value.firstOrNull {
                            it.id == plantMarkTeika && it.frozenTurns == 0 && !it.kinematic
                        }
                        val target = if (hasAbductable) (markedFree ?: selectPlantTarget(edge)) else null
                        plantMarkEdge = null; plantMarkTeika = null
                        if (target != null) {
                            val captured = PlantAbduction(
                                teikaId = target.id,
                                teikaType = target.type,
                                edge = edge,
                                currentRoot = bodyTopLeftCell(target),
                                maxTurns = LevelDirector.gardenAbductionTurns(s.level)
                            )
                            val result = advancePlantAbduction(
                                ninjaGrid,
                                captured,
                                plantBusyIds + target.id,
                                events
                            )
                            plantAbduction = result.abduction
                            plantBusyIds = result.busyIds
                            plantIdleTurns = result.idleTurns
                            result.targetGains.forEach { (color, amount) ->
                                plantTargetGains[color] = (plantTargetGains[color] ?: 0) + amount
                            }
                        } else {
                            // P-324 · LA INVASIÓN: sin Teika que agarrar, la enredadera brota del borde.
                            val cuerpos = teikaBlockedCells()
                            val cells = com.cukiti.teikafusion.model.GardenVine.invasionCells(
                                edge, ninjaGrid,
                                unusable = cuerpos + s.unplaceableCells + s.gluttonDeadCells.keys + setOfNotNull(s.eggCell),
                                filled = cuerpos,
                                random = rng,
                            )
                            if (cells.isNotEmpty()) {
                                scheduleVineSprout(cells.toSet(), edge, delayMs = 0L, excludeBody = null)
                                soundManager.playVineGrab()
                            }
                            plantIdleTurns = 0
                        }
                    }
                } else if (stormEnergized) {
                    // Completar una fila que se volvió circuito NO cuenta turno de arrastre: la planta
                    // espera quieta a que el jugador resuelva (o falle) el circuito.
                } else {
                    val result = advancePlantAbduction(
                        ninjaGrid,
                        plantAbduction,
                        plantBusyIds,
                        events
                    )
                    plantAbduction = result.abduction
                    plantBusyIds = result.busyIds
                    plantIdleTurns = result.idleTurns
                    result.targetGains.forEach { (color, amount) ->
                        plantTargetGains[color] = (plantTargetGains[color] ?: 0) + amount
                    }
                }
            } else {
                plantAbduction?.let { plantBusyIds = plantBusyIds - it.teikaId }
                plantIdleTurns = 0
                plantAbduction = null
                plantMarkEdge = null; plantMarkTeika = null
            }

            // Tóxico · EL VENENO ES UNA CAPA (2026-09-28) — reglas en [ToxicBiomeRules] (solo primario).
            // Sin romper línea, se EXTIENDE un paso a los bloques vecinos; si no alcanza ninguno, a las
            // [ToxicBiomeRules.SPLASH_AFTER_TURNS] colocaciones seguidas sin romper SALPICA lejos. Romper
            // una línea para el avance y reinicia la cuenta. [toxicDecayCounter] guarda esa cuenta (el
            // nombre viene de la putrefacción que sustituyó; se conserva para no romper guardados).
            var toxicDecay = s.toxicDecayCounter
            var toxicFront = emptyList<Pair<Position, Position>>()
            if (s.biomePrimary == com.cukiti.teikafusion.model.BiomeType.TOXIC) {
                val rules = com.cukiti.teikafusion.model.ToxicBiomeRules
                val teikaOccToxic = teikaBlockedCells()
                fun canPoison(p: Position): Boolean {
                    val w = ninjaGrid[p] as? CellContent.Wood ?: return false
                    return rules.isSpreadCandidate(w, p, s.lavaRow, s.unplaceableCells, placedForBiomeTick, teikaOccToxic)
                }
                if (boardActive) {
                    toxicDecay = 0
                } else {
                    val poisonedNow = ninjaGrid.filter { (_, c) -> c is CellContent.Wood && c.poisoned }.keys
                    val step = rules.spreadStep(poisonedNow, ::canPoison)
                    if (step.isNotEmpty()) {
                        toxicDecay = 0
                        step.forEach { (from, to) ->
                            val w = ninjaGrid[to] as? CellContent.Wood ?: return@forEach
                            ninjaGrid[to] = w.copy(poisoned = true)
                            events.add(GameEvent.PoisonSpread(from = from, to = to))
                        }
                        soundManager.playToxicSpread()
                    } else {
                        toxicDecay += 1
                        if (rules.shouldSplash(toxicDecay, LevelDirector.toxicSplashAfter(s.level))) {
                            toxicDecay = 0
                            val candidates = ninjaGrid.keys.filter(::canPoison)
                            val targets = rules.splashTargets(
                                poisonedNow, candidates, rng, count = LevelDirector.toxicSplashCount(s.level)
                            )
                            val center = Position(GameState.GRID_SIZE / 2, GameState.GRID_SIZE / 2)
                            targets.forEach { to ->
                                val w = ninjaGrid[to] as? CellContent.Wood ?: return@forEach
                                ninjaGrid[to] = w.copy(poisoned = true)
                                events.add(GameEvent.PoisonSpread(
                                    from = rules.nearestSource(poisonedNow, to) ?: center, to = to, splash = true,
                                ))
                            }
                            if (targets.isNotEmpty()) soundManager.playPoisonSplash()
                        }
                    }
                }
                // El aviso del turno que viene: lo que alcanzaría con el tablero que queda (la ficha de
                // este turno ya cuenta como bloque normal en la próxima).
                val poisonedAfter = ninjaGrid.filter { (_, c) -> c is CellContent.Wood && c.poisoned }.keys
                toxicFront = rules.spreadStep(poisonedAfter) { p ->
                    val w = ninjaGrid[p] as? CellContent.Wood
                    w != null && rules.isSpreadCandidate(w, p, s.lavaRow, s.unplaceableCells, emptySet(), teikaOccToxic)
                }
            } else {
                toxicDecay = 0
            }

            // Acumulador de celdas ocultas de ESTE tick: el galáctico y el rey tapan la madera
            // mientras viaja (su VFX la dibuja) y la revelan al asentarse.
            var starHidden = s.hiddenWoodCells

            // Espacio Profundo · LLUVIA DE METEORITOS (P-294, 2026-09-25; sustituye a la Brecha). Reglas en
            // [MeteorShower]. 1.er aviso: el meteorito ASOMA lejos (ya ha elegido el cráter 2×2 que más
            // bloques funde). 2.º: el cráter se marca (lo pinta la UI con `galacticIdleSaved`). 3.º:
            // IMPACTO — los bloques del cráter se funden en roca blindada y los Teikas salen despedidos.
            // Contrajuego: una línea que cruce el cráter lo DESVÍA en cualquier aviso; otra línea solo
            // congela el reloj ([BiomeClock]).
            var meteorAt = s.meteorAt
            var meteorAt2 = s.meteorAt2
            if (s.biomePrimary == com.cukiti.teikafusion.model.BiomeType.GALACTIC) {
                val impactAt = LevelDirector.meteorThreshold(s.level)
                // P-319 · LA ROCA SE AGRIETA: cada roca envejece una colocación; la que llega a su 3.ª
                // contagia a un vecino. Va ANTES del impacto: la roca que cae ahora empieza en 0.
                val (agedGrid, cracks) = com.cukiti.teikafusion.model.MeteorShower.tickRocks(
                    ninjaGrid, rng, protected = setOfNotNull(s.eggCell),
                )
                if (agedGrid !== ninjaGrid) ninjaGrid.putAll(agedGrid)
                cracks.forEach { crack ->
                    val ev = GameEvent.RockCrack(crack.from, crack.to)
                    events.add(ev)
                    launchRoundJob {
                        // El bloque se funde cuando la grieta lo alcanza, a mitad de su VFX.
                        kotlinx.coroutines.delay(ev.durationMillis / 2L)
                        gameMutex.withLock {
                            val st = _gameState.value
                            val w = st.grid[crack.to] as? CellContent.Wood ?: return@withLock
                            if (w.rock) return@withLock
                            val g = st.grid.toMutableMap()
                            g[crack.to] = com.cukiti.teikafusion.model.MeteorShower.petrify(w)
                            _gameState.value = st.copy(grid = g)
                        }
                    }
                }
                if (cracks.isNotEmpty()) soundManager.playRockCrack()

                // El desvío (2026-09-27, decisión del usuario): SOLO romper una línea JUSTO en el turno
                // del impacto desvía los meteoritos ([BiomeClock]). Romper en un aviso congela el reloj
                // y la mira sigue fija; cruzar el cráter ya no tiene premio aparte.
                // P-353 · PARADA PERFECTA: en el turno del impacto, una línea que CRUCE un cráter lo
                // desvía (cada cráter por separado); el otro, si lo hay, cae igual.
                val strikeNow = galacticIdleCounter >= impactAt
                var deflectedNow = false
                meteorAt?.let { t ->
                    if (strikeNow && com.cukiti.teikafusion.model.MeteorShower.craterCells(t).any { it in parryCells }) {
                        events.add(GameEvent.MeteorDeflect(t)); meteorAt = null; deflectedNow = true
                    }
                }
                meteorAt2?.let { t ->
                    if (strikeNow && com.cukiti.teikafusion.model.MeteorShower.craterCells(t).any { it in parryCells }) {
                        events.add(GameEvent.MeteorDeflect(t)); meteorAt2 = null; deflectedNow = true
                    }
                }
                if (deflectedNow) {
                    soundManager.playMeteorDeflect()
                    parry(com.cukiti.teikafusion.model.BiomeType.GALACTIC)
                }
                if (!stormEnergized) {
                    // (El reloj `galacticIdleCounter` ya avanzó arriba, con `galacticCleared`.)
                    // Se apunta al empezar el ciclo, nunca a mitad: si un cráter se desvió, no sale otro.
                    if (meteorAt == null && meteorAt2 == null && !strikeNow &&
                        galacticIdleCounter >= LevelDirector.meteorWarnThreshold(s.level)
                    ) {
                        val vetadas = s.gluttonDeadCells.keys + setOfNotNull(s.eggCell)
                        val at = com.cukiti.teikafusion.model.MeteorShower.choose(
                            ninjaGrid,
                            blocked = vetadas,
                            order = com.cukiti.teikafusion.model.MeteorShower.allCorners().shuffled(rng),
                        )
                        if (at != null) {
                            meteorAt = at
                            events.add(GameEvent.MeteorSpotted(at))
                            // Sin disparo suelto: el radar en bucle arranca solo al haber mira (ver init).
                            // P-319 · LLUVIA DOBLE: en el último tercio del capítulo, un segundo cráter.
                            if (com.cukiti.teikafusion.model.MeteorShower.doubleShowerFor(s.level)) {
                                val at2 = com.cukiti.teikafusion.model.MeteorShower.chooseSecond(
                                    ninjaGrid, first = at, blocked = vetadas,
                                    order = com.cukiti.teikafusion.model.MeteorShower.allCorners().shuffled(rng),
                                )
                                if (at2 != null) {
                                    meteorAt2 = at2
                                    events.add(GameEvent.MeteorSpotted(at2))
                                }
                            }
                        }
                    }
                    if (galacticIdleCounter >= impactAt && (meteorAt != null || meteorAt2 != null)) {
                        // Lo que ya ocupa sitio para la metralla: los Teikas (también son comodín de las
                        // líneas), las casillas vetadas y los fragmentos del otro meteorito.
                        val teikaCells = teikaBlockedCells()
                        val takenShards = HashSet<Position>()
                        listOfNotNull(meteorAt, meteorAt2).forEach { at ->
                            val crater = com.cukiti.teikafusion.model.MeteorShower.craterCells(at)
                            // Como mucho MAX_ROCKS bloques se funden (2026-09-25): con los cuatro, la roca ahogaba.
                            val rocks = com.cukiti.teikafusion.model.MeteorShower.rocksFor(at, ninjaGrid)
                            // P-319 · METRALLA: fragmentos de roca a casillas vacías junto al cráter.
                            val shards = com.cukiti.teikafusion.model.MeteorShower.shardsFor(
                                at, ninjaGrid,
                                unusable = teikaCells + takenShards + s.gluttonDeadCells.keys +
                                    setOfNotNull(s.eggCell) + s.unplaceableCells,
                                filled = teikaCells + takenShards,
                                random = rng,
                            )
                            takenShards += shards
                            val shardColors = shards.map { rng.nextInt(WOOD_COLOR_PALETTE.size) }
                            // Los cuerpos del cráter y de su anillo de alrededor: el impacto los despide.
                            val ring = crater.flatMap { c ->
                                (-1..1).flatMap { dy -> (-1..1).map { dx -> Position(c.x + dx, c.y + dy) } }
                            }.toSet()
                            val pushedIds = physicsWorld.occupiedCells().filterKeys { it in ring }.values.toSet()
                            val impact = GameEvent.MeteorImpact(
                                at = at, rocks = rocks, pushedTeikaIds = pushedIds.toList(),
                                durationMillis = BIOME_EVENT_MAX_MS - 200,
                                shards = shards,
                            )
                            events.add(impact)
                            val cx = at.x + com.cukiti.teikafusion.model.MeteorShower.SIZE / 2f
                            val cy = at.y + com.cukiti.teikafusion.model.MeteorShower.SIZE / 2f
                            launchRoundJob {
                                // El meteorito toca el tablero a media animación: ahí se funde la roca y
                                // salen volando los cuerpos.
                                kotlinx.coroutines.delay(impact.durationMillis * 45L / 100)
                                gameMutex.withLock {
                                    val st = _gameState.value
                                    val g = st.grid.toMutableMap()
                                    rocks.forEach { c ->
                                        val w = g[c] as? CellContent.Wood
                                        if (w != null) g[c] = com.cukiti.teikafusion.model.MeteorShower.petrify(w)
                                    }
                                    _gameState.value = st.copy(grid = g)
                                    pushedIds.forEach { id ->
                                        val b = physicsWorld.getBody(id) ?: return@forEach
                                        val dx = b.x - cx
                                        val dy = b.y - cy
                                        val len = kotlin.math.sqrt(dx * dx + dy * dy).coerceAtLeast(0.3f)
                                        physicsWorld.launchBody(
                                            id,
                                            dx / len * METEOR_PUSH_SPEED,
                                            dy / len * METEOR_PUSH_SPEED - METEOR_PUSH_LIFT,
                                        )
                                    }
                                }
                                if (shards.isEmpty()) return@launchRoundJob
                                // La metralla aterriza después (su vuelo lo dibuja el VFX). Una casilla que
                                // entretanto ocupó algo —un Teika despedido, una ficha— se la salta.
                                kotlinx.coroutines.delay(impact.durationMillis * (SHARD_LAND_PCT - 45L) / 100)
                                gameMutex.withLock {
                                    val st = _gameState.value
                                    val cuerpos = physicsWorld.occupiedCells().keys
                                    val g = st.grid.toMutableMap()
                                    shards.forEachIndexed { i, c ->
                                        if (g[c]?.isOccupied == true || c in cuerpos) return@forEachIndexed
                                        g[c] = com.cukiti.teikafusion.model.MeteorShower.shard(shardColors[i])
                                    }
                                    _gameState.value = st.copy(grid = g)
                                }
                            }
                        }
                        events.add(GameEvent.ScreenShake(1.8f))
                        soundManager.playMeteorImpact()
                        meteorAt = null
                        meteorAt2 = null
                        galacticIdleCounter = 0
                    }
                }
                // P-353: turno del impacto sin meteorito en camino (desviados o sin blanco): el ciclo vuelve a empezar.
                if (galacticIdleCounter >= LevelDirector.meteorThreshold(s.level) && meteorAt == null && meteorAt2 == null) {
                    galacticIdleCounter = 0
                }
            } else {
                meteorAt = null
                meteorAt2 = null
            }

            // Trono Real · LA ESPADA DEL REY (P-294, 2026-09-25; sustituye al Jaque). Reglas en [KingSword].
            // 1.er aviso: el Rey ALZA la espada y señala la línea con más bloques. 2.º: la hoja brilla sobre
            // ella (lo pinta la UI con `kingSwordIdle`). 3.º: CAE y la parte — sus bloques se rompen SIN
            // puntos y los Teikas salen lanzados hacia arriba (no se cortan). Una línea que cruce la
            // señalada la ENVAINA en cualquier aviso; otra solo congela el reloj.
            //
            // P-329 · LAS PIEZAS DEL REY (2026-09-26): el MISMO reloj alterna espada y pieza de ajedrez
            // ([kingPieceNext] dice a quién le toca). Nunca hay las dos alzadas a la vez. La pieza sigue
            // las mismas tres fases y el mismo contrajuego (reglas en [KingPiece]); lo suyo es que su
            // camino queda BLOQUEADO una colocación.
            var swordAxis = s.kingSwordAxis
            var swordLine = s.kingSwordLine
            var swordIdle = s.kingSwordIdle
            var pieceKind = s.kingPieceKind
            var pieceA = s.kingPieceA
            var pieceB = s.kingPieceB
            var pieceBlack = s.kingPieceBlack
            var pieceFromEnd = s.kingPieceFromEnd
            var pieceNext = s.kingPieceNext
            // 2026-09-28: piezas seguidas desde la última espada ([KingPiece.PIECES_PER_SWORD] por cada espada).
            var piecesInRow = s.kingPiecesInRow
            // LA CALLE BLOQUEADA dura [KingPiece.LANE_TURNS] colocaciones (2026-09-27, decisión del
            // usuario: 1 → 2, «que el castigo se sienta»). Cada tick descuenta la colocación que acaba de
            // sufrirla. Y en cada una se vuelve a preguntar si deja jugada: la bandeja cambia entre medias,
            // y un castigo de dos turnos tampoco puede costar la partida.
            var laneCells = s.kingLaneCells
            var laneTurns = s.kingLaneTurns
            // LA PIEZA SE QUEDA (2026-09-28): mientras está en el tablero, su calle no caduca; se va
            // con ella cuando el jugador rompe su fila o su columna.
            var restCell = s.kingRestCell
            var restKind = s.kingRestKind
            var restBlack = s.kingRestBlack
            if (restCell != null &&
                com.cukiti.teikafusion.model.KingPiece.restFreedBy(restCell, parryRows, parryCols)
            ) {
                events.add(GameEvent.KingPieceRetreat(restKind, -1, -1, restBlack, false, at = restCell))
                events.add(GameEvent.ScreenShake(0.8f))
                soundManager.playKingPieceEvict()
                parry(com.cukiti.teikafusion.model.BiomeType.KING)
                restCell = null; restKind = com.cukiti.teikafusion.model.KingPiece.NONE
                laneCells = emptySet(); laneTurns = 0
            }
            if (laneCells.isNotEmpty()) {
                if (restCell == null) laneTurns -= 1
                val stillPlayable = (restCell != null || laneTurns > 0) && hasAnyLegalPlacement(
                    grid = ninjaGrid,
                    availablePieces = s.availablePieces,
                    rulesState = s,
                )
                if (!stillPlayable) { laneCells = emptySet(); laneTurns = 0 }
            }
            if (s.biomePrimary == com.cukiti.teikafusion.model.BiomeType.KING) {
                val strikeAt = LevelDirector.swordThreshold(s.level)
                val none = com.cukiti.teikafusion.model.KingSword.NONE
                val noPiece = com.cukiti.teikafusion.model.KingPiece.NONE
                fun sheathe() {
                    events.add(GameEvent.KingSwordSheathe(swordAxis, swordLine))
                    events.add(GameEvent.ScreenShake(0.8f))
                    soundManager.playSwordSheathe()
                    swordAxis = none; swordLine = -1; swordIdle = 0
                    piecesInRow = 0; pieceNext = true
                }
                fun retreat() {
                    events.add(GameEvent.KingPieceRetreat(pieceKind, pieceA, pieceB, pieceBlack, pieceFromEnd))
                    events.add(GameEvent.ScreenShake(0.8f))
                    soundManager.playSwordSheathe()
                    pieceKind = noPiece; pieceA = -1; pieceB = -1; swordIdle = 0
                    piecesInRow += 1
                    pieceNext = com.cukiti.teikafusion.model.KingPiece.pieceTurnAfter(piecesInRow)
                }
                fun calm() { if (pieceKind != noPiece) retreat() else if (swordAxis != none) sheathe() }
                // P-353: el reloj del Rey SIEMPRE avanza. En el turno del golpe, la PARADA PERFECTA: romper
                // una de las dos líneas de la espada, o una línea que pise el camino de la pieza.
                run {
                    swordIdle += 1
                    if (swordIdle >= strikeAt) {
                        val swordParry = kingSwordParried(swordAxis, swordLine, parryRows, parryCols)
                        // 2026-09-28: la pieza solo se para cruzando su casilla de llegada (la diana del aviso).
                        val pieceParry = com.cukiti.teikafusion.model.KingPiece.parriedBy(
                            pieceKind, pieceA, pieceB, pieceFromEnd, parryRows, parryCols,
                        )
                        if (swordParry || pieceParry) {
                            calm()
                            parry(com.cukiti.teikafusion.model.BiomeType.KING)
                        }
                    }
                    if (swordAxis == none && pieceKind == noPiece &&
                        swordIdle >= LevelDirector.swordWarnThreshold(s.level)
                    ) {
                        // Le toca a la pieza: una al azar; si no tiene madera a su alcance, prueba las otras.
                        // Con una pieza ya quieta en el tablero, el golpe lo da la ESPADA: nunca dos piezas.
                        val picked = if (!pieceNext || restCell != null) null else
                            com.cukiti.teikafusion.model.KingPiece.KINDS.shuffled(rng).firstNotNullOfOrNull { k ->
                                com.cukiti.teikafusion.model.KingPiece.choose(k, ninjaGrid, rng)?.let { k to it }
                            }
                        if (picked != null) {
                            pieceKind = picked.first; pieceA = picked.second.first; pieceB = picked.second.second
                            pieceBlack = !pieceBlack
                            pieceFromEnd = rng.nextBoolean()
                            events.add(GameEvent.KingPieceRaise(pieceKind, pieceA, pieceB, pieceBlack, pieceFromEnd))
                            soundManager.playSwordRaise()
                        } else {
                            val (axis, line) = com.cukiti.teikafusion.model.KingSword.choose(
                                ninjaGrid, com.cukiti.teikafusion.model.KingSword.allLines().shuffled(rng)
                            )
                            if (axis != none) {
                                swordAxis = axis; swordLine = line
                                events.add(GameEvent.KingSwordRaise(axis, line))
                                soundManager.playSwordRaise()
                            }
                        }
                    }
                    if (pieceKind != noPiece && swordIdle >= strikeAt) {
                        val path = com.cukiti.teikafusion.model.KingPiece.cells(pieceKind, pieceA, pieceB)
                        val cuts = path.mapNotNull { p ->
                            (ninjaGrid[p] as? CellContent.Wood)?.let { w ->
                                GameEvent.KingSwordStrike.SwordCut(p, w.colorType, w.targetColor)
                            }
                        }
                        val pathSet = path.toSet()
                        val cutCells = cuts.map { it.cell }.toSet()
                        val bodyCells = physicsWorld.occupiedCells()
                        // LA PIEZA SE QUEDA (2026-09-28) en su casilla de llegada y bloquea lo que ataca
                        // como pieza de ajedrez. Si un Teika ocupa esa casilla, no se queda (meter terreno
                        // dentro de un cuerpo deja al solver sin salida) y la calle vuelve a caducar.
                        val landing = com.cukiti.teikafusion.model.KingPiece
                            .landingCell(pieceKind, pieceA, pieceB, pieceFromEnd)
                            ?.takeIf { it !in bodyCells }
                        val lane = if (landing != null)
                            com.cukiti.teikafusion.model.KingPiece.restLane(pieceKind, pieceA, pieceB, landing)
                        else pathSet
                        // La calle se bloquea… salvo que eso deje la bandeja sin jugada: un castigo no
                        // puede costar la partida. (La pieza se queda igual: solo se abre su calle.)
                        val afterGrid = ninjaGrid.toMutableMap().apply { cutCells.forEach { this[it] = CellContent.Empty } }
                        val blocks = hasAnyLegalPlacement(
                            grid = afterGrid,
                            availablePieces = s.availablePieces,
                            rulesState = s.copy(kingLaneCells = lane, kingRestCell = landing),
                        )
                        if (blocks) { laneCells = lane; laneTurns = com.cukiti.teikafusion.model.KingPiece.LANE_TURNS }
                        val pushedIds = bodyCells.filterKeys { it in pathSet }.values.toSet()
                        val strike = GameEvent.KingPieceStrike(
                            kind = pieceKind, a = pieceA, b = pieceB, black = pieceBlack, fromEnd = pieceFromEnd,
                            cuts = cuts, pushedTeikaIds = pushedIds.toList(), blocked = blocks,
                            durationMillis = BIOME_EVENT_MAX_MS - 200,
                            stays = landing != null,
                        )
                        val landedKind = pieceKind
                        val landedBlack = pieceBlack
                        events.add(strike)
                        events.add(GameEvent.ScreenShake(if (cuts.isNotEmpty()) 1.8f else 1.0f))
                        if (pieceKind == com.cukiti.teikafusion.model.KingPiece.KNIGHT) soundManager.playMeteorImpact()
                        else soundManager.playSwordStrike()
                        // Los bloques arrasados siguen ocupando hasta el instante del golpe (fin de la
                        // cámara lenta, ver KingPieceVFX); ahí se vacían y los Teikas salen lanzados.
                        starHidden = starHidden + cutCells
                        launchRoundJob {
                            kotlinx.coroutines.delay(strike.durationMillis * com.cukiti.teikafusion.model.KingPiece.IMPACT_PCT / 100L)
                            gameMutex.withLock {
                                val st = _gameState.value
                                val g = st.grid.toMutableMap()
                                cutCells.forEach { c -> if (g[c] is CellContent.Wood) g[c] = CellContent.Empty }
                                _gameState.value = st.copy(grid = g, hiddenWoodCells = st.hiddenWoodCells - cutCells)
                                pushedIds.forEach { id ->
                                    val b = physicsWorld.getBody(id) ?: return@forEach
                                    physicsWorld.launchBody(id, b.vx, -SWORD_PUSH_LIFT)
                                }
                            }
                            // La pieza que se queda aterriza en el mismo instante del golpe.
                            if (landing != null) soundManager.playKingPieceLand()
                        }
                        // La casilla de llegada es terreno YA (no al final del golpe): así ningún cuerpo
                        // rueda dentro mientras dura la animación.
                        if (landing != null) { restCell = landing; restKind = landedKind; restBlack = landedBlack }
                        pieceKind = noPiece; pieceA = -1; pieceB = -1; swordIdle = 0
                        piecesInRow += 1
                        pieceNext = com.cukiti.teikafusion.model.KingPiece.pieceTurnAfter(piecesInRow)
                    }
                    if (swordAxis != none && swordIdle >= strikeAt) {
                        // P-352: la hoja ancha cae sobre la línea señalada y su pareja.
                        // P-361 (2026-09-28): parte la SEÑALADA y deja la PAREJA como ESCOMBRO (roca: ocupa y
                        // pide dos líneas). Medido con el bot, partir dos líneas enteras AYUDABA —vaciaba el
                        // tablero— y el Trono quedó en el 74 % con objetivo 57 %.
                        val lineCells = com.cukiti.teikafusion.model.KingSword.strikeCells(swordAxis, swordLine)
                        val markedCells = com.cukiti.teikafusion.model.KingSword.cells(swordAxis, swordLine).toSet()
                        val rubbleCells = lineCells.filter { it !in markedCells && ninjaGrid[it] is CellContent.Wood }.toSet()
                        val cuts = lineCells.filter { it in markedCells }.mapNotNull { p ->
                            (ninjaGrid[p] as? CellContent.Wood)?.let { w ->
                                GameEvent.KingSwordStrike.SwordCut(p, w.colorType, w.targetColor)
                            }
                        }
                        val lineSet = lineCells.toSet()
                        val pushedIds = physicsWorld.occupiedCells().filterKeys { it in lineSet }.values.toSet()
                        val strike = GameEvent.KingSwordStrike(
                            axis = swordAxis, line = swordLine, cuts = cuts, pushedTeikaIds = pushedIds.toList(),
                            durationMillis = BIOME_EVENT_MAX_MS - 200,
                        )
                        events.add(strike)
                        events.add(GameEvent.ScreenShake(if (cuts.isNotEmpty()) 1.7f else 0.9f))
                        soundManager.playSwordStrike()
                        // Los bloques partidos siguen ocupando mientras el VFX dibuja sus mitades; se
                        // vacían cuando la hoja termina de caer.
                        val cutCells = cuts.map { it.cell }.toSet()
                        starHidden = starHidden + cutCells
                        launchRoundJob {
                            kotlinx.coroutines.delay(strike.durationMillis * 40L / 100)
                            gameMutex.withLock {
                                val st = _gameState.value
                                val g = st.grid.toMutableMap()
                                cutCells.forEach { c -> if (g[c] is CellContent.Wood) g[c] = CellContent.Empty }
                                // P-361: la pareja queda como escombro (la misma roca que el meteorito).
                                rubbleCells.forEach { c ->
                                    (g[c] as? CellContent.Wood)?.let { w -> g[c] = com.cukiti.teikafusion.model.MeteorShower.petrify(w) }
                                }
                                _gameState.value = st.copy(grid = g, hiddenWoodCells = st.hiddenWoodCells - cutCells)
                                pushedIds.forEach { id ->
                                    val b = physicsWorld.getBody(id) ?: return@forEach
                                    physicsWorld.launchBody(id, b.vx, -SWORD_PUSH_LIFT)
                                }
                            }
                        }
                        swordAxis = none; swordLine = -1; swordIdle = 0
                        piecesInRow = 0; pieceNext = true
                    }
                    // Turno del golpe sin nada alzado (tablero sin madera): el ciclo vuelve a empezar.
                    if (swordIdle >= strikeAt) swordIdle = 0
                }
            } else {
                swordAxis = com.cukiti.teikafusion.model.KingSword.NONE; swordLine = -1; swordIdle = 0
                pieceKind = com.cukiti.teikafusion.model.KingPiece.NONE; pieceA = -1; pieceB = -1
                pieceNext = false; piecesInRow = 0
                laneCells = emptySet(); laneTurns = 0
                restCell = null; restKind = com.cukiti.teikafusion.model.KingPiece.NONE
            }

            // Glaciar (rework 2026-07): la escarcha sobre madera se retira. Ahora, tras
            // GLACIER_FREEZE_AFTER turnos ociosos, una OLEADA DE FRÍO congela un TEIKA aleatorio
            // GLACIER_FROZEN_TURNS turnos: queda como OBSTÁCULO inmóvil (no fusiona ni rompe filas con
            // su cuerpo — frozenTurns ya lo vuelve estático y lo excluye de la fusión y del rapto). Cada
            // turno baja su cuenta; a 0 se deshiela. Contrajuego: romper una fila (boardActive) reinicia
            // el reloj (no descongela a los ya atrapados, pero frena nuevas oleadas). glacierFrostCells
            // queda vacío (plumbing inofensivo aguas abajo).
            val glacierFrost = emptySet<Position>()
            var glacierIdle = s.glacierIdleTurns
            if (com.cukiti.teikafusion.model.BiomeType.GLACIER in active) {
                // 1) Deshielo por tiempo: baja frozenTurns de cada cuerpo; a 0 se libera.
                var bodiesChanged = false
                // One release cue even when several bodies thaw together.
                if (_teikaBodies.value.any { it.frozenTurns == 1 }) soundManager.playGlacierThaw()
                _teikaBodies.value.filter { it.frozenTurns > 0 }.forEach { b ->
                    val left = b.frozenTurns - 1
                    physicsWorld.setFrozenTurns(b.id, left)
                    bodiesChanged = true
                    if (left <= 0) events.add(GameEvent.Particles(bodyTopLeftCell(b), -1))
                }
                // 2) Reloj → nueva oleada de congelación. SIN CONTRAJUEGO (2026-09-23, pedido del
                //    usuario): cuenta CADA colocación, rompas filas o no, y congela a TODOS los Teikas
                //    libres a la vez. Antes romper una fila reiniciaba el reloj y la ola atrapaba a uno
                //    solo al azar: el glaciar era la única amenaza que se podía ignorar jugando bien.
                //    El castigo sigue avisado (la escarcha repta con `glacierIdleTurns`) y sigue siendo
                //    temporal: el deshielo del paso 1 libera cada cuerpo a los GLACIER_FROZEN_TURNS (1 desde P-254).
                run {
                    glacierIdle += 1
                    if (glacierIdle >= LevelDirector.glacierWaveEvery(s.level)) {
                        val targets = _teikaBodies.value.filter { it.frozenTurns == 0 && !it.kinematic }
                        // La ventisca es UNA: nace del mayor cuerpo y su frente cuaja a todos a la vez.
                        val target = targets.maxByOrNull { it.type.level }
                        if (target != null) {
                            val frozenCell = bodyTopLeftCell(target)
                            events.add(GameEvent.GlacierColdWave(frozenCell, target.type.level))
                            events.add(GameEvent.ScreenShake(0.8f))
                            // EL HIELO CUAJA CUANDO LLEGA LA VENTISCA (fix 2026-08-01, revisión de
                            // tiempos de bioma). El SFX ya esperaba a `glacierImpactMs` —el frame en
                            // que el FRENTE de la ráfaga cruza por el Teika— pero `setFrozenTurns` se
                            // aplicaba al EMITIR: `FrozenBodiesOverlay` dibujaba el bloque de hielo
                            // desde el primer fotograma, con la ventisca todavía fuera del tablero.
                            // El jugador veía el resultado y DESPUÉS la animación que lo causa. Ahora
                            // el estado y el frente van al mismo compás, igual que el sonido.
                            // Con la ola a TODOS, cada cuerpo cuaja cuando el frente pasa por SU columna:
                            // la ventisca barre el tablero y los va dejando atrás, no los congela de golpe.
                            val freezes = targets.map { b ->
                                b.id to com.cukiti.teikafusion.ui.glacierImpactMs(
                                    bodyTopLeftCell(b).x, b.type.level
                                )
                            }.sortedBy { it.second }
                            val frozenTurns = LevelDirector.glacierFrozenTurns(s.level)
                            launchRoundJob {
                                var elapsed = 0L
                                freezes.forEachIndexed { i, (id, at) ->
                                    kotlinx.coroutines.delay((at - elapsed).coerceAtLeast(0L))
                                    elapsed = maxOf(elapsed, at)
                                    gameMutex.withLock {
                                        // Un cuerpo que se fusionó o murió mientras llegaba la ola ya no está.
                                        if (physicsWorld.snapshot().any { it.id == id }) {
                                            physicsWorld.setFrozenTurns(id, frozenTurns)
                                            _teikaBodies.value = physicsWorld.snapshot()
                                        }
                                    }
                                    if (i == 0) soundManager.playGlacierFreeze()
                                }
                            }
                            glacierIdle = 0
                            bodiesChanged = true
                        } else {
                            // No hay Teika libre que congelar: la ola pasa sin blanco y el ciclo vuelve a
                            // empezar (P-359; antes reintentaba en la colocación siguiente y cazaba a los
                            // recién nacidos nada más salir).
                            glacierIdle = 0
                        }
                    }
                }
                if (bodiesChanged) _teikaBodies.value = physicsWorld.snapshot()
            } else {
                glacierIdle = 0
            }

            // Cocina Voraz / Glotón — reglas en [GluttonBiomeRules] (primario o secundario).
            // Ocioso = sin clear ni fusión. Open → Bite. Clear/fusión calman. El mordisco se traga TODA
            // la madera del rincón (incl. estrellas, que se ACREDITAN); solo respeta los Teikas.
            var gluttonCounter = s.gluttonCounter
            var gluttonCorner = s.gluttonCorner
            var gluttonDead = s.gluttonDeadCells
            // Estrellas que el mordisco del Glotón se traga este turno → se acreditan al objetivo abajo.
            val gluttonEatenTargets = HashMap<com.cukiti.teikafusion.model.TargetColor, Int>()
            if (com.cukiti.teikafusion.model.BiomeType.GLUTTON in active) {
                if (gluttonDead.isNotEmpty()) {
                    gluttonDead = com.cukiti.teikafusion.model.GluttonBiomeRules.digest(gluttonDead)
                }
                // P-353: la boca SIEMPRE avanza. Parada perfecta: en el turno del mordisco, una línea que
                // pase por el rincón abierto. El banquete de Chueta (una carga) sigue calmándolo.
                val parryBite = !gluttonFeast && gluttonCorner in 0..3 &&
                    gluttonCounter + 1 >= LevelDirector.gluttonBiteThreshold(s.level) &&
                    GameState.gluttonCornerCells(gluttonCorner).any { it in parryCells }
                if (parryBite) parry(com.cukiti.teikafusion.model.BiomeType.GLUTTON)
                if (gluttonFeast || parryBite) {
                    // Con la boca ABIERTA el siguiente turno es el de morder: romper ahora lo cancela (la
                    // rotura ya la cerró al instante en el pase de líneas; esto cubre lo que quede). Con la
                    // boca cerrada es un aviso: el reloj se CONGELA ([BiomeClock]). El banquete de Chueta
                    // —una carga que el jugador decide gastar— sí lo calma del todo en cualquier turno.
                    if (gluttonCorner in 0..3) events.add(GameEvent.GluttonRetreat(gluttonCorner)).also { soundManager.playGluttonRetreat() }
                    gluttonCounter = 0
                    gluttonCorner = -1
                } else {
                    val mouthOpen = gluttonCorner in 0..3
                    val (nextC, shouldOpen, shouldBite) =
                        com.cukiti.teikafusion.model.GluttonBiomeRules.advanceIdle(
                            gluttonCounter,
                            mouthOpen,
                            fed = false,
                            openAt = LevelDirector.gluttonOpenThreshold(s.level),
                            biteAt = LevelDirector.gluttonBiteThreshold(s.level)
                        )
                    gluttonCounter = nextC
                    when {
                        shouldBite && mouthOpen -> {
                            val cornerCells = GameState.gluttonCornerCells(gluttonCorner)
                            val bitten = com.cukiti.teikafusion.model.GluttonBiomeRules
                                .biteableCells(cornerCells)
                            // La dentellada ESCUPE hacia dentro cualquier Teika apoyado en el rincón,
                            // en vez de saltarse su celda (con un cuerpo ahí el mordisco se comía 1
                            // sola casilla y el bioma parecía roto — playtest 2026-07-20).
                            val cornerSet = cornerCells.toSet()
                            val (pdx, pdy) = com.cukiti.teikafusion.model.GluttonBiomeRules
                                .pushDirectionFromCorner(gluttonCorner)
                            physicsWorld.occupiedCells()
                                .filterKeys { it in cornerSet }
                                .values.toSet()
                                .forEach { bodyId ->
                                    physicsWorld.launchBody(bodyId, pdx * GLUTTON_BITE_PUSH, pdy * GLUTTON_BITE_PUSH)
                                }
                            // El mordisco vacía TODA la madera del triángulo (incl. estrellas). Un bloque
                            // con estrella se traga y su objetivo se ACREDITA (no se pierde ni queda
                            // flotando en la boca). El pozo ocupa el hueco del rincón (celda vacía = dead).
                            bitten.forEach { p ->
                                val w = ninjaGrid[p] as? CellContent.Wood
                                if (w != null) {
                                    if (w.targetColor != null) {
                                        gluttonEatenTargets[w.targetColor] =
                                            (gluttonEatenTargets[w.targetColor] ?: 0) + 1
                                    }
                                    ninjaGrid[p] = CellContent.Empty
                                }
                            }
                            // Marca dead en todas las biteable (incl. vacías) para el pozo del triángulo.
                            val pitCells = bitten
                            if (pitCells.isNotEmpty()) {
                                gluttonDead = gluttonDead + pitCells.associateWith {
                                    LevelDirector.gluttonRecoverTurns(s.level)
                                }
                                events.add(GameEvent.GluttonBite(gluttonCorner, pitCells))
                                soundManager.playGluttonBite()
                            } else {
                                events.add(GameEvent.GluttonRetreat(gluttonCorner)).also { soundManager.playGluttonRetreat() }
                            }
                            gluttonCounter = 0
                            gluttonCorner = -1
                        }
                        shouldOpen && !mouthOpen -> {
                            val eligible = com.cukiti.teikafusion.model.GluttonBiomeRules.eligibleCorners(
                                gluttonDead.keys
                            )
                            if (eligible.isEmpty()) {
                                // Sin rincón libre: no "open fantasma". Congela presión y libera
                                // el pozo más cerca de digiérese para que el bioma vuelva a amenazar.
                                gluttonCounter = com.cukiti.teikafusion.model.GluttonBiomeRules
                                    .holdCounterWhenNoCorner(
                                        LevelDirector.gluttonOpenThreshold(s.level)
                                    )
                                gluttonCorner = -1
                                if (gluttonDead.isNotEmpty()) {
                                    val before = gluttonDead.keys
                                    gluttonDead = com.cukiti.teikafusion.model.GluttonBiomeRules
                                        .freeOneCorner(gluttonDead)
                                    (before - gluttonDead.keys).forEach { p ->
                                        events.add(GameEvent.Particles(p, -1))
                                    }
                                }
                            } else {
                                gluttonCorner = eligible.random(rng)
                                events.add(GameEvent.GluttonOpen(gluttonCorner))
                                soundManager.playGluttonOpen()
                            }
                        }
                    }
                }
            }

            // Mansión Espectral · EL ESPEJO EMBRUJADO (P-246, 2026-09-23; sustituye a la cacería). Reglas
            // en [HauntedMirror]. Tres tiempos, como todo bioma: se EMPAÑA (elige la mitad), se ve el
            // REFLEJO (la UI enseña dónde caerán los fantasmas) y al tercero DESTELLA. Romper una línea
            // lo empaña y vuelve a cero. Los fantasmas ya puestos cuentan sus turnos en cada colocación.
            var ghostIdle = s.ghostIdleTurns
            var mirrorSource = s.mirrorSource
            if (s.biomePrimary == com.cukiti.teikafusion.model.BiomeType.GHOST) {
                // 1) Los fantasmas que ya estaban cumplen un turno; a cero se desvanecen.
                val fading = mutableListOf<Position>()
                val fadingColors = mutableListOf<Int>()
                ninjaGrid.entries.filter { (_, c) -> c is CellContent.Wood && c.phantom > 0 }.forEach { (p, c) ->
                    val w = c as CellContent.Wood
                    if (w.phantom <= 1) {
                        ninjaGrid[p] = CellContent.Empty
                        fading += p; fadingColors += w.colorType
                    } else ninjaGrid[p] = w.copy(phantom = w.phantom - 1)
                }
                if (fading.isNotEmpty()) events.add(GameEvent.PhantomFade(fading, fadingColors))

                // 2) El reloj del espejo.
                val teikaOccMirror = teikaBlockedCells()
                val unplaceableMirror = s.unplaceableCells
                val freeForPhantom: (Position) -> Boolean = { t ->
                    ninjaGrid[t] is CellContent.Empty && t !in teikaOccMirror && t !in unplaceableMirror &&
                        t !in s.hiddenWoodCells
                }
                // P-353: el espejo SIEMPRE avanza. Parada perfecta en el turno del destello: romper una línea
                // entera DENTRO de la mitad que se refleja (una columna de esa mitad, o una fila si el
                // espejo es horizontal). Mitigar: menos madera en esa mitad = menos fantasmas.
                run {
                    ghostIdle += 1
                    val mirrorAt = LevelDirector.mirrorThreshold(s.level)
                    if (ghostIdle >= mirrorAt && mirrorSource != com.cukiti.teikafusion.model.HauntedMirror.NONE) {
                        val inHalf = ghostHalfParried(mirrorSource, parryRows, parryCols)
                        if (inHalf) {
                            ghostIdle = 0
                            mirrorSource = com.cukiti.teikafusion.model.HauntedMirror.NONE
                            parry(com.cukiti.teikafusion.model.BiomeType.GHOST)
                        }
                    }
                    if (mirrorSource == com.cukiti.teikafusion.model.HauntedMirror.NONE && ghostIdle in 1 until mirrorAt &&
                        ghostIdle >= LevelDirector.mirrorWarnThreshold(s.level)
                    ) {
                        // SE EMPAÑA: el espejo elige la mitad que más fantasmas dejaría.
                        mirrorSource = com.cukiti.teikafusion.model.HauntedMirror.chooseSource(
                            ninjaGrid, freeForPhantom,
                            listOf(
                                com.cukiti.teikafusion.model.HauntedMirror.LEFT,
                                com.cukiti.teikafusion.model.HauntedMirror.RIGHT,
                                com.cukiti.teikafusion.model.HauntedMirror.TOP,
                                com.cukiti.teikafusion.model.HauntedMirror.BOTTOM
                            ).shuffled(rng)
                        )
                        soundManager.playMirrorMist()
                    }
                    if (ghostIdle >= LevelDirector.mirrorThreshold(s.level) &&
                        mirrorSource != com.cukiti.teikafusion.model.HauntedMirror.NONE
                    ) {
                        val phantoms = com.cukiti.teikafusion.model.HauntedMirror.phantomsFor(
                            ninjaGrid, mirrorSource, freeForPhantom
                        )
                        if (phantoms.isNotEmpty()) {
                            // DESTELLA: los fantasmas aparecen ya en el estado; el VFX los hace salir
                            // del espejo hacia su casilla.
                            phantoms.forEach { (t, color) ->
                                ninjaGrid[t] = com.cukiti.teikafusion.model.HauntedMirror.phantomWood(color)
                            }
                            events.add(GameEvent.MirrorFlash(mirrorSource, phantoms))
                            events.add(GameEvent.ScreenShake(1.1f))
                            soundManager.playMirrorFlash()
                            ghostIdle = 0; mirrorSource = com.cukiti.teikafusion.model.HauntedMirror.NONE
                        } else {
                            // P-353: nada que reflejar (mitad vacía u otra llena) = el jugador lo mitigó
                            // del todo. El ciclo vuelve a empezar.
                            ghostIdle = 0; mirrorSource = com.cukiti.teikafusion.model.HauntedMirror.NONE
                        }
                    }
                }
                // P-353: turno del destello sin espejo empañado: el ciclo vuelve a empezar.
                if (ghostIdle >= LevelDirector.mirrorThreshold(s.level) &&
                    mirrorSource == com.cukiti.teikafusion.model.HauntedMirror.NONE
                ) ghostIdle = 0
            } else {
                ghostIdle = 0; mirrorSource = com.cukiti.teikafusion.model.HauntedMirror.NONE
            }

            // ── Cielo Estelar / Evento Astral (idle-gated, PESADO solo primario) ────────────────────────
            // Sol → INCINERA 1 Teika (láser que se intensifica + explosión). Luna → rapta el 50% de los
            // BLOQUES-ESTRELLA (objetivo) al azar. AUTÓNOMO: al emerger, el astro DISPARA SOLO tras el
            // aviso (STAR_ASTRO_WARN_MS, ver fireAstroStrike) — no espera otra colocación ni existe
            // retirada por actividad. El único contrajuego es no estar ocioso 3 turnos.
            var astroIdle = s.starAstroIdleCounter
            var astroEmerged = s.starAstroEmerged
            var astroBody = s.starAstroBody
            var astroOmen = s.starAstroOmen
            var astroTargetId = s.starAstroTargetTeikaId
            var astroTargetCells = s.starAstroTargetCells
            var astroMoonWoods = s.starAstroMoonWoodCells
            var astroCooldown = s.starAstroCooldown
            // Fase 3: el astro es SOLO del Cielo Estelar. El Infinito dejó de invocarlo por fase.
            val astroIdleAt = LevelDirector.starIdleThreshold(s.level)
            if (s.biomePrimary == com.cukiti.teikafusion.model.BiomeType.STAR) {
                // La Luna se lleva BLOQUES-ESTRELLA (objetivo). Solo estrellas "limpias" (sin bobina).
                fun isMoonStarWood(c: CellContent): Boolean {
                    val w = c as? CellContent.Wood ?: return false
                    return w.targetColor != null && w.coil == 0
                }
                val astroTeikas = _teikaBodies.value.filter { it.frozenTurns == 0 && !it.kinematic }
                if (astroEmerged) {
                    // Disparo EN VUELO: lo ejecuta fireAstroStrike (corrutina) — el tick no interviene.
                } else if (astroCooldown > 0) {
                    astroCooldown -= 1; astroIdle = 0; astroOmen = com.cukiti.teikafusion.model.StarAstroOmen.NONE
                } else {
                    // P-353: el astro SIEMPRE llega. En el aviso 2 MARCA a su presa (el Teika del Sol o las
                    // estrellas de la Luna); parada perfecta: una línea por lo marcado en el turno del golpe.
                    astroIdle += 1
                    // EL PRESAGIO (2026-09-23): el astro se sortea 50/50 al primer turno ocioso y se
                    // anuncia en el tablero; ya no se elige al disparar entre los que tienen presa.
                    // P-360 (2026-09-28): el Sol sale 1 de cada 3 veces (antes 50/50). Medido con el bot, el Sol
                    // AYUDA: quema el Teika más grande y, con el tablero lleno de cuerpos, eso libera sitio (con
                    // el Sol 3 de 4 el Estelar subió al 80 %). La Luna devuelve lo que roba como madera sin
                    // estrella, que ocupa. Estelar 75 % con el dial al tope, objetivo 60 %.
                    astroOmen = com.cukiti.teikafusion.model.StarAstroOmen.next(astroOmen, astroIdle) {
                        rng.nextInt(3) == 0
                    }
                    if (astroIdle == astroIdleAt - 1) {
                        // EL AVISO 2 MARCA: el Sol, al Teika más grande; la Luna, sus estrellas.
                        if (astroOmen == 1) {
                            astroTargetId = astroTeikas.maxByOrNull { it.type.level }?.id
                            astroMoonWoods = emptySet()
                        } else if (astroOmen == 2) {
                            val stars = ninjaGrid.filter { (_, c) -> isMoonStarWood(c) }.keys.toList()
                            astroMoonWoods = stars.shuffled(rng).take(LevelDirector.starVictimCount(stars.size, s.level)).toSet()
                            astroTargetId = null
                        }
                    }
                    if (astroIdle >= astroIdleAt) {
                        val markedCells = starParryZone(astroMoonWoods, astroTargetId)
                        if (markedCells.any { it in parryCells }) {
                            parry(com.cukiti.teikafusion.model.BiomeType.STAR)
                            astroIdle = 0; astroOmen = com.cukiti.teikafusion.model.StarAstroOmen.NONE
                            astroTargetId = null; astroMoonWoods = emptySet(); astroTargetCells = emptySet()
                        }
                    }
                    if (astroIdle >= astroIdleAt) {
                        val hasStars = ninjaGrid.values.any { isMoonStarWood(it) }
                        val body = astroOmen
                        // Mitigar: si el marcado ya no está (fundido), el Sol se queda sin Teika.
                        val victim = if (body == 1) astroTeikas.firstOrNull { it.id == astroTargetId } else null
                        // Sol sin Teika: calcina el bloque más cercano al centro (sin estrella si puede).
                        val sunWood = if (body == 1 && victim == null) {
                            com.cukiti.teikafusion.model.StarAstroOmen.sunWoodTarget(
                                wood = ninjaGrid.filter { (_, c) -> c is CellContent.Wood && c.coil == 0 }.keys,
                                stars = ninjaGrid.filter { (_, c) -> isMoonStarWood(c) }.keys
                            )
                        } else null
                        val canFire = when (body) {
                            1 -> victim != null || sunWood != null
                            2 -> hasStars && astroMoonWoods.any { p -> ninjaGrid[p]?.let { isMoonStarWood(it) } == true }
                            else -> false
                        }
                        if (canFire) {
                            // Sol: marca Teika (o un bloque). Luna: marca el 50% de las estrellas.
                            astroBody = body
                            astroTargetId = victim?.id
                            val teikaCells = victim?.let { v ->
                                physicsWorld.occupiedCells().filterValues { it == v.id }.keys
                                    .ifEmpty { setOf(bodyTopLeftCell(v)) }
                            } ?: emptySet()
                            // La Luna se lleva SOLO lo marcado que siga siendo estrella (cobrarlas antes mitiga).
                            astroMoonWoods = if (body == 2) {
                                astroMoonWoods.filterTo(HashSet()) { p -> ninjaGrid[p]?.let { isMoonStarWood(it) } == true }
                            } else setOfNotNull(sunWood)   // el bloque que el Sol calcina, si no hay Teika
                            astroTargetCells = teikaCells + astroMoonWoods
                            astroEmerged = true; astroIdle = 0; astroOmen = com.cukiti.teikafusion.model.StarAstroOmen.NONE
                            events.add(GameEvent.AstroEmerge(body, astroTargetCells.toList()))
                            soundManager.playAstroEmerge(body)
                            fireAstroStrike()   // el astro dispara SOLO tras el aviso
                        } else {
                            // P-353: sin presa (el jugador lo mitigó del todo, o no había nada): el ciclo vuelve a
                            // empezar. Nunca sale el contrario al anunciado.
                            astroIdle = 0; astroOmen = com.cukiti.teikafusion.model.StarAstroOmen.NONE
                            astroTargetId = null; astroMoonWoods = emptySet()
                        }
                    }
                }
            } else {
                astroIdle = 0; astroEmerged = false; astroBody = 0; astroOmen = com.cukiti.teikafusion.model.StarAstroOmen.NONE
                astroTargetId = null; astroTargetCells = emptySet()
                astroMoonWoods = emptySet(); astroCooldown = 0
            }

            // ── Fuego/Volcán: la lava reacciona a lo que ESTA colocación acaba de romper ─────────────
            // (el tick corre DESPUÉS de resolver la cadena: sin "atraso de un turno"). SOLO las roturas
            // reales (volcanoClears) hacen retroceder la lava — energizar una fila con bobinas NO cuenta
            // (ni como rotura ni como turno de presión: stormEnergized congela la presión ese turno).
            var newLavaRow = s.lavaRow
            var newVolcanoDryTurns = s.volcanoDryTurns
            var volcanoGameOver = false
            if (com.cukiti.teikafusion.model.BiomeType.VOLCANO in active) {
                if (stormEnergized) {
                    // fila convertida en circuito → turno neutro para el volcán
                } else {
                    // P-353: la lava SIEMPRE baja al final del ciclo (las líneas la hacen retroceder al
                    // instante, 1 fila cada una). Parada perfecta: romper DOS líneas en el turno del descenso.
                    val pressure = nextVolcanoPressure(
                        currentDryTurns = s.volcanoDryTurns,
                        linesCleared = 0,
                        lavaRow = s.lavaRow,
                        firstThreshold = LevelDirector.volcanoFirstThreshold(s.level),
                        surfacedThreshold = LevelDirector.volcanoSurfacedThreshold(s.level)
                    )
                    newVolcanoDryTurns = pressure.dryTurns
                    if (pressure.advanceLava && volcanoClears >= VOLCANO_PARRY_LINES) {
                        parry(com.cukiti.teikafusion.model.BiomeType.VOLCANO)
                    } else if (pressure.advanceLava) {
                        run {
                            val lavaAdvance = advanceLavaFromTop(
                                ninjaGrid,
                                events,
                                s.lavaRow,
                                1,
                                blockedCells = s.unplaceableCells,
                                busyIds = s.busyTeikaIds
                            )
                            newLavaRow = lavaAdvance.lavaRow
                            if (newLavaRow >= GameState.GRID_SIZE) volcanoGameOver = true
                        }
                    }
                }
            } else {
                newVolcanoDryTurns = 0
            }

            val plantTargetsCollected = s.targetsCollected.toMutableMap()
            plantTargetGains.forEach { (color, amount) ->
                plantTargetsCollected[color] = (plantTargetsCollected[color] ?: 0) + amount
            }
            // Glotón: estrellas tragadas por el mordisco cuentan como recogidas (no se pierde objetivo).
            gluttonEatenTargets.forEach { (color, amount) ->
                plantTargetsCollected[color] = (plantTargetsCollected[color] ?: 0) + amount
            }
            val biomeState = s.copy(
                biomeTurnCounter = turn, drowsyTurns = drowsy, drowsyPieceId = drowsyPiece,
                drowsyMarkedId = drowsyMarked,
                sleepIdleTurns = sleepIdle,
                fearCalmTurns = fearCalm,
                ninjaIdleTurns = ninjaIdle,
                ninjaCutActive = ninjaCutOn, ninjaCutLinesLeft = ninjaCutLeft, ninjaCutTurns = ninjaCutTurns,
                ninjaTruceTurns = ninjaTruce,
                starAstroIdleCounter = astroIdle, starAstroEmerged = astroEmerged, starAstroBody = astroBody,
                starAstroOmen = astroOmen,
                starAstroTargetTeikaId = astroTargetId, starAstroTargetCells = astroTargetCells,
                starAstroMoonWoodCells = astroMoonWoods,
                starAstroCooldown = astroCooldown,
                grid = ninjaGrid, events = events,
                targetsCollected = plantTargetsCollected,
                glacierFrostCells = glacierFrost,
                glacierIdleTurns = glacierIdle,
                ghostIdleTurns = ghostIdle, mirrorSource = mirrorSource,
                gluttonCounter = gluttonCounter, gluttonCorner = gluttonCorner, gluttonDeadCells = gluttonDead,
                hiddenWoodCells = starHidden,
                toxicDecayCounter = toxicDecay,
                toxicFront = toxicFront,
                kingSwordAxis = swordAxis, kingSwordLine = swordLine, kingSwordIdle = swordIdle,
                kingPieceKind = pieceKind, kingPieceA = pieceA, kingPieceB = pieceB,
                kingPieceBlack = pieceBlack, kingPieceFromEnd = pieceFromEnd, kingPieceNext = pieceNext,
                kingPiecesInRow = piecesInRow,
                kingLaneCells = laneCells, kingLaneTurns = laneTurns,
                kingRestCell = restCell, kingRestKind = restKind, kingRestBlack = restBlack,
                meteorAt = meteorAt,
                meteorAt2 = meteorAt2,
                // La UI del meteorito necesita saber en qué turno del aviso va (asoma → cráter marcado).
                galacticIdleSaved = galacticIdleCounter,
                busyTeikaIds = plantBusyIds,
                plantIdleTurns = plantIdleTurns,
                plantMarkEdge = plantMarkEdge, plantMarkTeikaId = plantMarkTeika,
                plantAbduction = plantAbduction,
                lavaRow = newLavaRow,
                volcanoDryTurns = newVolcanoDryTurns,
                // C-3 (2026-09-02): la lava mataba con un `GAME_OVER` directo y se saltaba las
                // CUATRO cosas que hacen que perder pese — no ofrecía revivir, no cobraba vida
                // (`spendLifeForDefeat` no se llamaba por aquí), no registraba el fallo en
                // analytics, no corría el barrido dominó (la pantalla se quedaba quieta el segundo
                // y medio que espera `GameScreen`) y no borraba el save, con lo que quedaba una
                // partida ya perdida marcada como reanudable. Ahora muere como todas: REVIVE_OFFER,
                // y si el jugador declina, `declineRevive` hace las cuatro.
                status = if (volcanoGameOver)
                    com.cukiti.teikafusion.model.GameStatus.REVIVE_OFFER else s.status,
                defeatCause = if (volcanoGameOver)
                    com.cukiti.teikafusion.model.DefeatCause.LAVA else s.defeatCause,
                score = s.score
            ).let { after ->
                // ── P-228 · ¿QUIÉN TE HA DEJADO SIN SITIO? ───────────────────────────────────────
                // Se responde AQUÍ, con una resta, en vez de cablear catorce mecánicas: si el tick
                // ha dejado menos casillas libres y jugables de las que había, el castigo del bioma
                // te ha quitado sitio, y el cartel «SIN SALIDA» puede decirlo con nombre y apellido.
                // Si no, el tablero se llenó jugando y la culpa es del jugador — que es exactamente
                // lo que el cartel debe seguir diciendo entonces.
                val squeezed = after.playableFreeCells < freeCellsBeforeTick
                after.copy(lastSqueezeBiome = if (squeezed) s.biomePrimary else null)
            }
            _gameState.value = if (biomeState.status == com.cukiti.teikafusion.model.GameStatus.PLAYING) {
                checkObjectiveCompletion(biomeState)
            } else {
                biomeState
            }
            // CORTE NINJA recién abierto: el tablero acaba de PARTIRSE en dos mitades de 4 columnas,
            // y las fichas que el jugador tenía en la mano se repartieron para un tablero de 8. Una
            // I5 (5 de ancho) ya no cabe en ninguna mitad.
            //
            // Aquí se sustituían las fichas que el tajo dejaba sin sitio. **Retirado el 2026-09-07
            // por decisión expresa del usuario**, que eligió quitar el reparador «del todo, también
            // en el Corte Ninja». Consecuencia asumida y que hay que mirar en el playtest: el tajo
            // PUEDE dejar la bandeja muerta en el acto, y entonces se pierde por el castigo del
            // bioma. El aviso de dos turnos del corte es la contrajugada: hay que llegar a él sin
            // fichas anchas en la mano.
            //
            // Lo que sí hace el tajo es dejar la bandeja MARCADA (P-229): la ficha que ya no cabe se
            // apaga en el acto, en el mismo turno en que el tablero se parte. Y como el tajo quita
            // sitio jugable, el balance de hueco de aquí abajo lo señala como culpable (P-228).
            // (D-GO: en Infinito la lava ya no remata la partida — ver comentario de `status`.)
          } catch (e: Exception) {
            // Una mecánica de bioma (decreto del Rey, gravedad estelar, singularidad, etc.) NUNCA debe
            // tumbar la partida. Si algo lanza, se registra y el turno simplemente no avanza el reloj.
            android.util.Log.e("GameViewModel", "applyBiomeTick falló (mecánica de bioma): ${e.message}", e)
          }
        }
    }



    // (RETIRADO 2026-09-26) `spawnDeferredTeikas` / `PendingSpawn`: código muerto, sin productor ni llamante.


    // ── Helper: celdas ocupadas por un Teika en una posición raíz ────────────
    private fun cellsAt(root: Position, type: TeikaType): Set<Position> {
        val out = mutableSetOf<Position>()
        for (dx in 0 until type.width) for (dy in 0 until type.height) {
            out.add(Position(root.x + dx, root.y + dy))
        }
        return out
    }

    /**
     * Fuego/Volcán: la lava AVANZA desde ARRIBA (baja una fila). [oldLavaRow]/return = nº de filas
     * SUPERIORES cubiertas; la zona cubierta es [0, newLavaRow) y la jugable [newLavaRow, GRID).
     * CADA Teika se desplaza hacia abajo el mismo número de filas que avanza la lava. El movimiento
     * se planifica y aplica de forma atómica, así las cadenas ocupan las celdas que va liberando el
     * Teika inferior. Solo mueren los que ya no caben dentro del borde inferior del tablero.
     */
    private fun advanceLavaFromTop(
        grid: MutableMap<Position, CellContent>,
        events: MutableList<GameEvent>,
        oldLavaRow: Int,
        rowsToAdvance: Int,
        blockedCells: Set<Position> = emptySet(),
        busyIds: Set<String> = emptySet()
    ): LavaAdvanceResult {
        if (rowsToAdvance <= 0) return LavaAdvanceResult(oldLavaRow, emptySet())
        val GRID = GameState.GRID_SIZE
        val newLavaRow = (oldLavaRow + rowsToAdvance).coerceAtMost(GRID)
        if (newLavaRow <= oldLavaRow) return LavaAdvanceResult(oldLavaRow, emptySet())

        // Quemar (vaciar) las filas cubiertas por la lava: [0, newLavaRow).
        for (yy in 0 until newLavaRow) {
            for (xx in 0 until GRID) {
                grid[Position(xx, yy)] = CellContent.Empty
            }
        }
        // Motor físico: los CUERPOS cuyo centro queda dentro de la lava se QUEMAN (poof); los que
        // solo la rozan son empujados hacia abajo frame a frame por el techo de lava (la zona
        // cubierta es terreno sólido en physicsTerrainCells).
        val burnedBodies = physicsWorld.snapshot().filter { it.y < newLavaRow }
        if (burnedBodies.isNotEmpty()) {
            burnedBodies.forEach { b ->
                physicsWorld.removeBody(b.id)
                events.add(GameEvent.Particles(bodyTopLeftCell(b), -1))
            }
            _teikaBodies.value = physicsWorld.snapshot()
        }
        // LA ERUPCIÓN (P-65): la ola que rompe hacia abajo, la salpicadura y las brasas. Antes esto
        // era mudo en pantalla — solo se veía la superficie deslizarse con su tween.
        events.add(GameEvent.LavaSurge(oldLavaRow, newLavaRow, burnedBodies.size))
        // SACUDIDA PROPORCIONAL A LO QUE YA TE HA COMIDO. Era una constante (0,5 + 0,15·filas, y
        // `rowsToAdvance` siempre vale 1, así que SIEMPRE 0,65): la primera fila de lava sacudía
        // exactamente igual que la séptima, con el tablero a punto de perderse. Ahora crece con la
        // fila alcanzada, así que la presión del bioma se siente en la mano, y sube otro escalón si
        // además se ha llevado Teikas por delante.
        val depth = newLavaRow.toFloat() / GRID
        val burnKick = if (burnedBodies.isNotEmpty()) 0.7f else 0f
        events.add(GameEvent.ScreenShake(0.55f + depth * 1.6f + burnKick))
        soundManager.playLavaSurge()
        return LavaAdvanceResult(newLavaRow, emptySet())
    }


    /**
     * @param silent sin chime de monedas. Es para las concesiones que ocurren **sin ventana**: la
     * racha del arranque y el barrido de murales pendientes corren detras del splash, y ahi el
     * sonido de recompensa se oia solo, sobre la barra de carga (2026-09-04, pedido del usuario).
     */
    fun grantTeikoins(amount: Int, silent: Boolean = false) {
        _gameState.update { it.copy(teikoins = (it.teikoins + amount).coerceAtLeast(0)) }
        if (amount > 0 && !silent) soundManager.playTeikoinGain()
        viewModelScope.launch { prefs.saveTeikoins(_gameState.value.teikoins) }
    }

    fun awardXp(amount: Int) {
        if (amount <= 0) return
        viewModelScope.launch {
            xpMutex.withLock {
                val old = _totalXp.value
                val newTotal = prefs.addXp(amount)
                _totalXp.value = newTotal
                // Celebración de rango (V-03): solo si se cruza un umbral de la tabla.
                com.cukiti.teikafusion.model.PlayerRank.rankAfterXpGain(old, newTotal)?.let { rank ->
                    _rankUpCelebration.value = rank
                    // Cue PROPIO desde 2026-07-31 (antes tomaba prestado `snd_mega`, o sea que subir
                    // de rango sonaba igual que formar un MEGA). Desde el 2026-09-04 lo dispara **su
                    // overlay** y no esta linea: el XP del primer juego del dia se otorga en el
                    // arranque, detras del splash, y la fanfarria salia sola sobre la barra de carga
                    // mientras la ventana esperaba (esta gateada por `!inSplash`). Ver AppNavigation.
                    Analytics.trackRankUp(rank.name, newTotal)
                }
            }
        }
    }

    /** Arma el tracking de récord de puntos de esta ronda (highScore al entrar). */
    private fun armPersonalScoreRecordTracking(currentHighScore: Int) {
        personalScoreRecordFloor = currentHighScore
        personalScoreRecordXpGiven = false
    }

    /**
     * +[XpAward.PERSONAL_RECORD] la primera vez en la ronda que [newScore] supera el highScore
     * con el que se arrancó. No premia batir el 0 (primera partida de la vida).
     */
    private fun maybeAwardScoreRecordXp(newScore: Int) {
        if (personalScoreRecordXpGiven) return
        if (personalScoreRecordFloor <= 0) return
        if (newScore <= personalScoreRecordFloor) return
        personalScoreRecordXpGiven = true
        awardXp(com.cukiti.teikafusion.model.XpAward.PERSONAL_RECORD)
    }

    fun setMaxLevel(level: Int) {
        // +1: al superar el último nivel, la frontera vale totalLevels+1 (sentinel de "juego
        // terminado" que marca el mural final como COMPLETO). Restaurar de nube no debe perderlo.
        val clamped = level.coerceIn(1, com.cukiti.teikafusion.model.LevelMap.totalLevels + 1)
        _gameState.update { it.copy(maxUnlockedLevel = clamped) }
        viewModelScope.launch { prefs.forceSetMaxLevel(clamped) }
        viewModelScope.launch { syncSkippedMuralRewards(clamped) }
    }

    /**
     * Otorga la recompensa de mural de cualquier capítulo cuyo último nivel haya quedado por
     * debajo de [newMaxLevel] pero que aún no se hubiera pagado — cubre saltos de nivel que se
     * saltan la celebración normal de fin de capítulo (restauración en la nube, override admin).
     * `markMuralRewarded` es un check-and-set atómico: nunca paga dos veces el mismo capítulo.
     */
    private suspend fun syncSkippedMuralRewards(newMaxLevel: Int) {
        com.cukiti.teikafusion.model.LevelMap.chapters.indices.forEach { i ->
            if (com.cukiti.teikafusion.model.LevelMap.chapterLastLevel(i) < newMaxLevel) {
                if (prefs.markMuralRewarded(i)) {
                    // SILENCIOSO: este barrido corre al restaurar progreso (nube, override admin),
                    // sin ninguna ventana que ensenar. Ver [grantTeikoins].
                    grantTeikoins(MURAL_REWARD_BASE + i * MURAL_REWARD_PER_CHAPTER, silent = true)
                }
            }
        }
    }

    /**
     * **NINGUNA ESTRELLA MUERTA** (2026-08-26, pedido del usuario).
     *
     * Cuando un color del objetivo queda cubierto, las estrellas suyas que siguen en el tablero —y
     * en las fichas que el jugador tiene en la mano— dejan de valer: siguen pintadas como objetivo y
     * romperlas ya no mueve el contador. Aquí se retintan al color que más falta, repartidas por
     * déficit ([StarObjectiveRetint]).
     *
     * Vive colgado de [checkObjectiveCompletion] a propósito: es el embudo por el que pasan las 19
     * rutas que tocan `targetsCollected` (línea rota, cosecha del MEGA, habilidades de compañero,
     * rescates…), así que la mutación ocurre **en el instante** en que el color se cubre, venga de
     * donde venga, y con un solo sitio que mantener. La guarda [StarObjectiveRetint.hasWork] hace que
     * el caso normal —objetivo con trabajo pendiente en todos sus colores— no recorra nada.
     */
    private fun GameState.withStarRetint(): GameState {
        val required = levelObjective?.required ?: return this
        if (status != com.cukiti.teikafusion.model.GameStatus.PLAYING) return this
        if (!com.cukiti.teikafusion.model.StarObjectiveRetint.hasWork(required, targetsCollected)) return this

        val satisfied = com.cukiti.teikafusion.model.StarObjectiveRetint
            .satisfiedColors(required, targetsCollected)
        // Orden estable (arriba-abajo, izquierda-derecha): el reparto por déficit tiene que dar el
        // mismo resultado en dos partidas con el mismo tablero, y `grid` es un mapa sin orden.
        val deadCells = grid.entries
            .mapNotNull { (p, c) ->
                p.takeIf { c is CellContent.Wood && c.targetColor != null && c.targetColor in satisfied }
            }
            .sortedWith(compareBy({ it.y }, { it.x }))
        val deadInTray = availablePieces.sumOf { piece ->
            piece.targetMask.count { it != null && it in satisfied }
        }
        if (deadCells.isEmpty() && deadInTray == 0) return this

        val assignment = com.cukiti.teikafusion.model.StarObjectiveRetint
            .assign(required, targetsCollected, deadCells.size + deadInTray)
        if (assignment.isEmpty()) return this

        // El tablero cobra primero (es lo que el jugador está mirando); lo que sobre va a la bandeja.
        val boardPlan = deadCells.take(assignment.size)
            .mapIndexed { i, p -> p to assignment[i] }
            .toMap()
        var trayCursor = boardPlan.size
        val newGrid = if (boardPlan.isEmpty()) grid else grid.toMutableMap().also { g ->
            boardPlan.forEach { (p, color) ->
                val wood = g[p] as? CellContent.Wood ?: return@forEach
                g[p] = wood.copy(targetColor = color)
            }
        }
        val newPieces = if (trayCursor >= assignment.size) availablePieces else availablePieces.map { piece ->
            if (piece.targetMask.none { it != null && it in satisfied }) return@map piece
            val mask = piece.targetMask.map { current ->
                if (current == null || current !in satisfied) current
                else assignment.getOrNull(trayCursor++) ?: current
            }
            piece.copy(targetMask = mask)
        }

        val newEvents = if (boardPlan.isEmpty()) events else events + GameEvent.StarRetint(
            boardPlan.map { (p, color) -> GameEvent.StarRetint.Retinted(p, color) }
        )
        if (boardPlan.isNotEmpty()) soundManager.playStarRetint()
        return copy(grid = newGrid, availablePieces = newPieces, events = newEvents)
    }

    private fun checkObjectiveCompletion(rawState: GameState, elapsedFxMs: Long = 0L): GameState {
        val state = rawState.withStarRetint()
        val objective = state.levelObjective ?: return state
        if (state.status != com.cukiti.teikafusion.model.GameStatus.PLAYING) return state
        val minRequiredPerColor = _remoteConfig.value.gatingStarsRequiredPerLevel.coerceAtLeast(1)
        val tutorialSpec = com.cukiti.teikafusion.model.TutorialCampaign.spec(state.level)
        // LOS CUATRO SABORES DE NIVEL (2026-07-31b). Hasta hoy solo existía el primero.
        val allMet = if (tutorialSpec != null) {
            val linesMet = state.linesClearedInLevel >= tutorialSpec.requiredLines
            val tierMet = tutorialSpec.targetTeika?.let { target ->
                (state.teikasCreatedInLevel[target] ?: 0) >= 1
            } ?: true
            // P-87 (2026-09-02): **la lección de habilidades se aprueba LANZANDO**, y solo así. Su
            // tablero son tres filas a las que faltan dos celdas, así que el hito de líneas era
            // alcanzable a mano y despedía al jugador con «¡HABILIDAD LANZADA!» sin que hubiera
            // lanzado nada. Ver [GameState.tutorialAbilityCast].
            val castMet = !tutorialSpec.teachesAbility || state.tutorialAbilityCast
            linesMet && tierMet && castMet
        } else {
            when (objective.goal) {
                com.cukiti.teikafusion.model.LevelGoal.STARS ->
                    objective.required.all { (color, needed) ->
                        (state.targetsCollected[color] ?: 0) >= maxOf(needed, minRequiredPerColor)
                    }
                com.cukiti.teikafusion.model.LevelGoal.LINES ->
                    state.linesClearedInLevel >= objective.amount
                // DESPEJE: se cuenta la madera del JUGADOR. El hormigón del muro (Infinito) y los Teikas
                // —que ni siquiera viven en el grid— no son suyos y exigir que desaparezcan haría el
                // objetivo imposible.
                com.cukiti.teikafusion.model.LevelGoal.CLEAR ->
                    state.grid.values.count { it is CellContent.Wood } <= objective.amount
                com.cukiti.teikafusion.model.LevelGoal.SURVIVE ->
                    state.placementsInLevel >= objective.amount
            }
        }
        if (!allMet) return state
        // El mapa regular conserva el Mega obligatorio. En el tutorial cada spec gobierna su hito y
        // [ChapterArc.requiresMega] solo devuelve true para la cuarta lección.
        val megaFormed = (state.teikasCreatedInLevel[TeikaType.MEGA_TEIKA] ?: 0) >= 1
        if (com.cukiti.teikafusion.model.ChapterArc.requiresMega(state.level) && !megaFormed) {
            // P-263: estrellas hechas, falta el MEGA → el HUD lo dice (ver [GameState.megaPending]).
            return if (state.megaPending) state else state.copy(megaPending = true)
        }
        // (RETIRADO 2026-09-22, decisión del usuario) Aquí esperaba EL PEDIDO (P-82): un nivel con
        // pedido no se cerraba hasta haber criado el Teika que pedía. La victoria vuelve a ser
        // estrellas + MEGA, sin puertas extra.
        // El Mega Teika ACABA de formarse (su espectáculo de limpieza está en vuelo): esperar a que
        // termine antes de abrir la ventana de nivel completado.
        val hasMegaAnimation = state.events.any { it is GameEvent.MegaTeikaFriendExpansion }
        val stateWithTurnBonus = state
        // El Mega ya se formó ANTES de completar el target (su espectáculo ya se vio al formarse):
        // NO se vuelve a mostrar el Mega de ninguna forma. Aun así el nivel NO se cierra en el mismo
        // frame: la jugada que completa el objetivo es justo la que manda las últimas estrellas a
        // volar hacia el panel, y la ventana de victoria aparecía ENCIMA de ellas — el jugador nunca
        // llegaba a ver completarse su propio objetivo. Se pasa por PENDING y lo confirma un reloj.
        if (!hasMegaAnimation) scheduleLevelCompleteConfirm(stateWithTurnBonus,elapsedFxMs)
        return stateWithTurnBonus.copy(
            status = com.cukiti.teikafusion.model.GameStatus.LEVEL_COMPLETE_PENDING
        )
    }

    /** Espera que se le da al jugador tras aterrizar la ÚLTIMA estrella, antes de la ventana. */
    private val LEVEL_COMPLETE_BEAT_MS = 620L

    /**
     * Compás entre que se apaga la explicación de una lección y se abre su ventana de victoria.
     *
     * Sin él las dos cosas se tocan: el velo del TIEMPO BALA todavía se está desvaneciendo (160 ms)
     * cuando entra el velo del panel, y se lee como un parpadeo en vez de como dos momentos.
     */
    private val LEVEL_COMPLETE_AFTER_LESSON_MS = 280L

    /**
     * Vuelo de una estrella al contador. Espejo de `FLIGHT_MS` de `TargetCollectVFX` (+ el burst de
     * salida): si allí cambia, cambia aquí — el reloj de la victoria tiene que cubrir el vuelo entero.
     */
    private val TARGET_FLIGHT_MS = 560L

    /** null = no hay victoria esperando su reloj. Se cancela con la ronda ([launchRoundJob]). */
    private var levelCompleteConfirmJob: kotlinx.coroutines.Job? = null

    /**
     * Cierra el nivel un compás DESPUÉS de que la última estrella aterrice en el panel de objetivos.
     *
     * La espera no es un número fijo: sale de la propia cola de eventos. Las estrellas se emiten con
     * `delayMs` escalonados (una cascada de 4 líneas reparte casi un segundo de retardos), así que se
     * toma el retardo MÁXIMO en vuelo, se le suma el vuelo al contador y un compás para que el número
     * suba y se lea. Sin estrellas pendientes queda solo el compás.
     */
    private fun scheduleLevelCompleteConfirm(state: GameState, elapsedFxMs: Long = 0L) {
        if (levelCompleteConfirmJob?.isActive == true) return
        val lastStarDelayMs = state.events
            .filterIsInstance<GameEvent.TargetCollected>()
            .maxOfOrNull { it.delayMs.toLong() }
        val wait = ((lastStarDelayMs?.plus(TARGET_FLIGHT_MS) ?: 0L) - elapsedFxMs).coerceAtLeast(0L) + LEVEL_COMPLETE_BEAT_MS
        levelCompleteConfirmJob = launchRoundJob {
            kotlinx.coroutines.delay(wait)
            // TIEMPO BALA: las lecciones cuyo remate NO es una rotura de línea (la fusión de la 3ª,
            // el Mega de la 4ª, el turno gastado de la 6ª) lo cobran aquí, con el objetivo ya
            // cumplido y ANTES de que se abra la ventana de victoria — que si no, taparía la
            // explicación con su propia celebración.
            tutorialPayoffOn(com.cukiti.teikafusion.model.TutorialCampaign.Payoff.COMPLETION)
            // …y si el remate de la lección era una ROTURA DE LÍNEA, su shot sigue corriendo desde
            // la cadena: la ventana espera a que termine y respira un compás antes de abrirse. Ver
            // [awaitSlowMotionIdle].
            awaitSlowMotionIdle()
            kotlinx.coroutines.delay(LEVEL_COMPLETE_AFTER_LESSON_MS)
            confirmLevelComplete()
        }
    }

    // (RETIRADO 2026-09-23) `awardLevelTurnBonus`: convertía los turnos sobrantes en puntos al
    // cerrar el nivel. Sin turnos no sobra ninguno.

    fun confirmLevelComplete() {
        var opened = false
        _gameState.update { state ->
            if (state.status != com.cukiti.teikafusion.model.GameStatus.LEVEL_COMPLETE_PENDING) return@update state
            opened = true
            // El snd_mega ya sonó al formarse el MEGA (limpieza del tablero); aquí no se repite.
            state.copy(status = com.cukiti.teikafusion.model.GameStatus.LEVEL_COMPLETE)
        }
        // P-54: la ventana de victoria se queda en pantalla varios segundos y el 90 % de las veces el
        // siguiente botón que se pulsa es SIGUIENTE NIVEL. Es el mejor momento del juego para
        // construir una ronda: el jugador está mirando otra cosa.
        if (opened) {
            val next = _gameState.value.level + 1
            if (com.cukiti.teikafusion.model.LevelLayouts.get(next) != null) {
                prepareRoundInternal(next, allowLocked = true)
            }
        }
    }

    /**
     * Revivir. [spendCoins] = true cobra 500 teikoins (ruta de pago); false = ruta de anuncio (gratis).
     * El AUTO-JUEGO de revivir ([autoReviveSweepBoard]) revienta las filas de madera. Si después el
     * atasco lo causan exclusivamente los cuerpos físicos, los condensa sin recompensas en una pareja
     * igual y separada para que la fusión final siga perteneciendo al jugador.
     */
    fun reviveGame(spendCoins: Boolean = true) {
        if (_isAutoReviving.value) return
        val state0 = _gameState.value
        // Solo se revive desde la oferta. Sin este guard, un anuncio que termina DESPUÉS de que el
        // temporizador ya pasó a GAME_OVER "revivía" un juego muerto (tablero ya vaciado).
        if (state0.status != com.cukiti.teikafusion.model.GameStatus.REVIVE_OFFER) return
        if (spendCoins && state0.teikoins < com.cukiti.teikafusion.model.LevelBudget.REVIVE_COST_TEIKOINS) return
        Analytics.trackReviveUsed()
        _isAutoReviving.value = true
        viewModelScope.launch {
            if (spendCoins) {
                gameMutex.withLock {
                    val newTeikoins = (_gameState.value.teikoins -
                        com.cukiti.teikafusion.model.LevelBudget.REVIVE_COST_TEIKOINS).coerceAtLeast(0)
                    _gameState.update { it.copy(teikoins = newTeikoins) }
                }
                prefs.saveTeikoins(_gameState.value.teikoins)
            }

            autoReviveSweepBoard()
            val recovery = gameMutex.withLock { prepareReviveRecovery(_gameState.value) }
            recovery.rescue?.let { playReviveTeikaRescue(it) }

            // Devolver el control: bandeja fresca + estado PLAYING.
            gameMutex.withLock {
                _gameState.update { s ->
                    checkObjectiveCompletion(s.copy(
                        status = com.cukiti.teikafusion.model.GameStatus.PLAYING,
                        availablePieces = recovery.pieces,
                        // C-3: revivir de una muerte por LAVA tiene que RETIRAR la lava. El barrido
                        // solo limpia madera, y `lavaRow` se persiste: sin esto el jugador pagaba
                        // 500 teikoins (o veía un anuncio entero) para volver a un tablero cubierto
                        // y morir otra vez en el tick siguiente. La presión también se reinicia, o
                        // la primera colocación la haría bajar de nuevo al instante.
                        lavaRow = if (s.defeatCause == com.cukiti.teikafusion.model.DefeatCause.LAVA)
                            0 else s.lavaRow,
                        volcanoDryTurns = if (s.defeatCause == com.cukiti.teikafusion.model.DefeatCause.LAVA)
                            0 else s.volcanoDryTurns
                    ))
                }
            }
            // Revivir con éxito reinicia la contabilidad de la derrota: la próxima muerte de este
            // intento debe poder descontar vida de nuevo (si no, una segunda derrota legítima saldría
            // gratis por culpa de un spendLifeForDefeat ya marcado).
            lifeAlreadySpentForDefeat = false
            _isAutoReviving.value = false
            saveCurrentState(_gameState.value)
            // BGM gobernada por la navegación (status PLAYING → silencio del menú).
        }
    }

    /**
     * Auto-juego de revivir: recorre TODAS las filas que tengan algún bloque de madera, de arriba (0)
     * a abajo. Cada fila se AUTO-COMPLETA (sus huecos se rellenan con madera) y acto seguido REVIENTA
     * entera con su VFX (haz de luz + shatter + shake), en una cascada satisfactoria que despeja el
     * tablero de bloques. Los Teikas del jugador se conservan: ni se rompen ni se rellenan sus celdas.
     */
    private suspend fun autoReviveSweepBoard() {
        val w = _gameState.value.gridW
        val h = _gameState.value.gridH
        // Filas con al menos un bloque de madera, congeladas ANTES de empezar (de arriba a abajo).
        fun playerWood(p: Position): Boolean =
            _gameState.value.grid[p] is CellContent.Wood
        val rowsToClear = (0 until h).filter { y -> (0 until w).any { x -> playerWood(Position(x, y)) } }
        for (y in rowsToClear) {
            val cells = (0 until w).map { Position(it, y) }
            // 1) Auto-completar la fila: rellenar los huecos con madera (sin tocar Teikas).
            gameMutex.withLock {
                _gameState.update { s ->
                    val g = s.grid.toMutableMap()
                    val color = cells.firstNotNullOfOrNull { (g[it] as? CellContent.Wood)?.colorType }
                        ?: (0..4).random(rng)
                    cells.forEach { p ->
                        if ((g[p] ?: CellContent.Empty) is CellContent.Empty)
                            g[p] = CellContent.Wood(colorType = color)
                    }
                    s.copy(grid = g, events = s.events + GameEvent.ScreenShake(3f))
                }
            }
            kotlinx.coroutines.delay(130L)
            // 2) Reventar la fila completa: haz de luz + shatter de toda su madera. Teikas intactos.
            gameMutex.withLock {
                _gameState.update { s ->
                    val g = s.grid.toMutableMap()
                    val ev = s.events.toMutableList()
                    val collected = s.targetsCollected.toMutableMap()
                    ev.addAll(lineClearBeamEvents(listOf(y), emptyList(), g))
                    cells.forEach { p ->
                        val c = g[p]
                        if (c is CellContent.Wood) {
                            ev.add(GameEvent.LineCellShatter(
                                position = p,
                                colorType = c.colorType,
                                delayMs = 0,
                                targetColor = c.targetColor,
                            ))
                            c.targetColor?.let { target ->
                                collected[target] = (collected[target] ?: 0) + 1
                                ev.add(GameEvent.TargetCollected(target, p, delayMs = 0))
                            }
                            g[p] = CellContent.Empty
                        }
                    }
                    ev.add(GameEvent.ScreenShake(7f))
                    s.copy(grid = g, targetsCollected = collected, events = ev)
                }
            }
                    soundManager.playClearAtImpact()
            kotlinx.coroutines.delay(210L)
        }
    }

    private data class PreparedReviveRecovery(
        val pieces: List<Piece>,
        val rescue: PreparedTeikaRescue? = null,
    )

    private data class PreparedTeikaRescue(
        val originalBodies: List<TeikaBody>,
        val placement: com.cukiti.teikafusion.model.ReviveTeikaRescuePlacement,
        val durationMs: Int = 1_350,
    )

    /**
     * Decide sin mutar. Solo activa la coreografía cuando existe una jugada SIN Teikas pero ninguna
     * con los cuerpos actuales: así un revive por movimientos agotados no reorganiza una partida sana.
     */
    private fun prepareReviveRecovery(state: GameState): PreparedReviveRecovery {
        val original = physicsWorld.snapshot()
        val currentBlocked = TeikaPhysicsWorld.occupiedCellsOf(original).keys
        val currentPieces = state.nextPieces(teikaBlockedOverride = currentBlocked)
        if (hasAnyLegalPlacement(
                grid = state.grid,
                availablePieces = currentPieces,
                rulesState = state,
                teikaBlockedOverride = currentBlocked,
            )
        ) return PreparedReviveRecovery(currentPieces)

        val noTeikaPieces = state.nextPieces(teikaBlockedOverride = emptySet())
        val physicalBodiesAreTheBlocker = original.isNotEmpty() && hasAnyLegalPlacement(
            grid = state.grid,
            availablePieces = noTeikaPieces,
            rulesState = state,
            teikaBlockedOverride = emptySet(),
        )
        if (!physicalBodiesAreTheBlocker) return PreparedReviveRecovery(currentPieces)

        val topBound = if (state.lavaActive) state.lavaRow.toFloat() else 0f
        for (type in com.cukiti.teikafusion.model.ReviveTeikaRescuePlanner
            .candidateTypes(original.map { it.type })) {
            val placements = com.cukiti.teikafusion.model.ReviveTeikaRescuePlanner.placements(
                type = type,
                left = 0f,
                top = topBound,
                right = GameState.GRID_SIZE.toFloat(),
                bottom = GameState.GRID_SIZE.toFloat(),
            )
            for (placement in placements) {
                val candidates = listOf(
                    TeikaBody("revive-a", type, placement.ax, placement.ay),
                    TeikaBody("revive-b", type, placement.bx, placement.by),
                )
                val blocked = TeikaPhysicsWorld.occupiedCellsOf(candidates).keys
                val pieces = state.nextPieces(teikaBlockedOverride = blocked)
                if (hasAnyLegalPlacement(
                        grid = state.grid,
                        availablePieces = pieces,
                        rulesState = state,
                        teikaBlockedOverride = blocked,
                    )
                ) {
                    return PreparedReviveRecovery(
                        pieces = pieces,
                        rescue = PreparedTeikaRescue(original, placement),
                    )
                }
            }
        }
        // Defensa extrema: si ni dos T1 dejan una jugada, conservar el mundo evita destruir datos.
        return PreparedReviveRecovery(currentPieces)
    }

    /** Coreografía asistida; no toca score, XP, estadísticas de tier ni progreso hacia el Mega. */
    private suspend fun playReviveTeikaRescue(rescue: PreparedTeikaRescue) {
        val p = rescue.placement
        val event = GameEvent.ReviveTeikaRescue(
            bodies = rescue.originalBodies.map {
                GameEvent.ReviveTeikaRescue.BodyVisual(it.type, it.x, it.y)
            },
            finalType = p.type,
            finalAx = p.ax,
            finalAy = p.ay,
            finalBx = p.bx,
            finalBy = p.by,
            durationMs = rescue.durationMs,
        )
        gameMutex.withLock {
            _gameState.update { it.copy(events = it.events + event) }
            physicsWorld.clear()
            _teikaBodies.value = emptyList()
        }
        kotlinx.coroutines.delay((rescue.durationMs * 0.56f).toLong())
        soundManager.playMerge(p.type.level)
        kotlinx.coroutines.delay((rescue.durationMs * 0.44f).toLong())
        gameMutex.withLock {
            physicsWorld.addBody(p.type, p.ax, p.ay)
            physicsWorld.addBody(p.type, p.bx, p.by)
            _teikaBodies.value = physicsWorld.snapshot()
        }
    }


    fun declineRevive() {
        val s = _gameState.value
        Analytics.trackGameOver(s.score, s.level, s.teikasFormed)
        // La derrota DEFINITIVA (rechazó revivir) es la que cuenta para la tasa de superación: si
        // se contara al ofrecer revivir, cada partida revivida se anotaría como fallo.
        Analytics.trackLevelFail(
            level = s.level,
            biome = com.cukiti.teikafusion.model.LevelMap.biomeFor(s.level).name,
            // El motivo era fijo («tablero_atascado») aunque se perdiera por turnos o por lava:
            // la tasa de superación no distinguía las tres derrotas del juego (C-3/C-4).
            reason = s.defeatCause.analyticsReason,
            attempt = lastLevelAttempt,
            // Lo que mide el progreso del intento son las ESTRELLAS que llegó a recoger, no los
            // turnos que le quedaban: dos derrotas con el mismo `movesLeft` pueden estar a mundos de
            // distancia del objetivo. (Este comentario decía «no hay límite de movimientos en este
            // juego» y dejó de ser cierto el 2026-07-31c, cuando entró el presupuesto de turnos y
            // `DefeatCause.SIN_TURNOS`. El dato reportado era y sigue siendo el correcto; la razón
            // escrita era la que había caducado.)
            targetsCollected = s.targetsCollected.values.sum()
        )
        // Deducir 1 vida por perder. spendLifeForDefeat es idempotente por derrota: si ya se
        // descontó al minimizar durante REVIVE_OFFER, aquí no vuelve a descontar.
        // The defeat cue owns this transition; do not layer the lost-heart cue over it.
        spendLifeForDefeat(playSound = false)
        triggerGameOverWipe()
    }


    /**
     * Secuencia de derrota: explota todos los bloques restantes del tablero con la
     * animación dominó. Tras ~1.1s transiciona a [targetStatus].
     * Por defecto va a GAME_OVER; la rendición voluntaria pasa REVIVE_OFFER para
     * que el jugador pueda aún comprar una segunda oportunidad.
     */
    fun triggerGameOverWipe(
        targetStatus: com.cukiti.teikafusion.model.GameStatus = com.cukiti.teikafusion.model.GameStatus.GAME_OVER
    ) {
        viewModelScope.launch {
            gameMutex.withLock {
                val state = _gameState.value
                if (state.status == com.cukiti.teikafusion.model.GameStatus.GAME_OVER) return@withLock

                val woodCells  = state.grid.entries.filter { it.value is CellContent.Wood }
                val teikaCells = state.grid.entries.filter { it.value is CellContent.Teika }
                val occupiedCount = woodCells.size + teikaCells.size

                val newEvents = state.events.toMutableList()
                // Madera: estalla en fragmentos (dominó escalonado por distancia).
                woodCells.forEach { (pos, cell) ->
                    val w = cell as CellContent.Wood
                    val delay = ((pos.x + pos.y) * 22).coerceAtMost(900)
                    newEvents.add(GameEvent.LineCellShatter(position = pos, colorType = w.colorType, delayMs = delay))
                }
                // Teikas: EXPLOTAN en su sitio (ya no caen por gravedad) — un estallido de partículas por cada
                // celda que ocupan. Es la animación de explosión previa, no la de caída.
                teikaCells.forEach { (pos, _) ->
                    newEvents.add(GameEvent.Particles(position = pos, colorType = -1))
                }
                newEvents.add(GameEvent.ScreenShake(8f))
                newEvents.add(GameEvent.BoardWipe(occupiedCount))

                val emptiedGrid = state.grid.mapValues { CellContent.Empty }
                _gameState.update { it.copy(grid = emptiedGrid, events = newEvents) }
                soundManager.playGameOver()
            }

            kotlinx.coroutines.delay(1100L)
            gameMutex.withLock {
                _gameState.update { it.copy(status = targetStatus) }
            }
            if (targetStatus == com.cukiti.teikafusion.model.GameStatus.GAME_OVER) {
                prefs.saveGameState(null)
                _hasSavedGame.value = false
            }
            // P-54 · LA TERCERA PUERTA. De las tres ventanas que llevan a `startGame` —victoria,
            // pausa y derrota— esta es la que más se cruza en los niveles duros: se pierde y se
            // reintenta el MISMO nivel. Mismo trato que las otras dos: la ronda se construye
            // mientras el jugador lee la ventana.
            prepareRound(_gameState.value.level)
        }
    }

    private fun checkGameOver(
        grid: Map<Position, CellContent>,
        availablePieces: List<Piece>,
        rulesState: GameState = _gameState.value,
        lavaRow: Int = rulesState.lavaRow,
        blockedCells: Set<Position> = rulesState.unplaceableCells,
        teikaBlockedOverride: Set<Position>? = null,
    ): Boolean {
        // Sin fichas no hay nada que probar, así que no se puede juzgar: un tablero sin bandeja no
        // es una derrota, es un estado que no debería existir. En el TUTORIAL sí existe y es
        // deliberado —la lección de la inclinación espera con la bandeja vacía a que muevas el
        // móvil—; fuera de él lo repara `ensureTrayNotEmpty()` al cerrar cada turno (C-8). Sin esa
        // red, una bandeja vacía en un nivel normal congelaba la partida en silencio: nada que
        // arrastrar, así que tampoco se podía disparar el aviso de atasco.
        if (availablePieces.isEmpty()) return false
        if(WreckingBallRules.appliesTo(rulesState.level) && rulesState.ballCharged &&
            WreckingBallRules.hasShot(rulesState.copy(grid=grid),teikaBlockedOverride ?: teikaBlockedCells())) return false
        if(ForgeRules.appliesTo(rulesState.level) && rulesState.forgeCharged &&
            ForgeRules.hasMove(rulesState.copy(grid=grid),physicsWorld.snapshot().map(::clawSave))) return false
        if(ReactorRules.appliesTo(rulesState.level) && rulesState.reactorCharged &&
            ReactorRules.hasGroup(rulesState.copy(grid=grid),teikaBlockedOverride ?: teikaBlockedCells())) return false
        if(TurbineRules.appliesTo(rulesState.level) && rulesState.turbineCharged && TurbineRules.hasMove(rulesState.copy(grid=grid),physicsWorld.snapshot().filter { !it.kinematic }.map(::clawSave))) return false
        if(OrbitRules.appliesTo(rulesState.level) && rulesState.orbitCharged && OrbitRules.hasMove(rulesState.copy(grid=grid),orbitBodyCells())) return false
        if(PortalSwapRules.appliesTo(rulesState.level) && rulesState.portalSwapCharged &&
            PortalSwapRules.hasMove(rulesState.copy(grid=grid),teikaBlockedOverride ?: teikaBlockedCells())) return false
        if(CompactorRules.appliesTo(rulesState.level) && rulesState.compactorCharged &&
            CompactorRules.hasMove(rulesState.copy(grid=grid),teikaBlockedOverride ?: teikaBlockedCells())) return false

        // ── TORMENTA: un circuito sin descargar es una SALIDA, pero solo si se puede tocar ───────
        // Tocar las bobinas en orden libera la fila, así que mientras quede circuito no hay derrota.
        // El indulto era incondicional (`any { coil > 0 }`) y eso no coincide con lo que de verdad
        // permite resolverlo: tanto `onBoardTap` como la capa táctil del tablero (`boardTapActive`)
        // exigen que STORM sea el bioma PRIMARIO. Una bobina en un tablero sin Tormenta es adorno —
        // y el indulto se volvía perpetuo: el tablero no podía declararse muerto ni ofrecer revivir,
        // la ficha rebotaba y no pasaba nada nunca más (C-7).
        if (rulesState.biomePrimary == com.cukiti.teikafusion.model.BiomeType.STORM &&
            grid.values.any { it is CellContent.Wood && it.coil > 0 }
        ) return false

        return !hasAnyLegalPlacement(
            grid = grid,
            availablePieces = availablePieces,
            rulesState = rulesState,
            lavaRow = lavaRow,
            blockedCells = blockedCells,
            teikaBlockedOverride = teikaBlockedOverride,
            includeReserve = true,
        )
    }

    /** Prueba geométrica estricta, sin excepciones temporales de hielo/bobinas. */
    private fun hasAnyLegalPlacement(
        grid: Map<Position, CellContent>,
        availablePieces: List<Piece>,
        rulesState: GameState,
        lavaRow: Int = rulesState.lavaRow,
        blockedCells: Set<Position> = rulesState.unplaceableCells,
        teikaBlockedOverride: Set<Position>? = null,
        includeReserve: Boolean = false,
    ): Boolean {
        if (availablePieces.isEmpty()) return false
        // Cada ficha se prueba en sus CUATRO rotaciones (P-276, 2026-09-24): el jugador puede girarla
        // con un toque, así que una ficha que solo cabe girada ES una salida. Mirar solo la
        // orientación repartida declararía perdida una partida que no lo está. El HOLD no existe,
        // así que no hay "escape" por intercambio. Los cuerpos físicos también bloquean celdas.
        val allBlocked = blockedCells + (teikaBlockedOverride ?: teikaBlockedCells())
        // Corte Ninja: con el tablero partido, una posición a caballo NO es salida válida.
        val splitAtX = if (rulesState.ninjaCutActive) NINJA_CUT_COL else -1
        // LA COLA FORZADA: solo cuenta como salida lo que la cola deja jugar ahora (ver
        // [com.cukiti.teikafusion.model.ForcedQueue.playable] — sin esto, sin jugada y sin derrota).
        for (dealt in com.cukiti.teikafusion.model.ForcedQueue.playable(rulesState.level, if(includeReserve) ReserveRules.candidates(rulesState,availablePieces) else availablePieces)) {
            // La ficha que la Maite tiene dormida NO es una salida: no se puede jugar (ni girar).
            // Contarla dejaría al jugador atascado sin que el juego lo declarase.
            if (rulesState.isPieceAsleep(dealt.id)) continue
            // En el tutorial no se gira (ver [rotatePieceInTray]): ahí solo cuenta la forma repartida.
            val variants = if (com.cukiti.teikafusion.model.TutorialCampaign.isTutorialLevel(rulesState.level))
                listOf(dealt) else allRotations(dealt)
            for (piece in variants) {
                // FICHA FANTASMA: puede posarse sobre madera del jugador, así que un tablero que para
                // el resto de fichas es un atasco para ella NO lo es. Sin esto el juego declaraba game
                // over con la ficha desatascadora en la mano — justo lo contrario de su razón de ser.
                val ghostable = ghostOverlappableCells(rulesState, piece)
                for (y in 0 until rulesState.gridH) {
                    for (x in 0 until rulesState.gridW) {
                        if (canPlacePieceInternal(
                                grid, piece, x, y, lavaRow = lavaRow, blockedCells = allBlocked,
                                overlappableCells = ghostable, splitAtX = splitAtX,
                                gridH = rulesState.gridH,
                            ) && ghostOverlapAllowed(rulesState, piece, x, y)
                        ) return true
                    }
                }
            }
        }
        return false
    }

    /**
     * Borrón y cuenta nueva de TODO el estado transitorio de una ronda (no vive en GameState):
     * mundo físico vacío, astro del Cielo Estelar en vuelo cancelado (no debe descargar sobre la
     * partida nueva) y los acumuladores `xxxSinceTick` de bioma a cero — sin esto, la
     * presión/actividad de la partida ANTERIOR se filtra al primer turno de la nueva.
     * Lo llaman [startGame] y [nextLevel]: los DOS caminos que estrenan tablero.
     */
    private fun resetRoundTransients() {
        rulePhysicsHoldUntilMs = 0L
        clawBusy = false
        resetMagmaHeat(); magmaHeatRow = -1; magmaForging = false
        // Invalida audio diferido de la ronda anterior (capas, colas graves y clears con impacto).
        soundManager.beginAudioContext()
        // P-187: la huella de la última colocación es de ESA ronda. Arrastrarla protegería de la
        // presión unas celdas del tablero nuevo hasta la primera colocación.
        justPlacedCells = emptySet()
        // Y la huella de los CUERPOS, por el mismo motivo y con un estropicio mayor si se olvida:
        // reintentar el mismo nivel deja el tablero nuevo lleno de madera y el mundo físico vacío,
        // así que la comparación vería «se han liberado todas las celdas» y desplomaría un tablero
        // recién repartido. El cambio de nivel ya lo cubre `floorLevel`; esto cubre el REINTENTO,
        // que es el caso que no cambia de número. Ver [settleGravityIfTeikaFloorMoved].
        resetTeikaFloorWatch()
        // Cancelar también el ciclo común evita que una habilidad cancelada por cambio de nivel
        // siga viva sobre el tablero nuevo.
        companionAbilityInFlight = false
        companionEffectJob = null
        tutorialReleaseFallbackJob = null
        tutorialTiltObserved = false
        _tutorialStage.value = 0
        _tutorialTiltDirection.value = 0
        _tutorialStageReady.value = false
        tutorialShotsPlayed.clear()
        clearSlowMotion()
        cinematicJob?.cancel(); cinematicJob = null
        _companionCinematic.value = null
        cancelForgeAim()
        cancelReactorAim()
        cancelClawAim()
        cancelBallAim()
        cancelPortalSwapAim()
        cancelTurbineAim()
        cancelOrbitAim()
        cancelCompactorAim()
        cancelPinballAim()
        physicsWorld.clear()
        _teikaBodies.value = emptyList()
        astroStrikeJob?.cancel(); astroStrikeJob = null
        // Habilidades en curso: nada debe filtrarse al siguiente nivel/partida.
        slidePuzzleJob?.cancel(); slidePuzzleJob = null
        floraCeremonyJob?.cancel(); floraCeremonyJob = null
        // Redes de seguridad temporizadas del revelado (Maite, Rayco, huida, galáctico, muro del
        // Rey) + re-disparos de cadena: si sobreviven al cambio de nivel, resuelven el tablero
        // NUEVO con datos del viejo. Se cancelan sobre una COPIA (invokeOnCompletion las quita
        // del set mientras se cancelan).
        roundJobs.toList().forEach { it.cancel() }
        roundJobs.clear()
        _floraAim.value = null
        floraProjectileId = null
        physicsWorld.setHorizontalGravity(0f)
        physicsWorld.setRampage(false)
        activityWeightSinceTick = 0
        lineClearsThisRound = 0
        pureLineSinceCapsule = false
        pendingCapsules.clear()
        gardenLinesClearedSinceTick = 0
        volcanoClearsSinceTick = 0
        galacticClearsSinceTick = 0
        galacticIdleCounter = 0
        stormEnergizedSinceTick = false
        coilFailCountingActive = false
        gluttonFedSinceTick = false
        gluttonFeastSinceTick = false
        poisonWashedThisPlacement.clear()
        lastPlacedCellsForBiomeTick = emptySet()
        clearedRowsSinceTick.clear(); clearedColsSinceTick.clear(); clearedCellsSinceTick.clear()
        lastPlacedPieceIdForBiomeTick = null
        // Ronda nueva: los mandos se devuelven pase lo que pase. Cualquier turno que siguiera vivo
        // queda cortado por `viewModelScope`, y su `finally` ya no puede hacer daño (ver
        // [BoardBusyCounter.exit]).
        turbineBusy=false; turbineFusionCount=0; turbineAimBusy=false; _turbineAim.value=null
        forgeAimBusy=false; _forgeAim.value=null; pinballAimBusy=false; pinballFlightBusy=false; compactorAimBusy=false; _compactorAiming.value=false; orbitAimBusy=false; _orbitAim.value=null; portalSwapAimBusy=false; _portalSwapAim.value=null; reactorAimBusy=false; _reactorAim.value=null; ballAimBusy=false; _ballAim.value=null; clawAimBusy=false; _clawAim.value=null
        boardBusyCounter.forceRelease()
        boardBusyWatchdog?.cancel(); boardBusyWatchdog = null
        _boardBusy.value = false
        // Aviso "faltan estrellas": una vez por nivel — se rearma con cada nueva ronda/nivel.
        objectiveNudgeLevel = -1
    }

    // ── RONDA PRECALCULADA (2026-08-24, perf del botón JUGAR NIVEL) ─────────────────────────────
    //
    // Construir la ronda no es gratis: figura del nivel, siembra de bioma, presupuesto de turnos y
    // el planificador de bandeja. Hasta hoy todo eso corría DENTRO del `onClick`, y la medición en
    // dispositivo lo confirmó — `HandleInputStart → PerformTraversalsStart` = **236 ms** en el
    // fotograma del toque (`Davey! duration=1085ms`). Doscientos milisegundos con el dedo levantado
    // y la pantalla congelada es justo lo que se siente como «el botón no responde».
    //
    // El panel de JUGAR NIVEL está abierto varios segundos antes de que nadie pulse: ese hueco es
    // gratis. [prepareRound] construye ahí el estado en un hilo de fondo y [startGame] lo recoge ya
    // hecho. Si no está listo (o el nivel/compañero cambiaron), se construye en el sitio como antes:
    // la ronda precalculada es una CACHÉ, nunca un requisito.
    private class PreparedRound(
        val level: Int,
        val companionId: String?,
        val companionLevel: Int,
        val state: GameState,
    )

    @Volatile
    private var preparedRound: PreparedRound? = null
    private var prepareRoundJob: kotlinx.coroutines.Job? = null

    /**
     * La ronda ya construida para [level], **si sigue valiendo**: mismo nivel, mismo compañero, mismo
     * nivel de compañero. La consumen `startGame` y `nextLevel`, y por eso vive aquí y
     * no dentro de una de las dos: si cada una comparase por su cuenta, la que se dejara un campo
     * arrancaría con la ronda de otra configuración —el compañero equivocado— y eso no se ve hasta
     * media partida después.
     */
    private fun takePreparedRound(level: Int): GameState? {
        val companionId = selectedCompanionId.value
        val companionLevel = companionLevelForRound(companionId)
        val match = preparedRound?.takeIf {
            it.level == level && it.companionId == companionId &&
                it.companionLevel == companionLevel
        }
        preparedRound = null
        prepareRoundJob?.cancel()
        return match?.state
    }

    /** Nivel de compañero que se usará al arrancar: parte de la identidad de la ronda. */
    private fun companionLevelForRound(companionId: String?): Int =
        companionId?.let { _companionUpgrades.value.levelOf(it) } ?: 1

    /**
     * Adelanta la construcción de la ronda de [level] en un hilo de fondo. Idempotente y cancelable:
     * llamarla otra vez con el mismo nivel y compañero no hace nada, y cambiar de compañero descarta
     * el trabajo en vuelo. La llama el panel de JUGAR NIVEL mientras el jugador lo mira.
     */
    fun prepareRound(level: Int) =
        prepareRoundInternal(level, allowLocked = false)

    /**
     * Re-adelanta la ronda del siguiente nivel desde la ventana de victoria.
     *
     * Existe porque el nivel siguiente está **cerrado** todavía cuando la ventana de victoria está
     * abierta —lo desbloquea `nextLevel` unas décimas después—, así que la puerta normal
     * ([prepareRound]) lo rechazaría por el guarda de nivel bloqueado. Es la misma excepción que ya
     * abrió P-54 y por el mismo motivo.
     */
    fun prepareNextLevelRound() {
        val next = _gameState.value.level + 1
        if (com.cukiti.teikafusion.model.LevelLayouts.get(next) == null) return
        prepareRoundInternal(next, allowLocked = true)
    }

    /**
     * [allowLocked] solo lo usa la victoria (P-54, 2026-09-04): al abrirse la ventana de nivel
     * completado se adelanta la ronda del SIGUIENTE, que en ese instante todavía puede estar cerrado
     * —lo desbloquea `nextLevel` unas décimas después—. Fuera de ese caso el guarda se respeta: no
     * hay motivo para construir un nivel al que el jugador no puede entrar.
     */
    private fun prepareRoundInternal(level: Int, allowLocked: Boolean) {
        if (!allowLocked && level > _gameState.value.maxUnlockedLevel) return
        if (com.cukiti.teikafusion.model.TutorialCampaign.isTutorialLevel(level)) return
        val companionId = selectedCompanionId.value
        val companionLevel = companionLevelForRound(companionId)
        preparedRound?.let {
            if (it.level == level && it.companionId == companionId &&
                it.companionLevel == companionLevel
            ) return
        }
        prepareRoundJob?.cancel()
        prepareRoundJob = viewModelScope.launch(kotlinx.coroutines.Dispatchers.Default) {
            // Puntuación, monedas y récords son PASO DIRECTO en `GameState.initial` (solo rellenan
            // campos), así que aquí van en blanco y `startGame` los pone al valor real al publicar.
            val built = GameState.initial(
                level = level,
                score = 0,
                teikoins = 0,
                highScore = 0,
                maxTeikas = 0,
                companionId = companionId,
                companionLevel = companionLevel,
            )
            if (kotlinx.coroutines.currentCoroutineContext().isActive) {
                preparedRound = PreparedRound(level, companionId, companionLevel, built)
            }
        }
    }

    /**
     * Arranca una ronda NUEVA de [level].
     *
     * Toda entrada presenta el objetivo: las estrellas y el MEGA vuelan al panel del HUD antes del
     * primer turno. El parámetro `presentObjectives` que apagaba esa ceremonia se retiró el
     * 2026-08-24 (decisión del usuario): su único usuario era el botón JUGAR NIVEL de Inicio —o
     * sea, **el camino más habitual para empezar un nivel era el único sin ceremonia**—. Reanudar
     * una partida guardada sigue sin presentarla: `continueGame` no toca [roundStartToken].
     */
    fun startGame(level: Int = 1) {
        // Guard: block access to locked regular levels regardless of how the call was made
        if (level > _gameState.value.maxUnlockedLevel) return

        // Sin vidas: en vez de un return silencioso (botón muerto, "no me deja jugar"), recordar
        // el nivel y avisar a la UI para que muestre el overlay "Sin vidas" (regen + comprar).
        //
        // **Las vidas infinitas mandan sobre el contador** (P-134, 2026-09-03). Hoy la comprobación
        // es redundante —`grantInfiniteLives` rellena el contador a `LIVES_MAX` al conceder, así que
        // mientras están activas nunca baja de ahí— y precisamente por eso se añade: la corrección
        // vivía en OTRA función, no aquí. `spendLife` ya preguntaba por las infinitas antes de
        // cobrar; este guarda no, y era el único camino capaz de decirle «no puedes jugar» a alguien
        // que acaba de pagar por jugar sin límite. Cualquier vía futura que conceda infinitas sin
        // tocar el contador —restaurarlas de la nube, un código promocional, un pack de regalo—
        // habría caído justo aquí.
        if (!com.cukiti.teikafusion.model.TutorialCampaign.isTutorialLevel(level) &&
            _lives.value <= 0 && !isInfiniteLivesActive()
        ) {
            pendingLevelForLives = level
            _outOfLivesPrompt.value = true
            soundManager.playNoLives()   // overlay "Sin vidas"
            return
        }
        // Entramos a una partida nueva → cualquier prompt de vidas pendiente ya no aplica y la
        // próxima derrota vuelve a poder descontar vida.
        _outOfLivesPrompt.value = false
        pendingLevelForLives = null
        // ── C-6 · ABANDONAR UN INTENTO CUESTA LO MISMO QUE PERDERLO (2026-09-02) ────────────────
        // Las vidas se cobraban SOLO al perder, y nunca al empezar. Así que un tablero irremediable
        // —o simplemente uno que iba mal— se salía gratis: pausa → Reiniciar, o pausa → Inicio y
        // otro nivel desde el mapa. La derrota no costaba nada mientras el jugador se adelantara a
        // ella, y eso vaciaba de sentido tanto la vida como la oferta de revivir.
        //
        // `_hasSavedGame` es exactamente «hay un intento sin terminar»: se pone al guardar en
        // PLAYING/PAUSED (o sea, desde la primera colocación) y se limpia al ganar, al perder de
        // verdad y aquí. Arrancar un nivel DESTRUYE ese intento —la ranura de guardado es única— y
        // ese es el momento en que se cobra. El tutorial no cobra: ahí se aprende.
        //
        // No usa `spendLifeForDefeat`: aquel es idempotente POR DERROTA y su bandera se reinicia
        // justo debajo; abandonar y perder son dos cosas distintas y cada una paga la suya.
        // «El tutorial no cobra» valía solo para la mitad de los casos (bug de playtest,
        // 2026-09-03): se miraba el nivel GUARDADO y no el que se va a empezar. Con una partida a
        // medias en el nivel 50, entrar a una lección daba `savedGameLevel = 50` —que no es tutorial—
        // y **el jugador pagaba una vida por ir a repasar cómo se juega**. Las lecciones son
        // gratis por las dos puntas: ni cobran por lo que abandonas ni por entrar en ellas.
        val entrandoALeccion = com.cukiti.teikafusion.model.TutorialCampaign.isTutorialLevel(level)
        val abandoningAttempt = _hasSavedGame.value && !entrandoALeccion &&
            !com.cukiti.teikafusion.model.TutorialCampaign.isTutorialLevel(
                _savedGameLevel.value.takeIf { it > 0 } ?: level
            )
        if (abandoningAttempt) spendLife()
        lifeAlreadySpentForDefeat = false
        // Clear any existing save — player is explicitly starting a new game
        viewModelScope.launch { prefs.saveGameState(null) }
        _hasSavedGame.value = false
        Analytics.trackGameStart(level)
        // Funnel de nivel + contexto de crash. Sin `level_start` no hay denominador para la tasa de
        // superación, y sin estas claves un crash de partida no dice ni en qué bioma ocurrió.
        val startBiome = com.cukiti.teikafusion.model.LevelMap.biomeFor(level).name
        // Intentos SEGUIDOS sobre el mismo nivel: un nivel que se reintenta 6 veces de media es
        // un muro de dificultad, y eso no se ve en `level_complete`.
        val attempt = if (level == lastStartedLevel) lastLevelAttempt + 1 else 1
        lastStartedLevel = level
        lastLevelAttempt = attempt
        Analytics.trackLevelStart(level, startBiome, attempt)
        Analytics.crashKeys("level" to level, "biome" to startBiome)
        resetRoundTransients()
        soundManager.playLaunch()   // botón JUGAR: lanzamiento de nivel/partida
        val prevMaxUnlocked = _gameState.value.maxUnlockedLevel
        val companionId = selectedCompanionId.value
        val companionLevel = companionLevelForRound(companionId)
        // Ronda ya construida por [prepareRound] mientras el panel estaba abierto, si sigue valiendo.
        val built = takePreparedRound(level) ?: GameState.initial(
            level = level,
            score = 0,
            teikoins = 0,
            highScore = 0,
            maxTeikas = 0,
            companionId = companionId,
            companionLevel = companionLevel,
        )
        _gameState.value = built.copy(
            status = com.cukiti.teikafusion.model.GameStatus.PLAYING,
            maxUnlockedLevel = prevMaxUnlocked,
            // Se ponen AQUÍ y no en `initial`: la ronda pudo construirse hace segundos, y monedas,
            // récord y colección son del jugador, no del nivel.
            teikoins = _gameState.value.teikoins,
            highScore = _gameState.value.highScore,
            maxTeikas = _gameState.value.maxTeikas
        )
        prepareTutorialPhysics(level)
        armPersonalScoreRecordTracking(_gameState.value.highScore)
        scheduleRoundStartCapsule()
        // Ronda nueva ⇒ token nuevo: la UI presenta el objetivo una sola vez, incluso al reintentar
        // el MISMO número de nivel. «Siguiente nivel» gestiona su propio token en [nextLevel].
        _roundStartToken.value = ++roundStartSequence
        // BGM gobernada por la navegación (status PLAYING → silencio del menú).
    }

    /** Pasa al nivel siguiente desde la ventana de victoria. */
    fun nextLevel() {
        dismissDoubleCoins()   // P-20: la oferta de duplicar es de ESA victoria y de ninguna otra
        // Clear the completed level's save — new level starts fresh
        viewModelScope.launch { prefs.saveGameState(null) }
        _hasSavedGame.value = false
        lifeAlreadySpentForDefeat = false
        val completedLevel = _gameState.value.level
        if (com.cukiti.teikafusion.model.LevelLayouts.get(completedLevel + 1) == null) {
            goHome()
            return
        }
        val nextLvl = completedLevel + 1
        val newMaxUnlocked = maxOf(_gameState.value.maxUnlockedLevel, nextLvl)
        viewModelScope.launch { prefs.saveMaxLevel(newMaxUnlocked) }
        // Mismo borrón y cuenta nueva que startGame: antes SOLO limpiaba la física, y los
        // acumuladores de bioma (y el astro en vuelo del Cielo Estelar) se FILTRABAN del nivel
        // recién completado al primer turno del siguiente.
        resetRoundTransients()

        // P-54 (2026-09-04): la ronda del siguiente nivel se adelantó al abrirse la ventana de
        // victoria, mientras el jugador la miraba. Aquí solo se recoge. Si no vale —cambió de
        // compañero desde la ventana, o la construcción no llegó a tiempo— se construye ahora, que es
        // exactamente lo que se hacía siempre.
        val builtNext = takePreparedRound(nextLvl)
            ?: GameState.initial(
                level = nextLvl,
                score = 0,
                teikoins = 0,
                highScore = 0,
                maxTeikas = 0,
                companionId = selectedCompanionId.value,
                companionLevel = companionLevelForRound(selectedCompanionId.value),
            )
        _gameState.value = builtNext.copy(
            status = com.cukiti.teikafusion.model.GameStatus.PLAYING,
            maxUnlockedLevel = newMaxUnlocked,
            // Monedas, récord y colección son del JUGADOR, no del nivel: se ponen al publicar, igual
            // que en `startGame`. Una ronda adelantada se construyó con ellos en blanco.
            teikoins = _gameState.value.teikoins,
            highScore = _gameState.value.highScore,
            maxTeikas = _gameState.value.maxTeikas
        )
        prepareTutorialPhysics(nextLvl)
        armPersonalScoreRecordTracking(_gameState.value.highScore)
        scheduleRoundStartCapsule()
        _roundStartToken.value = ++roundStartSequence
        // BGM gobernada por la navegación (status PLAYING → silencio del menú).
    }

    /**
     * Nivel para el que YA se avisó "faltan estrellas". Antes cada MEGA sin completar disparaba un
     * overlay a pantalla completa — molesto y repetitivo. Ahora el aviso es un PULSO en sitio (panel
     * de objetivo rojo + vibración) y suena **una sola vez por nivel**: esta guarda lo garantiza.
     */
    private var objectiveNudgeLevel: Int = -1

    /**
     * El espectáculo del MEGA terminó pero el nivel NO se completó (faltan estrellas). En vez de un
     * overlay intrusivo, tiñe de ROJO el panel de objetivo y lo hace VIBRAR (pulso incrementado que
     * la UI observa). Lo dispara GameScreen al consumirse el evento del Mega con la partida aún en
     * PLAYING. Guardas: solo NIVELES con objetivo aún incompleto, y **una sola vez por nivel**.
     */
    fun nudgeObjectives() {
        val s = _gameState.value
        val objective = s.levelObjective
        if (s.status != com.cukiti.teikafusion.model.GameStatus.PLAYING || objective == null) return
        val allMet = objective.required.all { (color, needed) ->
            (s.targetsCollected[color] ?: 0) >= needed
        }
        if (allMet) return
        if (objectiveNudgeLevel == s.level) return   // ya se avisó en este nivel
        objectiveNudgeLevel = s.level
        _gameState.update { it.copy(objectiveNudgePulse = it.objectiveNudgePulse + 1) }
    }

    fun goHome() {
        dismissDoubleCoins()
        // SALIR DEL TABLERO TERMINA LA RONDA (fix 2026-08-01). Sin esto, cualquier corrutina de
        // ronda todavía en vuelo —cacería fantasma, descarga eléctrica, colapso galáctico, empuje
        // de muros, ceremonia de fusión— publicaba al terminar el estado que capturó, con
        // `status = PLAYING`, y devolvía al jugador al nivel: el síntoma reportado de «le doy a
        // salir y no se sale» en según qué biomas. Va lo PRIMERO: si el status cambia antes de
        // cancelar, aún queda una ventana por la que colarse.
        resetRoundTransients()
        // La BGM la maneja la navegación: al pasar a HOME suena la pista de menú (LOFI) sin reiniciar.
        val status = _gameState.value.status
        // Coming from a terminal state — stale save is no longer resumable
        if (status == com.cukiti.teikafusion.model.GameStatus.GAME_OVER ||
            status == com.cukiti.teikafusion.model.GameStatus.LEVEL_COMPLETE ||
            // PENDING es victoria YA decidida esperando su animación: salir a Home ahí dejaba un
            // save reanudable de un nivel que el jugador acababa de ganar.
            status == com.cukiti.teikafusion.model.GameStatus.LEVEL_COMPLETE_PENDING) {
            viewModelScope.launch { prefs.saveGameState(null) }
            _hasSavedGame.value = false
        }
        _gameState.value = _gameState.value.copy(status = com.cukiti.teikafusion.model.GameStatus.HOME)
    }

    fun openStore() {
        _gameState.update { it.copy(status = com.cukiti.teikafusion.model.GameStatus.STORE) }
    }

    // (openSkillTree() se eliminó con el rediseño 2026-07-27: la pestaña «H. Teika» ya no existe,
    //  sus tarjetas de habilidad viven dentro del Inventario → openStore().)

    fun openShop() {
        _gameState.update { it.copy(status = com.cukiti.teikafusion.model.GameStatus.SHOP) }
    }

    fun selectAvatar(type: com.cukiti.teikafusion.model.TeikaType) {
        _avatarType.value = type
        viewModelScope.launch { prefs.saveAvatar(type) }
    }

    // (V-02 podado 2026-07-29) buyTeikaAbility / equipTeikaAbility retirados: no había variantes
    // reales (ambas defs eran isBase) y ninguna UI los llamaba.

    /**
     * Mejora (sube nivel) la habilidad base del compañero desde la screen H. Teika.
     * Cuesta cristales + teikoins. No hace nada si falta cualquiera de los dos.
     */
    /** Devuelve si la mejora ocurrió de verdad: solo entonces la UI lanza la cinemática. */
    fun upgradeCompanionAbility(companionId: String): Boolean {
        if (companionId !in claimedCharacterIds.value) return false
        // Habilidad desactivada (colección sin habilidad, decisión 2026-07-11): no se puede mejorar
        // — sería gastar cristales/teikoins en una habilidad que nunca dispara. La screen ya los
        // filtra; esta guarda cubre cualquier otro camino.
        if (!com.cukiti.teikafusion.model.companionAbilityEnabled(companionId)) return false
        val cur = _companionUpgrades.value
        if (cur.isMaxed(companionId)) return false
        // Coste afinable en remoto (100 = tabla original). Permite reequilibrar la economía sin
        // publicar versión, que es como se ajusta un juego ya lanzado.
        val cost = cur.costToNext(companionId, _remoteConfig.value.abilityUpgradeCostPercent)
        val crystalCost = cur.crystalCostToNext(companionId)
        val state = _gameState.value
        val inv = _crystalInventory.value
        if (state.teikoins < cost) return false
        if (!inv.canSpend(crystalCost)) return false

        val newTeikoins = state.teikoins - cost
        val newInventory = inv.spend(crystalCost)
        val newUpgrades = cur.withUpgrade(companionId)
        _companionUpgrades.value = newUpgrades
        _crystalInventory.value = newInventory
        _gameState.update { it.copy(teikoins = newTeikoins) }
        soundManager.playUiClick()   // botón de mejorar habilidad teika
        Analytics.trackAbilityUpgrade(companionId, newUpgrades.levelOf(companionId), cost)
        viewModelScope.launch {
            prefs.saveTeikoins(newTeikoins)
            prefs.saveCompanionUpgrades(newUpgrades)
            prefs.saveCrystalInventory(newInventory)
        }
        return true
    }

    /**
     * Reparte el cristal por superar [level] la PRIMERA vez ([com.cukiti.teikafusion.model.CrystalEconomy]):
     * fijo por capítulo, +1 con 3★. Afinable en remoto (100 = tabla), nunca por debajo de 1.
     */
    private fun awardCrystalsForLevel(level: Int, stars: Int) {
        val base = com.cukiti.teikafusion.model.CrystalEconomy.dropFor(level, stars)
        val pct = _remoteConfig.value.crystalDropPercent
        val drop = if (pct == 100) base else applyPercent(base, pct).coerceAtLeast(1)
        grantCrystals(drop)
        _lastCrystalDrop.value = drop
    }

    private fun grantCrystals(amount: Int) {
        if (amount <= 0) return
        val newInventory = _crystalInventory.value.add(amount)
        _crystalInventory.value = newInventory
        viewModelScope.launch { prefs.saveCrystalInventory(newInventory) }
    }

    /** El overlay de fin de nivel consumió el drop de cristales (ya lo animó). */
    fun consumeCrystalDrop() { _lastCrystalDrop.value = 0 }

    // (RETIRADAS 2026-09-24, P-267) `fuseCrystals` / `defuseCrystals`: la fusión 3:1 y la desfusión
    // desaparecen con los tiers. Hay un solo cristal.

    /**
     * Compra el bloque [key] y lo equipa. Devuelve si ocurrió: la vitrina solo celebra entonces.
     * El precio sale del propio bloque, no de quien llama: el motor no cobra lo que le digan.
     */
    fun buyCosmetic(key: String): Boolean {
        val state = _gameState.value
        val skin = com.cukiti.teikafusion.ui.BlockSkins.all.firstOrNull { it.id == key } ?: return false
        val cost = skin.priceTeikoins
        if (key in _unlockedCosmetics.value) return false   // ya comprado: no recobrar
        // P-250: un bloque de bioma solo se vende DESCUBIERTO (terminado su capítulo). La vitrina ya
        // no ofrece el botón, pero la regla vive aquí, donde se cobra.
        if (!com.cukiti.teikafusion.model.BlockDiscovery.isDiscovered(key, state.maxUnlockedLevel)) return false
        if (state.teikoins < cost) return false
        val newTeikoins = state.teikoins - cost
        val newCosmetics = _unlockedCosmetics.value + key
        _gameState.update { it.copy(teikoins = newTeikoins) }
        _unlockedCosmetics.value = newCosmetics
        // Auto-equipar lo recién comprado.
        _activeCosmetic.value = key
        soundManager.playPurchase()
        viewModelScope.launch {
            prefs.saveTeikoins(newTeikoins)
            prefs.saveUnlockedCosmetics(newCosmetics)
            prefs.saveActiveCosmetic(key)
        }
        val skinName = skin.name
        emitReveal(
            title = "¡NUEVO BLOQUE!",
            accentArgb = 0xFF4DB8FF,
            items = listOf(
                com.cukiti.teikafusion.model.RewardItem(
                    kind = com.cukiti.teikafusion.model.RewardKind.BLOCK_SKIN,
                    label = "Bloque $skinName", skinId = key
                )
            )
        )
        return true
    }

    /**
     * **P-249 · Retirada del bloque Caramelo** (regla en [com.cukiti.teikafusion.model.CandyRetirement]).
     * Se pasa al cargar el perfil y tras cada fusión con la nube; es idempotente: la marca impide
     * pagar dos veces y un Caramelo equipado vuelve al Clásico aunque ya se hubiera pagado.
     */
    private fun retireCandy() {
        val o = com.cukiti.teikafusion.model.CandyRetirement.apply(
            _unlockedCosmetics.value, _activeCosmetic.value, _candyRefunded.value
        )
        if (o.active != _activeCosmetic.value) {
            _activeCosmetic.value = o.active
            viewModelScope.launch { prefs.saveActiveCosmetic(o.active) }
        }
        if (o.refunded && !_candyRefunded.value) {
            _candyRefunded.value = true
            viewModelScope.launch { prefs.saveCandyRefunded() }
        }
        if (o.refund > 0) {
            grantTeikoins(o.refund, silent = true)
            emitReveal(
                title = "BLOQUE RETIRADO",
                accentArgb = 0xFFFFD700,
                items = listOf(
                    com.cukiti.teikafusion.model.RewardItem(
                        kind = com.cukiti.teikafusion.model.RewardKind.TEIKOINS,
                        label = "${o.refund} Teikoins devueltos por el Caramelo", amount = o.refund
                    )
                )
            )
        }
    }

    fun equipCosmetic(key: String) {
        soundManager.playUiClick()   // botón EQUIPAR de la tienda (comprar ya suena con playPurchase)
        _activeCosmetic.value = key
        viewModelScope.launch { prefs.saveActiveCosmetic(key) }
    }

    /** OTRA: reengancha el mismo nivel en un toque. */
    fun restartGame() {
        startGame(_gameState.value.level)
    }

    fun pauseGame() {
        cancelForgeAim()
        cancelReactorAim()
        cancelClawAim()
        cancelBallAim()
        cancelPortalSwapAim()
        cancelTurbineAim()
        cancelOrbitAim()
        cancelCompactorAim()
        cancelPinballAim()
        if (_gameState.value.status == com.cukiti.teikafusion.model.GameStatus.PLAYING) {
            _gameState.update { it.copy(status = com.cukiti.teikafusion.model.GameStatus.PAUSED) }
            soundManager.pauseBgm()
            saveCurrentState(_gameState.value)
            // P-54: desde la pausa se sale por REINICIAR más veces que por ninguna otra puerta, y
            // reiniciar es `startGame` del mismo nivel. Mientras el panel está abierto no hay prisa.
            prepareRound(_gameState.value.level)
        }
    }

    /** Llamado desde MainActivity.onPause() para guardar la partida y pausar si estaba en juego. */
    fun autoSaveAndPause() {
        cancelForgeAim()
        cancelReactorAim()
        cancelClawAim()
        cancelBallAim()
        cancelPortalSwapAim()
        cancelTurbineAim()
        cancelOrbitAim()
        cancelCompactorAim()
        cancelPinballAim()
        val current = _gameState.value
        if (isTutorialRound(current)) {
            // Irse a segundo plano en una lección la pausa, pero no la guarda (P-169): al volver se
            // repite entera, que es lo que una lección es.
            if (current.status == com.cukiti.teikafusion.model.GameStatus.PLAYING) {
                _gameState.value = current.copy(status = com.cukiti.teikafusion.model.GameStatus.PAUSED)
                soundManager.pauseBgm()
            }
            return
        }
        when (current.status) {
            com.cukiti.teikafusion.model.GameStatus.PLAYING -> {
                val paused = current.copy(status = com.cukiti.teikafusion.model.GameStatus.PAUSED)
                _gameState.value = paused
                soundManager.pauseBgm()
                // Guarda ambos modos: al volver, el jugador retoma con "Continuar".
                _hasSavedGame.value = true
                _savedGameLevel.value = paused.level
                val pausedToSave = withTeikaBodySaves(paused)
                saveScope.launch {
                    try {
                        prefs.saveGameState(GameStateJson.encodeToString(pausedToSave), level = pausedToSave.level)
                    } catch (e: Exception) {
                        android.util.Log.e("GameViewModel", "autoSave (PLAYING) failed", e)
                    }
                }
            }
            com.cukiti.teikafusion.model.GameStatus.PAUSED,
            com.cukiti.teikafusion.model.GameStatus.OBJECTIVES_REMINDER -> {
                _hasSavedGame.value = true
                _savedGameLevel.value = current.level
                val currentToSave = withTeikaBodySaves(current)
                saveScope.launch {
                    try {
                        prefs.saveGameState(GameStateJson.encodeToString(currentToSave), level = currentToSave.level)
                    } catch (e: Exception) {
                        android.util.Log.e("GameViewModel", "autoSave (PAUSED) failed", e)
                    }
                }
            }
            com.cukiti.teikafusion.model.GameStatus.REVIVE_OFFER -> {
                // Player left while revive screen was showing — deduct the life now so it
                // can't be recovered by force-quitting. State stays REVIVE_OFFER; the UI
                // will handle it correctly on return. spendLifeForDefeat evita que declineRevive
                // vuelva a cobrar la misma derrota al regresar (antes se perdían 2 vidas).
                //
                // EXCEPCIÓN: no se descuenta vida si el jugador YA se comprometió a revivir:
                //  - _rewardedAdActive: abrir nuestro rewarded ad provoca onPause; revivir por anuncio
                //    es gratis (sin esto perdía una vida pese a ver el anuncio entero).
                //  - _isAutoReviving: corre el auto-juego de revivir (ya pagó monedas o vio el anuncio);
                //    minimizar durante esos ~2 s no debe penalizar.
                if (!_rewardedAdActive.value && !_isAutoReviving.value)
                    spendLifeForDefeat()
            }
            else -> { /* No hay partida activa, nada que guardar */ }
        }
        // Persist lives unconditionally so they survive app kill / back-press
        val livesToSave = _lives.value
        val regenToSave = _livesNextRegenAt.value
        saveScope.launch {
            try { prefs.saveLives(livesToSave, regenToSave) } catch (_: Exception) {}
        }
    }

    /**
     * Programa las notificaciones LOCALES de reenganche al pasar a 2º plano: energía llena (según la
     * regeneración de vidas), reto diario (~19h) y racha en peligro ("Día N 🔥", ~20h). Idempotente —
     * WorkManager usa trabajo único con REPLACE, así que recalcular en cada onPause es seguro.
     */
    fun scheduleReengagementNotifications() {
        // El interruptor del jugador manda (P-166): sin él, apagarlo en Ajustes duraba hasta el
        // siguiente onPause, que es donde se reprograma todo.
        if (!_notificationsEnabled.value) {
            com.cukiti.teikafusion.NotificationScheduler.cancelAll(appContext)
            return
        }
        val lives = _lives.value
        val nextRegen = _livesNextRegenAt.value
        // Tiempo hasta llenar TODAS las vidas: la 1ª regenera en nextRegen, luego +REGEN por restante.
        val msUntilFull = if (lives >= LIVES_MAX || nextRegen <= 0L) 0L
            else (nextRegen - System.currentTimeMillis()) +
                 (LIVES_MAX - lives - 1).coerceAtLeast(0) * LIVES_REGEN_MS
        com.cukiti.teikafusion.NotificationScheduler.scheduleEnergyFull(appContext, msUntilFull)
        com.cukiti.teikafusion.NotificationScheduler.scheduleDailyReminder(appContext)
        viewModelScope.launch {
            val lastPlayed = try { prefs.lastPlayedDayFlow.first() } catch (_: Exception) { -1L }
            val playedToday = lastPlayed == java.time.LocalDate.now().toEpochDay()
            com.cukiti.teikafusion.NotificationScheduler.scheduleStreakReminder(appContext, _dailyStreak.value, playedToday)
        }
    }

    /**
     * Vuelta a 1º PLANO: la música se reanuda **solo si nadie la había callado a propósito**.
     *
     * `MainActivity.onWindowFocusChanged` llamaba a `resumeBgm()` a secas, y ese callback llega en
     * situaciones en las que el silencio era deliberado:
     *  · **partida en PAUSA** — `pauseGame`/`autoSaveAndPause` paran la BGM; bastaba bajar la
     *    persiana de notificaciones y volver para que la música arrancara con el menú de pausa
     *    delante (y ahí sigue el juego parado).
     *
     * Al reanudar la partida (`resumeGame`) se devuelve la música.
     */
    fun resumeBgmIfAllowed() {
        if (_gameState.value.status == com.cukiti.teikafusion.model.GameStatus.PAUSED) return
        soundManager.resumeBgm()
    }

    /** Al volver a 1º plano la notificación de energía ya no aplica (está jugando) → cancelarla. */
    fun cancelEnergyNotification() {
        com.cukiti.teikafusion.NotificationScheduler.cancelEnergyFull(appContext)
    }

    fun resumeGame() {
        if (_gameState.value.status == com.cukiti.teikafusion.model.GameStatus.PAUSED) {
            if(_gameState.value.clawTrip != null && !_boardBusy.value) { boardBusyEnter(); clawBusy=true }
            _gameState.update { it.copy(status = com.cukiti.teikafusion.model.GameStatus.PLAYING) }
            if(!boardChainActive && ((_gameState.value.turbineGust?.chainPending==true) || !_boardBusy.value) && (_gameState.value.turbineGust?.chainPending==true || _gameState.value.relayPendingFootprint.isNotEmpty() || _gameState.value.compactorPending || _gameState.value.orbitPending || _gameState.value.portalSwapPending || _gameState.value.forgePending || _gameState.value.reactorPending || _gameState.value.ballPending)) {
                launchRoundJob {
                    boardBusyEnter()
                    try { resolveBoardChain(initialDelayMs=0L); burstRelay(); finishPendingBoardTools(); saveCurrentState(_gameState.value) }
                    finally { boardBusyExit() }
                }
            }
            soundManager.resumeBgm()
        }
    }

    /**
     * **Auto-sanado del mute maestro** (bloque 24, 2026-07-31). Subir un volumen es, sin ambigüedad,
     * pedir oír algo: si el silencio general estaba puesto, se levanta.
     *
     * No es un adorno: el mute maestro **no tiene hoy ningún botón** en toda la app (`isMuted` y
     * `onToggleMute` son parámetros muertos en HomeScreen), así que un guardado con `is_muted = true`
     * dejaba el juego mudo PARA SIEMPRE — el jugador movía los dos sliders al máximo y no sonaba
     * nada. Con esto, mover cualquier volumen lo devuelve al mundo.
     */
    private fun liftMasterMute() {
        if (!_isMuted.value) return
        soundManager.setMuted(false)
        _isMuted.value = false
        viewModelScope.launch { prefs.saveMute(false) }
    }

    /** Fija el volumen de la música (0f..1f) en vivo y persiste. */
    fun setMusicVolume(volume: Float) {
        val v = volume.coerceIn(0f, 1f)
        if (v > 0f) liftMasterMute()
        soundManager.setMusicVolume(v)
        _musicVolume.value = v
        viewModelScope.launch { prefs.saveMusicVolume(v) }
    }

    /** Fija el volumen de los efectos (0f..1f) y persiste. */
    fun setSfxVolume(volume: Float) {
        val v = volume.coerceIn(0f, 1f)
        if (v > 0f) liftMasterMute()   // ver liftMasterMute: hoy es la ÚNICA salida del mute
        soundManager.setSfxVolume(v)
        _sfxVolume.value = v
        viewModelScope.launch { prefs.saveSfxVolume(v) }
    }

    /** Activa/desactiva la vibración (feedback háptico) y persiste. */
    fun setVibrationEnabled(enabled: Boolean) {
        com.cukiti.teikafusion.ui.Haptics.enabled = enabled
        _vibrationEnabled.value = enabled
        // MUESTRA al encender: un interruptor de vibración que no vibra al activarse no dice si ha
        // funcionado — el jugador se queda mirando un punto de color. Es el único ajuste cuyo efecto
        // no se puede ver ni oír. (Al apagar no se vibra, obviamente: sería contradecirse.)
        if (enabled) com.cukiti.teikafusion.ui.Haptics.tap()
        viewModelScope.launch { prefs.saveVibrationEnabled(enabled) }
    }

    fun toggleVibration() = setVibrationEnabled(!_vibrationEnabled.value)

    /**
     * Enciende/apaga los avisos de reenganche y persiste (P-166).
     *
     * Al apagar **cancela lo que ya estaba en la cola**: dejar de programarlos no basta, porque los
     * tres avisos viven en WorkManager con horas de retraso y seguirían saltando después de que el
     * jugador dijera que no los quiere. Al encender no se programa nada aquí a propósito — lo hace
     * `scheduleReengagementNotifications` en el siguiente `onPause`, que es cuando se sabe cuánto
     * falta para las vidas llenas.
     */
    fun setNotificationsEnabled(enabled: Boolean) {
        _notificationsEnabled.value = enabled
        if (!enabled) com.cukiti.teikafusion.NotificationScheduler.cancelAll(appContext)
        viewModelScope.launch { prefs.saveNotificationsEnabled(enabled) }
    }

    fun toggleNotifications() = setNotificationsEnabled(!_notificationsEnabled.value)

    /** Activa/desactiva la inclinación (Teikas ruedan al inclinar el teléfono) y persiste. */
    fun setTiltEnabled(enabled: Boolean) {
        _tiltEnabled.value = enabled
        // Al apagar, deja la gravedad horizontal en reposo (el sensor de GameScreen ya reporta 0
        // al desregistrarse, pero esto evita que quede una inclinación colgada si no hay partida).
        if (!enabled) physicsWorld.setHorizontalGravity(0f)
        viewModelScope.launch { prefs.saveTiltEnabled(enabled) }
    }

    fun toggleTilt() = setTiltEnabled(!_tiltEnabled.value)

    /** Activa/desactiva «reducir efectos» y persiste (a partir de aquí manda el jugador, no el sistema). */
    fun setReducedFx(enabled: Boolean) {
        _reducedFx.value = enabled
        viewModelScope.launch { prefs.saveReducedFx(enabled) }
    }

    fun toggleReducedFx() = setReducedFx(!_reducedFx.value)

    /**
     * ¿El SISTEMA tiene las animaciones desactivadas? (Accesibilidad → "Quitar animaciones", o
     * Opciones de desarrollador con las escalas a 0.) Es la señal estándar de Android para decir
     * "no me muevas la pantalla", y la respetamos como valor de arranque de [reducedFx].
     */
    private fun systemAnimationsDisabled(): Boolean = try {
        android.provider.Settings.Global.getFloat(
            appContext.contentResolver,
            android.provider.Settings.Global.ANIMATOR_DURATION_SCALE,
            1f
        ) == 0f
    } catch (_: Exception) { false }

    /** Master mute (botón rápido 🔊/🔇): silencia/restaura todo. Devuelve si quedó muteado y persiste. */
    fun toggleMute(): Boolean {
        val newMuted = soundManager.toggleMute()
        _isMuted.value = newMuted
        viewModelScope.launch { prefs.saveMute(newMuted) }
        return newMuted
    }

    /**
     * Continúa la secuencia guiada. Tras el cuarto Mega entra directamente al nivel 5; la única
     * invitación opcional de respaldo queda encolada hasta que el jugador vuelva a Inicio.
     */
    fun advanceTutorial() {
        val level = _gameState.value.level
        if (!com.cukiti.teikafusion.model.TutorialCampaign.isTutorialLevel(level)) return
        if (level < com.cukiti.teikafusion.model.TutorialCampaign.LAST_LEVEL) {
            nextLevel()
            return
        }
        if (!_showTutorial.value) {
            nextLevel()
            return
        }
        Analytics.trackTutorialDone()
        if (!isCloudAccount()) _showPostTutorialBackupPrompt.value = true
        _showTutorial.value = false
        viewModelScope.launch { prefs.saveTutorialDone() }
        nextLevel()
    }

    /**
     * **SALTAR EL TUTORIAL** (2026-09-01, decisión del usuario: saltable desde la primera lección).
     *
     * Da la campaña por vista y arranca el primer nivel de verdad. Quien reinstala, o quien ya sabe
     * jugar, no se come siete lecciones — y el que las necesita las tiene enteras.
     *
     * Hace exactamente lo mismo que terminar la última lección (marca `tutorial_done`, avisa a
     * analítica y ofrece el respaldo), porque para todo lo demás del juego el tutorial está hecho:
     * dejarlo a medias por dentro es cómo se acaba reapareciendo en la lección 3 tras un reinicio.
     */
    fun skipTutorial() {
        if (!com.cukiti.teikafusion.model.TutorialCampaign.isTutorialLevel(_gameState.value.level)) return
        if (_showTutorial.value) {
            Analytics.trackTutorialDone()
            if (!isCloudAccount()) _showPostTutorialBackupPrompt.value = true
            _showTutorial.value = false
            viewModelScope.launch { prefs.saveTutorialDone() }
        }
        clearSlowMotion()
        // ── EL PRIMER NIVEL DE VERDAD QUEDA ABIERTO (2026-09-04) ──────────────────────────────
        // Esto llamaba a `startGame(LAST_LEVEL + 1)` y **no hacía nada**: la primera guarda de
        // `startGame` es `if (level > maxUnlockedLevel) return`, y quien acaba de instalar el juego
        // tiene la frontera en 1. O sea que en una instalación limpia —el caso para el que existe el
        // botón— saltar el tutorial dejaba al jugador exactamente donde estaba, con la campaña ya
        // marcada por vista. Saltar las siete lecciones ES superarlas: la frontera se mueve.
        val firstRealLevel = com.cukiti.teikafusion.model.TutorialCampaign.LAST_LEVEL + 1
        val newMax = maxOf(_gameState.value.maxUnlockedLevel, firstRealLevel)
        _gameState.update { it.copy(maxUnlockedLevel = newMax) }
        viewModelScope.launch { prefs.saveMaxLevel(newMax) }
        // La lección que se abandona no es un intento reanudable.
        viewModelScope.launch { prefs.saveGameState(null) }
        _hasSavedGame.value = false
        // Y AL INICIO, no directamente a jugar (2026-09-04, pedido del usuario): «que lo mande
        // directamente al inicio del juego listo para jugar el nivel 1». El cursor de Home queda en
        // el primer nivel de verdad —el que el jugador ve como NIVEL 1, ver `LevelMap.displayNumber`—
        // así que JUGAR arranca ahí sin tener que buscarlo en el mapa.
        setSelectedLevel(firstRealLevel)
        goHome()
    }

    /** Registra la versión actual de términos y privacidad aceptada por el jugador. */
    fun acceptLegalDocuments() {
        viewModelScope.launch {
            // Persistir primero: si el proceso muere al iniciar el tablero, no se pide aceptar otra vez.
            prefs.saveLegalConsent()
            _legalConsentAccepted.value = true
            if (_showTutorial.value) startGame(com.cukiti.teikafusion.model.TutorialCampaign.FIRST_LEVEL)
        }
    }

    /** Resetea record, niveles y XP. Conserva teikoins, power-ups, habilidades y cosméticos. */
    fun resetProgress() {
        // Y lo APRENDIDO: quien empieza de cero vuelve a encontrarse las mecanicas por primera vez,
        // asi que tiene que volver a recibir sus explicaciones.
        resetMechanicCapsules()
        // Cancelar jobs de compañeros que podrían actualizar _gameState tras el reset.
        cinematicJob?.cancel()
        glaciarJob?.cancel()
        siestaJob?.cancel()
        plantaJob?.cancel()

        // Limpiar estado de UI en vuelo para evitar overlays/modos bloqueados post-reset.
        _companionCinematic.value = null
        _wildcardSelectionsLeft.value = 0
        _dragState.value = DragState.Idle

        val currentTeikoins = _gameState.value.teikoins
        val uid         = _currentUid.value
        val displayName = _displayName.value.ifEmpty { "Player" }
        val avatarType  = _avatarType.value

        viewModelScope.launch {
            prefs.resetProgressOnly()
            // Solo cuentas vinculadas tienen datos en la nube. El reset es TOTAL: además del
            // player_stats/leaderboard, se borra el respaldo cloud_saves para que al reconectar no
            // reviva el progreso viejo.
            if (uid != null && isCloudAccount()) {
                com.cukiti.teikafusion.LeaderboardRepository.forceResetProgress(uid)
                com.cukiti.teikafusion.CloudSaveRepository.delete(uid)
                // El respaldo borrado se lleva también lo que NO es progreso y se conserva: el
                // paquete inicial entregado, los bonos de primera compra, los bloques comprados. Sin
                // re-subirlo, reinstalar antes de la próxima subida volvía a entregar el paquete
                // (Play lo re-entrega en cada arranque y su marca vive en la nube).
                pushCloudSave()
            }
        }

        Analytics.trackProgressReset()

        _hasSavedGame.value = false
        _totalXp.value = 0

        // Progresión por niveles: compañeros, mejoras de habilidad y cristales vuelven a cero.
        _claimedCharacterIds.value = emptySet()
        _companionUpgrades.value = com.cukiti.teikafusion.model.CompanionAbilityUpgrades()
        _crystalInventory.value = com.cukiti.teikafusion.model.CrystalInventory()
        _lastCrystalDrop.value = 0
        _selectedCompanionId.value = null
        // `resetProgressOnly` borra del disco el cinturón: la memoria tiene que quedar IGUAL. Antes
        // seguía vivo hasta reiniciar la app — power-ups elegidos que ya no tenías (auditoría
        // 2026-10-01). Los USOS se conservan (P-433): se pagaron con teikoins.
        _companionBelt.value = com.cukiti.teikafusion.model.CompanionBelt()

        _gameState.value = GameState.initial().copy(
            status    = com.cukiti.teikafusion.model.GameStatus.HOME,
            teikoins  = currentTeikoins,
            highScore = 0,
            maxTeikas = 0
        )
        // _unlockedCosmetics, _activeCosmetic, _lives, teikoins y _companionCharges (P-433):
        // no son progreso de niveles (incluyen compras) — se conservan intencionalmente.
    }

    // ── Lives logic ──────────────────────────────────────────────────────────────

    private suspend fun loadAndRegenLives() {
        val savedLives = prefs.livesFlow.first()
        val savedNextRegen = prefs.livesNextRegenAtFlow.first()
        // La aritmética (y su guarda contra la vida gratis al reabrir) vive en `LivesRules`, que es
        // la única copia y tiene test. Aquí solo queda decidir qué hacer con el resultado.
        val regen = com.cukiti.teikafusion.model.LivesRules.regenerate(
            lives = savedLives, nextRegenAt = savedNextRegen, now = System.currentTimeMillis()
        )
        _lives.value = regen.lives
        _livesNextRegenAt.value = regen.nextRegenAt
        if (regen.changed) prefs.saveLives(regen.lives, regen.nextRegenAt)
    }

    private fun startLivesRegenLoop() {
        viewModelScope.launch {
            while (true) {
                kotlinx.coroutines.delay(30_000L) // check every 30 s
                val regen = com.cukiti.teikafusion.model.LivesRules.regenerate(
                    lives = _lives.value,
                    nextRegenAt = _livesNextRegenAt.value,
                    now = System.currentTimeMillis()
                )
                if (regen.changed) {
                    _lives.value = regen.lives
                    _livesNextRegenAt.value = regen.nextRegenAt
                    prefs.saveLives(regen.lives, regen.nextRegenAt)
                }
            }
        }
    }

    /** Descuenta exactamente 1 vida por derrota (idempotente hasta la siguiente partida). */
    private fun spendLifeForDefeat(playSound: Boolean = true) {
        if (lifeAlreadySpentForDefeat) return
        lifeAlreadySpentForDefeat = true
        spendLife(playSound = playSound)
    }

    /** Cierra el overlay "Sin vidas" sin hacer nada más. */
    fun dismissOutOfLivesPrompt() {
        _outOfLivesPrompt.value = false
        pendingLevelForLives = null
    }

    /**
     * Compra [amount] vidas desde el overlay "Sin vidas" y, si la compra prosperó, arranca
     * automáticamente el nivel que el jugador intentaba jugar. Si faltan teikoins, [buyLives]
     * no hace nada y el overlay permanece abierto.
     */
    fun buyLivesAndContinue(amount: Int) {
        val before = _lives.value
        buyLives(amount)
        if (_lives.value > before) {
            val lvl = pendingLevelForLives
            _outOfLivesPrompt.value = false
            pendingLevelForLives = null
            if (lvl != null) startGame(lvl)
        }
    }

    /** Descuenta 1 vida (llamar antes de iniciar un nivel clásico). Devuelve false si no hay vidas. */
    fun spendLife(playSound: Boolean = true): Boolean {
        // Vidas infinitas activas: se puede jugar siempre y NO se descuenta nada.
        if (isInfiniteLivesActive()) return true
        val current = _lives.value
        if (current <= 0) return false
        val newLives = current - 1
        val now = System.currentTimeMillis()
        val newNextRegen = if (_livesNextRegenAt.value == 0L && newLives < LIVES_MAX)
            now + LIVES_REGEN_MS else _livesNextRegenAt.value
        _lives.value = newLives
        _livesNextRegenAt.value = newNextRegen
        if (playSound) soundManager.playLifeLost()   // se perdió un corazón
        viewModelScope.launch { prefs.saveLives(newLives, newNextRegen) }
        return true
    }

    /** Compra vidas con teikoins. amount = cantidad de vidas, cost = precio total en teikoins. */
    fun buyLives(amount: Int) {
        val cost = when (amount) {
            1 -> 50
            3 -> 120
            else -> 200 // full refill
        }
        if (_gameState.value.teikoins < cost) return
        val newTeikoins = _gameState.value.teikoins - cost
        val newLives = (_lives.value + amount).coerceAtMost(LIVES_MAX)
        val gained = newLives - _lives.value
        _gameState.update { it.copy(teikoins = newTeikoins) }
        _lives.value = newLives
        _livesNextRegenAt.value = if (newLives >= LIVES_MAX) 0L else _livesNextRegenAt.value
        soundManager.playPurchase()
        viewModelScope.launch {
            prefs.saveTeikoins(newTeikoins)
            prefs.saveLives(newLives, _livesNextRegenAt.value)
        }
        // Reveal épico de lo conseguido (compra pequeña: sin sorpresa).
        emitReveal(
            title = "¡RECARGA!",
            accentArgb = 0xFFFF4D6D,
            items = listOf(
                com.cukiti.teikafusion.model.RewardItem(
                    kind = com.cukiti.teikafusion.model.RewardKind.LIVES,
                    label = if (gained == 1) "1 vida" else "$gained vidas",
                    amount = gained
                )
            )
        )
    }

    // ── Vidas infinitas: otorgar / comprar ─────────────────────────────────────────────────────

    /** Extiende las vidas infinitas [ms] milisegundos (acumula sobre el tiempo restante). */
    fun grantInfiniteLives(ms: Long) {
        val base = maxOf(System.currentTimeMillis(), _infiniteLivesUntil.value)
        val until = base + ms
        _infiniteLivesUntil.value = until
        // Al activarse, las vidas quedan "llenas" a efectos de UI y se detiene el reloj de regen.
        if (_lives.value < LIVES_MAX) { _lives.value = LIVES_MAX; _livesNextRegenAt.value = 0L }
        viewModelScope.launch {
            prefs.saveInfiniteLivesUntil(until)
            prefs.saveLives(_lives.value, 0L)
        }
    }

    /** Compra un pack de vidas infinitas con teikoins (packs caros de [INFINITE_LIVES_PACKS]). */
    fun buyInfiniteLives(hours: Int) {
        val pack = INFINITE_LIVES_PACKS.firstOrNull { it.hours == hours } ?: return
        if (_gameState.value.teikoins < pack.cost) return
        val newTeikoins = _gameState.value.teikoins - pack.cost
        _gameState.update { it.copy(teikoins = newTeikoins) }
        grantInfiniteLives(pack.hours * ONE_HOUR_MS)
        soundManager.playPurchase()
        viewModelScope.launch { prefs.saveTeikoins(newTeikoins) }
        // Pack grande ⇒ tira una SORPRESA además de las vidas infinitas.
        val items = mutableListOf(
            com.cukiti.teikafusion.model.RewardItem(
                kind = com.cukiti.teikafusion.model.RewardKind.INFINITE_LIVES,
                label = "Vidas infinitas ${pack.hours}h",
                amount = pack.hours
            )
        )
        rollSurpriseBonus()?.let { items.add(it) }
        emitReveal(title = "¡VIDAS INFINITAS!", accentArgb = 0xFFFFD700, items = items)
    }

    /**
     * Tira un premio SORPRESA del pool para packs grandes: cristal mágico, un skin de bloque gratis
     * (si queda alguno por desbloquear) o un pequeño empujón de vidas infinitas. Aplica el efecto
     * (inventario/cosmético/tiempo) y devuelve el [RewardItem] para el reveal (null si nada tocó).
     */
    private fun rollSurpriseBonus(): com.cukiti.teikafusion.model.RewardItem? {
        // P-250: solo entre los bloques ya DESCUBIERTOS — el sorteo no puede adelantarle al jugador
        // el premio de un bioma que todavía no ha terminado.
        val lockedSkin = com.cukiti.teikafusion.ui.BlockSkins.all
            .firstOrNull {
                it.priceTeikoins > 0 && it.id !in _unlockedCosmetics.value &&
                    com.cukiti.teikafusion.model.BlockDiscovery.isDiscovered(it.id, _gameState.value.maxUnlockedLevel)
            }
        // Opciones disponibles según el estado actual (no regalar un skin ya poseído).
        val options = buildList {
            add("crystal")
            if (lockedSkin != null) add("skin")
            add("infinite")
        }
        return when (options.random(rng)) {
            "skin" -> {
                val skin = lockedSkin!!
                val newCosmetics = _unlockedCosmetics.value + skin.id
                _unlockedCosmetics.value = newCosmetics
                viewModelScope.launch { prefs.saveUnlockedCosmetics(newCosmetics) }
                com.cukiti.teikafusion.model.RewardItem(
                    kind = com.cukiti.teikafusion.model.RewardKind.BLOCK_SKIN,
                    label = "Bloque ${skin.name} GRATIS", skinId = skin.id, bonus = true
                )
            }
            "infinite" -> {
                grantInfiniteLives(ONE_HOUR_MS)
                com.cukiti.teikafusion.model.RewardItem(
                    kind = com.cukiti.teikafusion.model.RewardKind.INFINITE_LIVES,
                    label = "+1h vidas infinitas", amount = 1, bonus = true
                )
            }
            else -> {
                // Cristal: 1-2 a la mochila (el cristal es escaso a propósito, P-267).
                val qty = (1..2).random(rng)
                grantCrystals(qty)
                com.cukiti.teikafusion.model.RewardItem(
                    kind = com.cukiti.teikafusion.model.RewardKind.CRYSTAL,
                    label = if (qty == 1) "1 cristal" else "$qty cristales",
                    amount = qty, bonus = true
                )
            }
        }
    }

    /** Emite un reveal épico con un id nuevo (relanza el overlay aunque el contenido se repita). */
    private fun emitReveal(title: String, accentArgb: Long, items: List<com.cukiti.teikafusion.model.RewardItem>) {
        _purchaseReveal.value = com.cukiti.teikafusion.model.PurchaseReveal(
            id = revealIdCounter++, title = title, accentArgb = accentArgb, items = items
        )
    }

    // ── Cloud save (Firestore, solo usuarios vinculados) ─────────────────────────
    // El I/O vive en CloudSaveRepository. Aquí solo serializamos el progreso y fusionamos
    // lo que baja de la nube. Orquestado por syncCloudSaveOnSignIn / pushCloudSave.

    private suspend fun buildCloudSaveJson(): String = buildCloudSaveData().toJson()

    /**
     * Sube el progreso local a Firestore **fusionándolo en transacción** con lo que haya en la nube.
     *
     * Todas las subidas pasan por aquí. La fusión dentro de la transacción es lo que impide que dos
     * dispositivos con la misma cuenta se pisen: el que escribe segundo ya no borra lo del primero,
     * porque relee y aplica `mergedWith` (máximos por campo) antes de confirmar.
     */
    private suspend fun saveCloudMerged(uid: String): Boolean {
        // El perfil local no se pudo leer entero: lo que hay en memoria son valores por defecto, no
        // el progreso del jugador. Subirlos pisaría la nube con un jugador vacío, y eso no tiene
        // vuelta atrás. Se comprueba aquí por el mismo motivo que el kill-switch de abajo: este es
        // el ÚNICO punto de subida. Ver [localProfileLoadFailed].
        if (localProfileLoadFailed) {
            android.util.Log.w("GameViewModel", "Perfil local roto: NO se sube nada a la nube en esta sesión")
            return false
        }
        // Kill-switch remoto: si Firestore se satura o el respaldo empieza a corromper guardados,
        // se apaga desde la consola y el juego sigue funcionando 100 % en local. Se comprueba aquí
        // —el único punto de subida— para que ninguna ruta se escape.
        if (!_remoteConfig.value.cloudSyncEnabled) {
            android.util.Log.w("GameViewModel", "Cloud sync DESACTIVADO por Remote Config")
            return false
        }
        val local = buildCloudSaveData()
        val localJson = local.toJson()
        // P-162 · NO SE SUBE LO QUE YA ESTÁ SUBIDO.
        // El documento de nube es UN blob: cada `onPause` reescribía el progreso entero, y desde el
        // esquema v4 eso arrastra además decenas de KB de tablero aunque el jugador no haya tocado
        // nada (volver de segundo plano, abrir un enlace, girar el móvil). Se compara la huella del
        // snapshot —sin la hora de sincronización, que cambia siempre— con la de la última subida
        // que salió bien, y si son la misma no se gasta escritura. La huella vive en memoria a
        // propósito: al reabrir la app se sube de nuevo, que es la red de seguridad por si el
        // documento cambió en el servidor.
        val fingerprint = cloudFingerprintOf(local)
        if (fingerprint == lastPushedFingerprint) {
            android.util.Log.i("GameViewModel", "Cloud push omitido: nada ha cambiado desde la última subida")
            return true
        }
        val ok = com.cukiti.teikafusion.CloudSaveRepository.save(uid, localJson) { remoteJson ->
            val remote = remoteJson?.let { com.cukiti.teikafusion.model.CloudSaveData.fromJson(it) }
            if (remote == null) localJson else local.mergedWith(remote).toJson()
        }
        if (ok) lastPushedFingerprint = fingerprint
        return ok
    }

    /**
     * Huella del progreso subido: longitud + hash del JSON **sin `updatedAtEpochMs`**, que es la hora
     * de la sincronización y por sí sola haría distinto a cada snapshot. El par (longitud, hash) hace
     * que una colisión —que costaría una subida omitida— sea irrelevante en la práctica.
     */
    private fun cloudFingerprintOf(data: com.cukiti.teikafusion.model.CloudSaveData): Pair<Int, Int> {
        val normalized = data.copy(updatedAtEpochMs = 0L).toJson()
        return normalized.length to normalized.hashCode()
    }

    @Volatile private var lastPushedFingerprint: Pair<Int, Int>? = null

    private suspend fun buildCloudSaveData(): com.cukiti.teikafusion.model.CloudSaveData {
        val s = _gameState.value
        val localBoard = localBoardForCloud()
        return com.cukiti.teikafusion.model.CloudSaveData(
            updatedAtEpochMs   = System.currentTimeMillis(),
            maxLevel          = s.maxUnlockedLevel,
            teikoins          = s.teikoins,
            highScore         = s.highScore,
            maxTeikas         = s.maxTeikas,
            totalXp           = _totalXp.value,
            claimedCharacters = claimedCharacterIds.value.toList(),
            teikaAbilityLoadout = _teikaAbilityLoadout.value,
            companionUpgrades = _companionUpgrades.value,
            companionCharges  = _companionCharges.value,
            companionBelt     = _companionBelt.value,
            crystalInventory  = _crystalInventory.value,
            unlockedCosmetics = _unlockedCosmetics.value.toList(),
            activeCosmetic     = _activeCosmetic.value,
            avatarType        = _avatarType.value.name,
            selectedCompanion = _selectedCompanionId.value,
            displayName       = _displayName.value,
            tutorialDone      = !_showTutorial.value,
            // schema v3: estrellas, flags anti-exploit y racha. Los sets/streak no viven como
            // StateFlow en memoria, así que se leen de DataStore.
            levelStars        = _levelStars.value,
            muralRewards      = prefs.muralRewardsFlow.first().toList(),
            crystalAwardedLevels = prefs.crystalAwardedFlow.first().toList(),
            dailyStreak       = _dailyStreak.value,
            lastPlayedDay     = prefs.lastPlayedDayFlow.first(),
            adsRemoved        = _adsRemoved.value,
            starterPackGranted = _starterPackGranted.value,
            candyRefunded     = _candyRefunded.value,
            blockBankPurchased = _blockBankPurchased.value,
            coinBonusClaimed  = _coinBonusClaimed.value.toList(),
            bestCombo         = _bestCombo.value,
            // schema v4: vidas y partida en curso (P-113/P-114). Ver `localBoardForCloud`.
            lives             = _lives.value,
            livesNextRegenAtMs = _livesNextRegenAt.value,
            infiniteLivesUntilMs = _infiniteLivesUntil.value,
            gameStateJson     = localBoard.first,
            gameSavedAtMs     = localBoard.second
        )
    }

    /**
     * El tablero local tal y como debe viajar a la nube, **con su hora**: la ranura de DataStore, o
     * `null` si pesa más de lo razonable (ver `CloudSaveData.MAX_GAME_STATE_JSON` — el documento
     * entero tiene 1 MB de tope y el progreso de la cuenta vale más que un intento suelto).
     *
     * La hora `0` de una ranura que SÍ existe es la de un guardado anterior al esquema v4, cuando
     * nadie la estampaba. Se sustituye por la de ahora a propósito: en un conflicto, el desempate
     * favorece al tablero del aparato que el jugador tiene delante, no al que lleva meses en la nube.
     */
    private suspend fun localBoardForCloud(): Pair<String?, Long> {
        val json = prefs.savedGameStateFlow.first()
            ?.takeIf { it.length <= com.cukiti.teikafusion.model.CloudSaveData.MAX_GAME_STATE_JSON }
            ?: return null to 0L
        val savedAt = prefs.savedGameAtFlow.first()
        return json to (if (savedAt > 0L) savedAt else System.currentTimeMillis())
    }

    /** Foto del progreso local actual como CloudSaveData (para fusionar/comparar con la nube). */
    private suspend fun localProgressSnapshot(): com.cukiti.teikafusion.model.CloudSaveData {
        val s = _gameState.value
        val localBoard = localBoardForCloud()
        return com.cukiti.teikafusion.model.CloudSaveData(
            maxLevel = s.maxUnlockedLevel,
            teikoins = s.teikoins,
            highScore = s.highScore,
            maxTeikas = s.maxTeikas,
            totalXp = _totalXp.value,
            claimedCharacters = _claimedCharacterIds.value.toList(),
            teikaAbilityLoadout = _teikaAbilityLoadout.value,
            companionUpgrades = _companionUpgrades.value,
            companionCharges = _companionCharges.value,
            companionBelt = _companionBelt.value,
            crystalInventory = _crystalInventory.value,
            unlockedCosmetics = _unlockedCosmetics.value.toList(),
            activeCosmetic = _activeCosmetic.value,
            avatarType = _avatarType.value.name,
            selectedCompanion = _selectedCompanionId.value,
            displayName = _displayName.value,
            tutorialDone = !_showTutorial.value,
            levelStars = _levelStars.value,
            muralRewards = prefs.muralRewardsFlow.first().toList(),
            crystalAwardedLevels = prefs.crystalAwardedFlow.first().toList(),
            dailyStreak = _dailyStreak.value,
            lastPlayedDay = prefs.lastPlayedDayFlow.first(),
            adsRemoved = _adsRemoved.value,
            starterPackGranted = _starterPackGranted.value,
            candyRefunded = _candyRefunded.value,
            blockBankPurchased = _blockBankPurchased.value,
            coinBonusClaimed = _coinBonusClaimed.value.toList(),
            bestCombo = _bestCombo.value,
            lives = _lives.value,
            livesNextRegenAtMs = _livesNextRegenAt.value,
            infiniteLivesUntilMs = _infiniteLivesUntil.value,
            gameStateJson = localBoard.first,
            gameSavedAtMs = localBoard.second
        )
    }

    /** true si este perfil tiene avance real (no es un arranque limpio). Ignora las monedas (ruidosas). */
    private fun com.cukiti.teikafusion.model.CloudSaveData.hasMeaningfulProgress(): Boolean =
        maxLevel > 1 || totalXp > 0 || maxTeikas > 0 || claimedCharacters.isNotEmpty() ||
            levelStars.isNotEmpty() || unlockedCosmetics.isNotEmpty()

    /** Fusiona el progreso cloud con el local y persiste todos los campos restaurables. */
    private suspend fun mergeCloudProgress(json: String) {
        val cloud = com.cukiti.teikafusion.model.CloudSaveData.fromJson(json) ?: run {
            android.util.Log.e("GameViewModel", "mergeCloudProgress: JSON inválido")
            return
        }
        applyCloudData(localProgressSnapshot().mergedWith(cloud), cloud.schemaVersion)
    }

    // El eje de la elección es el NIVEL desbloqueado (`maxLevel`): "entrar a la cuenta anterior" usa el
    // de la nube; "mantener mi progreso actual" usa el local. TODO lo demás se fusiona por máximo/unión
    // (monedas, XP, estrellas, compras, cristales, racha, flags anti-doble-cobro), así ninguna opción
    // pierde dinero/compras ni abre exploits. (applyCloudData solo SUBE el XP: prefs.addXp es aditivo.)

    /** "Entrar a la cuenta anterior": adopta el nivel de la nube; el resto se fusiona por máximo. */
    private suspend fun overwriteWithCloudProgress(cloud: com.cukiti.teikafusion.model.CloudSaveData) {
        val safe = localProgressSnapshot().mergedWith(cloud).copy(maxLevel = cloud.maxLevel)
        val cloudBoardInstalled = applyCloudData(safe, cloud.schemaVersion)
        // La partida en progreso era de la sesión local (invitado): al cargar la cuenta anterior se
        // descarta para no reanudar un nivel por encima del máximo de la cuenta cargada.
        // EXCEPCIÓN desde v4 (P-113): si la nube ha traído SU propio intento, ese sí es de la cuenta
        // que se acaba de cargar — borrarlo sería tirar justo lo que el jugador venía a recuperar.
        if (!cloudBoardInstalled) {
            prefs.saveGameState(null)
            _hasSavedGame.value = false
        }
    }

    /** "Mantener mi progreso actual": conserva el nivel local; el resto se fusiona por máximo. */
    private suspend fun keepLocalProgress(cloud: com.cukiti.teikafusion.model.CloudSaveData) {
        val local = localProgressSnapshot()
        applyCloudData(local.mergedWith(cloud).copy(maxLevel = local.maxLevel), cloud.schemaVersion)
    }

    /**
     * Aplica un CloudSaveData (ya sea fusionado o de la nube) al estado en memoria y a DataStore.
     *
     * Devuelve **true si ha instalado la partida en curso que venía de la nube** — lo necesita
     * `overwriteWithCloudProgress`, que borra el intento local salvo que sea justo el que acaba de
     * bajar de la cuenta.
     */
    private suspend fun applyCloudData(
        merged: com.cukiti.teikafusion.model.CloudSaveData,
        cloudSchema: Int
    ): Boolean {
        // Foto de lo que había ANTES de aplicar la fusión: es con lo que se decide si la nube ha
        // devuelto progreso y hay que avisar (P-24).
        val localBeforeMerge = localProgressSnapshot()
        _gameState.update { it.copy(
            maxUnlockedLevel = merged.maxLevel,
            teikoins = merged.teikoins,
            highScore = merged.highScore,
            maxTeikas = merged.maxTeikas
        ) }
        prefs.saveMaxLevel(merged.maxLevel)
        prefs.saveTeikoins(merged.teikoins)
        prefs.saveHighScore(merged.highScore)
        prefs.saveMaxTeikas(merged.maxTeikas)

        if (merged.totalXp > _totalXp.value) {
            _totalXp.value = prefs.addXp(merged.totalXp - _totalXp.value)
        }
        merged.claimedCharacters.forEach { prefs.claimCharacter(it) }
        _claimedCharacterIds.value = merged.claimedCharacters.toSet()
        retroClaimCompanions()   // Fase 3: tras restaurar nivel desde la nube, desbloquea compañeros por nivel

        _teikaAbilityLoadout.value = merged.teikaAbilityLoadout
        _companionUpgrades.value = merged.companionUpgrades
        _companionCharges.value = merged.companionCharges
        // El cinturón se sanea contra los personajes reclamados TRAS la fusión: la nube puede traer
        // uno equipado en otro móvil que aquí todavía no está reclamado.
        val mergedBelt = merged.companionBelt.sanitized(_claimedCharacterIds.value)
        _companionBelt.value = mergedBelt
        _crystalInventory.value = merged.crystalInventory
        _unlockedCosmetics.value = merged.unlockedCosmetics.toSet()
        _activeCosmetic.value = merged.activeCosmetic
        // El capitán sigue al cinturón fusionado (ranura 1); el valor de la nube solo cubre el
        // caso de un cinturón vacío.
        _selectedCompanionId.value = mergedBelt.slots.firstOrNull() ?: merged.selectedCompanion
        // Clamp defensivo: un save de nube manipulado (o de un esquema viejo sin límite) no debe
        // colar un nombre por encima del límite que impone saveDisplayName.
        _displayName.value = merged.displayName.trim().take(com.cukiti.teikafusion.model.MAX_DISPLAY_NAME_LENGTH)
        val mergedTutorialDone = com.cukiti.teikafusion.model.TutorialCampaign
            .isAlreadyCompleted(merged.tutorialDone, merged.maxLevel)
        _showTutorial.value = !mergedTutorialDone
        val mergedAvatar = merged.avatarType?.let {
            runCatching { com.cukiti.teikafusion.model.TeikaType.valueOf(it) }.getOrNull()
        } ?: _avatarType.value
        _avatarType.value = mergedAvatar

        prefs.saveTeikaAbilityLoadout(merged.teikaAbilityLoadout)
        prefs.saveCompanionUpgrades(merged.companionUpgrades)
        prefs.saveCompanionCharges(merged.companionCharges)
        prefs.saveCompanionBelt(mergedBelt)
        prefs.saveCrystalInventory(merged.crystalInventory)
        prefs.saveUnlockedCosmetics(merged.unlockedCosmetics.toSet())
        prefs.saveActiveCosmetic(merged.activeCosmetic)
        prefs.saveSelectedCompanion(_selectedCompanionId.value)
        prefs.saveAvatar(mergedAvatar)
        if (merged.displayName.isNotBlank()) prefs.saveDisplayName(merged.displayName.trim())
        if (mergedTutorialDone) prefs.saveTutorialDone()

        // ¿La nube ha DEVUELTO progreso que este dispositivo no tenía? Se anuncia (P-24). Se mira
        // el nivel y el récord de profundidad: son los dos números que el jugador reconoce como
        // "lo mío". Las monedas no entran — suben y bajan por mil motivos y darían falsos avisos.
        if (merged.maxLevel > localBeforeMerge.maxLevel) {
            _cloudRestoreNotice.value = "Progreso restaurado · nivel ${merged.maxLevel}"
        }

        // schema v3: estrellas, flags anti-exploit y racha.
        _levelStars.value = merged.levelStars
        prefs.saveLevelStarsAll(merged.levelStars)
        prefs.saveMuralRewardsAll(merged.muralRewards.toSet())
        prefs.saveCrystalAwardedAll(merged.crystalAwardedLevels.toSet())
        _dailyStreak.value = merged.dailyStreak
        prefs.saveStreakState(merged.dailyStreak, merged.lastPlayedDay)
        // Una compra nunca se revoca al fusionar: si la nube dice que pagó, se respeta.
        if (merged.adsRemoved && !_adsRemoved.value) applyAdsRemoved()
        // Las dos marcas del dinero se OBEDECEN, no se recalculan: vienen fusionadas por OR y por
        // unión, y bajarlas aquí reabriría justo la puerta que cierran — el paquete inicial se
        // volvería a entregar y los tres bonos de bienvenida volverían a estar disponibles.
        if (merged.starterPackGranted && !_starterPackGranted.value) {
            _starterPackGranted.value = true
            prefs.saveStarterPackGranted()
        }
        // P-249: la marca de la devolución se obedece igual —fusionada por OR— y DESPUÉS se vuelve a
        // pasar la retirada: la nube puede haber traído el Caramelo (comprado en otro móvil) o
        // haberlo dejado equipado. Con la marca ya puesta, eso solo lo desequipa; sin ella, paga.
        if (merged.candyRefunded && !_candyRefunded.value) {
            _candyRefunded.value = true
            prefs.saveCandyRefunded()
        }
        if (merged.blockBankPurchased && !_blockBankPurchased.value) {
            _blockBankPurchased.value = true
            prefs.saveBlockBankPurchased()
        }
        retireCandy()
        if (merged.coinBonusClaimed.isNotEmpty()) {
            val claimed = _coinBonusClaimed.value + merged.coinBonusClaimed
            if (claimed != _coinBonusClaimed.value) {
                _coinBonusClaimed.value = claimed
                prefs.saveCoinBonusClaimed(claimed)
            }
        }
        if (merged.bestCombo > _bestCombo.value) {
            _bestCombo.value = merged.bestCombo
            prefs.saveBestCombo(merged.bestCombo)
        }

        // ── schema v4: LAS VIDAS SON DE LA CUENTA (P-114) ───────────────────────────────────
        // Ya vienen fusionadas por MÍNIMO, así que aquí no se decide nada: se obedece. Es lo que
        // cierra la puerta trasera de reinstalar para tener la reserva llena. El tope y el suelo se
        // aplican igual que en `regenerate`, por si el documento viene manipulado.
        val cloudLives = merged.lives.coerceIn(0, LIVES_MAX)
        val cloudRegenAt = if (cloudLives >= LIVES_MAX) 0L else merged.livesNextRegenAtMs
        if (cloudLives != _lives.value || cloudRegenAt != _livesNextRegenAt.value) {
            _lives.value = cloudLives
            _livesNextRegenAt.value = cloudRegenAt
            prefs.saveLives(cloudLives, cloudRegenAt)
        }
        // El perk de infinitas viaja por MÁXIMO: se compra con teikoins y no se pierde al cambiar
        // de móvil. Nunca lo acorta — solo puede alargarlo.
        if (merged.infiniteLivesUntilMs > _infiniteLivesUntil.value) {
            _infiniteLivesUntil.value = merged.infiniteLivesUntilMs
            prefs.saveInfiniteLivesUntil(merged.infiniteLivesUntilMs)
        }

        // ── schema v4: EL INTENTO EN CURSO (P-113) ──────────────────────────────────────────
        val boardInstalled = installCloudBoardIfNewer(merged)

        android.util.Log.i(
            "GameViewModel",
            "Cloud apply OK: schema=$cloudSchema lvl=${merged.maxLevel} " +
                "coins=${merged.teikoins} xp=${merged.totalXp} chars=${merged.claimedCharacters.size} " +
                "stars=${merged.levelStars.size} streak=${merged.dailyStreak} " +
                "lives=$cloudLives board=$boardInstalled"
        )
        return boardInstalled
    }

    /**
     * Instala el tablero que viene de la nube **si es más reciente que el de este aparato** (P-113).
     *
     * Tres cautelas, todas con motivo:
     *  · **No pisa una ronda viva.** Si el jugador está dentro de un nivel, su siguiente colocación
     *    reescribe la ranura de todas formas; cambiarla por debajo solo podría confundirle.
     *  · **Valida antes de guardar.** Mismo criterio que `continueGame`: un tablero que no decodifica
     *    —o que trae celdas fuera del 8×8, o sea, un save del modo Infinito borrado— se descarta en
     *    silencio en vez de dejar una ranura que reviente al pulsar CONTINUAR.
     *  · **Conserva la hora original.** Se persiste con `gameSavedAtMs`, no con la de ahora: si se
     *    estampara la hora de la descarga, el tablero recién bajado ganaría para siempre cualquier
     *    conflicto futuro contra el que el jugador juegue de verdad en el otro móvil.
     */
    private suspend fun installCloudBoardIfNewer(
        merged: com.cukiti.teikafusion.model.CloudSaveData
    ): Boolean {
        val json = merged.gameStateJson ?: return false
        // El tablero que ha ganado la fusión puede ser el de este aparato (p. ej. porque el de la
        // nube era más viejo, o porque el local venía sin hora del esquema v3). Ahí no hay nada que
        // instalar: se compara el contenido, que es lo único que distingue un caso del otro.
        if (json == prefs.savedGameStateFlow.first()) return false
        val localSavedAt = prefs.savedGameAtFlow.first()
        if (merged.gameSavedAtMs <= localSavedAt) return false
        val status = _gameState.value.status
        if (status == com.cukiti.teikafusion.model.GameStatus.PLAYING ||
            status == com.cukiti.teikafusion.model.GameStatus.PAUSED) return false
        val decoded = try {
            GameStateJson.decodeFromString<GameState>(json)
        } catch (e: Exception) {
            android.util.Log.w("GameViewModel", "Tablero de nube ilegible, se ignora", e)
            return false
        }
        if (decoded.grid.keys.any { it.x >= GameState.GRID_SIZE || it.y >= GameState.GRID_SIZE }) return false
        prefs.saveGameState(json, merged.gameSavedAtMs, level = decoded.level)
        _hasSavedGame.value = true
        _savedGameLevel.value = decoded.level
        // P-163 · Y SE DICE. Sin esto el jugador se encuentra un CONTINUAR apuntando a un nivel que
        // él no dejó a medias en ESTE aparato. No pisa el aviso de progreso restaurado —ese habla
        // del nivel, que es el número gordo—: solo cubre el hueco de que no haya ninguno.
        if (_cloudRestoreNotice.value == null) {
            _cloudRestoreNotice.value = "Partida restaurada · nivel ${decoded.level}"
        }
        return true
    }

    /**
     * Enseña la oferta del paquete inicial si procede, y solo una vez en la vida de la instalación.
     *
     * Las tres puertas, y ninguna sobra:
     *  · **ya se ofreció** (`starterPackOffered`, local) — la ventana es de una sola vez;
     *  · **ya lo tiene** (`starterPackGranted`, que viaja en la nube) — ofrecerle a alguien algo que
     *    ya compró es la forma más rápida de parecer una máquina tragaperras;
     *  · **Play no lo sirve** — sin `ProductDetails` no hay precio que enseñar ni compra que hacer,
     *    y la ventana saldría vacía. En ese caso NO se marca como ofrecido: se intentará al cerrar
     *    el capítulo siguiente, cuando puede que la tienda ya responda.
     */
    private fun ofrecerPaqueteInicialUnaVez() {
        viewModelScope.launch {
            if (prefs.starterPackOfferedFlow.first()) return@launch
            if (prefs.starterPackGrantedFlow.first()) return@launch
            val disponible = com.cukiti.teikafusion.BillingManager.products.value
                .any { it.productId == com.cukiti.teikafusion.model.StorePacks.STARTER_PACK_ID }
            if (!disponible) {
                android.util.Log.i("GameViewModel", "Paquete inicial: Play no lo sirve todavía, no se ofrece")
                return@launch
            }
            prefs.saveStarterPackOffered(true)
            _showStarterPackOffer.value = true
        }
    }

    /** Desbloquea el onboarding cuando el arranque confirmó que no hay sesión vinculada (anónimo). */
    fun finishInitialAccountCheck() {
        _initialAccountSyncFinished.value = true
        // Anónimo confirmado: nunca escribirá player_stats, así que la identidad ya está "resuelta".
        markCloudIdentityResolved()
    }

    // Garantiza que el chequeo/sync inicial de cuenta corra UNA sola vez por vida del ViewModel. Como el
    // ViewModel sobrevive a recreaciones de la Activity (cambios de config), esto evita relanzar el sync
    // (y su overlay "Cargando tu cuenta") cada vez que la Activity se recrea al volver de 2º plano. En
    // un arranque limpio o tras process death el ViewModel es nuevo → el flag es false → sí corre.
    @Volatile private var initialAccountCheckStarted = false

    /** Llamado por MainActivity.onCreate. Idempotente: solo actúa en el primer arranque del ViewModel. */
    fun ensureInitialAccountCheck() {
        if (initialAccountCheckStarted) return
        initialAccountCheckStarted = true
        // No hay token que persista al reinicio, pero Firebase conserva la sesión google.com. Si el
        // usuario que vuelve está vinculado con Google, sincronizamos sin re-autenticar (token null).
        if (isReturningGoogleUser()) {
            com.cukiti.teikafusion.GoogleManager.hydrateFromFirebase()
            syncCloudSaveOnSignIn(LinkedProvider.GOOGLE, null)
        } else {
            finishInitialAccountCheck()
        }
    }

    /** true si Firebase ya tiene una sesión no-anónima vinculada con Google (usuario que vuelve). */
    private fun isReturningGoogleUser(): Boolean = try {
        val user = com.google.firebase.auth.FirebaseAuth.getInstance().currentUser
        user != null && !user.isAnonymous && user.providerData.any {
            it.providerId == com.google.firebase.auth.GoogleAuthProvider.PROVIDER_ID
        }
    } catch (_: Exception) { false }

    /**
     * true SOLO si el jugador vinculó una cuenta de Google. Los anónimos no escriben NADA en Firestore
     * (ni player_stats, ni leaderboard, ni cloud_saves) ni reciben comandos admin → así nunca queda
     * una cuenta fantasma en la base de datos. Ranking, nombre y guardado en la nube exigen vínculo.
     */
    private fun isCloudAccount(): Boolean =
        com.cukiti.teikafusion.GoogleManager.googleId.value != null

    /** El proveedor con el que hay sesión de nube activa, o null si es anónimo. */
    private fun linkedProvider(): LinkedProvider? =
        if (com.cukiti.teikafusion.GoogleManager.googleId.value != null) LinkedProvider.GOOGLE else null

    /**
     * Traduce el fallo de Firebase Auth a la frase que de verdad ayuda al jugador.
     *
     * Antes TODO fallo de vinculación decía «Revisa tu conexión», y eso mandaba a mirar el wifi
     * cuando el problema real era una credencial rechazada o App Check bloqueando el tráfico. Un
     * aviso que apunta al sitio equivocado es peor que no dar
     * ninguno: hace perder el tiempo en el único sitio donde no está el fallo.
     */
    private fun linkFailureText(error: Throwable?): String = when {
        error == null ->
            "No se pudo vincular tu cuenta. Revisa tu conexión."
        error is com.google.firebase.FirebaseNetworkException ->
            "No se pudo vincular tu cuenta. Revisa tu conexión."
        error is com.google.firebase.auth.FirebaseAuthInvalidCredentialsException ->
            "El proveedor rechazó la credencial. Vuelve a intentarlo."
        error is com.google.firebase.auth.FirebaseAuthUserCollisionException ->
            "Esa cuenta ya está vinculada a otro perfil."
        error is com.google.firebase.auth.FirebaseAuthInvalidUserException ->
            "Esa cuenta está deshabilitada o ya no existe."
        // App Check rechazando el tráfico: no es del jugador, es de la consola.
        error.message?.contains("App Check", ignoreCase = true) == true ||
            error.message?.contains("appCheck", ignoreCase = true) == true ->
            "La verificación de la app fue rechazada (App Check)."
        else ->
            "No se pudo vincular tu cuenta. Vuelve a intentarlo."
    }

    private fun accountFailureMessage(userMessage: String, detail: String?): String =
        if (com.cukiti.teikafusion.BuildConfig.DEBUG && !detail.isNullOrBlank()) {
            "$userMessage\n[debug] $detail"
        } else {
            userMessage
        }

    /**
     * Conecta con Google (aviso post-tutorial, Ranking o Ajustes). Credential Manager es suspend.
     * Autenticamos con Firebase AQUÍ (antes del reinicio) porque el ID token de Google no
     * sobrevive al restart; así la sesión `google.com` queda persistida en Firebase y el arranque
     * limpio la detecta. Persistimos si hubo "switch" a una cuenta existente para poder ofrecer el
     * diálogo de conflicto tras el reinicio (el token ya no estará disponible para re-derivarlo).
     */
    fun connectGoogle(activity: android.app.Activity) {
        viewModelScope.launch {
            val idToken = when (val login = com.cukiti.teikafusion.GoogleManager.login(activity)) {
                is com.cukiti.teikafusion.GoogleLoginResult.Success -> login.idToken
                // Cancelar es una decisión del jugador: silencio.
                com.cukiti.teikafusion.GoogleLoginResult.Cancelled -> return@launch
                is com.cukiti.teikafusion.GoogleLoginResult.Failure -> {
                    _accountNotice.value = accountFailureMessage(
                        login.userMessage,
                        com.cukiti.teikafusion.GoogleManager.lastErrorDetail
                    )
                    return@launch
                }
            }
            _accountLoadingKind.value = AccountLoadingKind.LOADING
            _accountSyncing.value = true
            val result = kotlinx.coroutines.withTimeoutOrNull(NET_TIMEOUT_MS) {
                com.cukiti.teikafusion.FirebaseManager.authenticateWithGoogle(
                    idToken = idToken,
                    // El ID token se consume al intentar vincular: si esa cuenta de Google ya existía,
                    // hace falta uno NUEVO para entrar a ella. Se vuelve a pedir al selector.
                    freshIdToken = {
                        (com.cukiti.teikafusion.GoogleManager.login(activity)
                            as? com.cukiti.teikafusion.GoogleLoginResult.Success)?.idToken
                    }
                )
            }
            if (result == null || !result.isSuccess) {
                // Sin internet o error: no reiniciamos a un estado roto; seguimos anónimos.
                android.util.Log.w("GameViewModel", "connectGoogle: auth Firebase falló", result?.error)
                _accountSyncing.value = false
                _accountNotice.value = accountFailureMessage(
                    linkFailureText(result?.error),
                    result?.error?.let { "${it.javaClass.simpleName}: ${it.message}" }
                        ?: "timeout ${NET_TIMEOUT_MS}ms"
                )
                return@launch
            }
            val name = com.google.firebase.auth.FirebaseAuth.getInstance().currentUser?.displayName
            com.cukiti.teikafusion.GoogleManager.publishSession(result.uid, name)
            // El diálogo de conflicto solo aplica si entramos a una cuenta existente con progreso.
            prefs.savePendingCloudConflictPrompt(result.switchedToExistingAccount)
            onCloudLoginSuccess()
        }
    }

    /**
     * Tras un login de nube exitoso (desde el aviso post-tutorial, Ranking o Ajustes), dispara el
     * REINICIO del juego (estilo Clash of Clans). En el arranque limpio,
     * MainActivity/el ViewModel detectan la sesión y ejecutan la sincronización que fusiona el progreso
     * local con la nube. Reiniciar garantiza que TODO el estado en memoria se recargue con la cuenta correcta.
     */
    private fun onCloudLoginSuccess() {
        viewModelScope.launch {
            _accountLoadingKind.value = AccountLoadingKind.LOADING   // "Cargando tu cuenta…"
            _accountSyncing.value = true   // muestra la pantalla de carga hasta que reinicie
            _restartRequested.value = true
        }
    }

    /**
     * Cierra la sesión actual para abrir otra cuenta (estilo Clash of Clans). Respalda el progreso a
     * la nube si estaba vinculado, cierra Google + Firebase, borra los datos locales y REINICIA el
     * juego → vuelve al arranque local limpio, sin una pantalla obligatoria de cuenta.
     */
    // ── Borrado de cuenta (requisito de la política de datos de Google Play) ──────────────────
    // Play exige que toda app que permite CREAR una cuenta permita ELIMINARLA desde dentro de la
    // app (y ofrezca además una URL web). El «Borrar» de Ajustes es un RESET de progreso: conserva
    // la cuenta. Esto es lo otro: se va todo, y es irreversible.
    /**
     * Esta versión está por debajo del mínimo soportado y hay que actualizar.
     *
     * Es la red de seguridad para el peor caso: una versión publicada con un bug que corrompe
     * guardados o rompe el respaldo en la nube. Se levanta desde la consola, sin publicar nada.
     * Por defecto `min_supported_version_code` es 0, así que nunca se dispara sola.
     */
    val updateRequired: StateFlow<Boolean> = _remoteConfig
        .map { it.minSupportedVersionCode > com.cukiti.teikafusion.BuildConfig.VERSION_CODE }
        .stateIn(viewModelScope, kotlinx.coroutines.flow.SharingStarted.Eagerly, false)

    /** Texto del aviso de actualización (el de la consola, o uno por defecto si viene vacío). */
    fun updateMessageText(): String = _remoteConfig.value.updateMessage.ifBlank {
        "Hay una versión nueva de Teika Fusion con correcciones importantes. " +
            "Actualiza desde Google Play para seguir jugando."
    }

    /** Aplica un porcentaje de Remote Config (100 = sin cambio) redondeando al entero más cercano. */
    private fun applyPercent(base: Int, percent: Int): Int =
        if (percent == 100) base else ((base.toLong() * percent) / 100L).toInt()

    // ── Quitar anuncios (compra permanente) ──────────────────────────────────────────────────
    private val _adsRemoved = MutableStateFlow(false)
    val adsRemoved: StateFlow<Boolean> = _adsRemoved.asStateFlow()

    /**
     * El jugador tiene «quitar anuncios»: recién comprado, o RESTAURADO al reinstalar (Play sigue
     * devolviendo la compra porque no es consumible).
     *
     * Idempotente a propósito: se llama en cada arranque y no debe celebrar dos veces. El reveal
     * solo sale la primera vez, cuando el flag pasa de apagado a encendido.
     */
    private fun applyAdsRemoved() {
        val yaLoTenia = _adsRemoved.value
        _adsRemoved.value = true
        com.cukiti.teikafusion.AdManager.setAdsRemoved(true)
        viewModelScope.launch { prefs.saveAdsRemoved() }
        if (!yaLoTenia) {
            emitReveal(
                title = "¡ADIÓS A LOS ANUNCIOS!",
                accentArgb = 0xFFFFD700,
                items = listOf(
                    com.cukiti.teikafusion.model.RewardItem(
                        kind = com.cukiti.teikafusion.model.RewardKind.TEIKOINS,
                        label = "Sin anuncios para siempre", amount = 0
                    )
                )
            )
        }
    }

    // ── LA TIENDA REABIERTA (2026-09-06) ─────────────────────────────────────────────────────

    /** Packs de monedas cuya primera compra ya cobró el bono de bienvenida del 100 %. */
    private val _coinBonusClaimed = MutableStateFlow<Set<String>>(emptySet())
    val coinBonusClaimed: StateFlow<Set<String>> = _coinBonusClaimed.asStateFlow()

    /** El paquete inicial ya está entregado (comprado y acreditado). */
    private val _starterPackGranted = MutableStateFlow(false)
    val starterPackGranted: StateFlow<Boolean> = _starterPackGranted.asStateFlow()

    /**
     * **UN PACK DE MONEDAS, CON SU BONO DE BIENVENIDA** (decisión del usuario, 2026-09-06).
     *
     * La **primera** compra de cada pack paga el doble. La regla es pura y vive en
     * [com.cukiti.teikafusion.model.StorePacks]; aquí solo se acredita y se recuerda cuál ya lo
     * cobró — y ese recuerdo viaja con la cuenta, porque si fuera del aparato bastaría reinstalar
     * para volver a doblar los tres packs.
     *
     * El bono se anuncia **aparte** en el reveal (`bonus = true`), no sumado al total: un jugador
     * al que le entran 2400 teikoins por un pack de 1200 tiene que ver POR QUÉ, o lo lee como un
     * error de la tienda.
     */
    private fun applyCoinPack(result: com.cukiti.teikafusion.PurchaseResult.Coins) {
        val packs = com.cukiti.teikafusion.model.StorePacks
        val bonus = packs.welcomeBonusFor(result.productId, _coinBonusClaimed.value)
        grantTeikoins(result.teikoins + bonus)
        if (bonus > 0) {
            val claimed = _coinBonusClaimed.value + result.productId
            _coinBonusClaimed.value = claimed
            viewModelScope.launch { prefs.saveCoinBonusClaimed(claimed) }
        }
        val items = mutableListOf(
            com.cukiti.teikafusion.model.RewardItem(
                kind = com.cukiti.teikafusion.model.RewardKind.TEIKOINS,
                label = "${result.teikoins} Teikoins", amount = result.teikoins
            )
        )
        if (bonus > 0) {
            items += com.cukiti.teikafusion.model.RewardItem(
                kind = com.cukiti.teikafusion.model.RewardKind.TEIKOINS,
                label = "¡+$bonus de regalo!", amount = bonus, bonus = true
            )
        }
        // La sorpresa aleatoria solo cuando NO hay bono: dos premios extra en la misma compra se
        // pisan en el reveal y el segundo deja de leerse como un premio.
        if (bonus == 0) rollSurpriseBonus()?.let { items.add(it) }
        emitReveal(title = "¡COMPRA COMPLETADA!", accentArgb = 0xFFFFD700, items = items)
    }

    /**
     * **EL PAQUETE INICIAL** (2026-09-06): 5000 teikoins, los dos bloques de pago, siete días de
     * vidas infinitas y **Estela**.
     *
     * **Idempotente, y esta vez no por elegancia sino por dinero.** Play reenvía las compras no
     * consumibles en CADA arranque —es como se restauran al reinstalar—, así que sin la marca
     * `starterPackGranted` abrir el juego diez veces regalaría cincuenta mil teikoins. Con «quitar
     * anuncios» el mismo reenvío es inofensivo; aquí es una fuga, y por eso la marca viaja con la
     * cuenta y no con el aparato.
     */
    private fun applyStarterPack() {
        if (_starterPackGranted.value) return
        _starterPackGranted.value = true
        val packs = com.cukiti.teikafusion.model.StorePacks
        viewModelScope.launch { prefs.saveStarterPackGranted() }

        grantTeikoins(packs.STARTER_COINS, silent = true)
        // Los bloques: se desbloquean sin auto-equipar. Cambiarle el tablero al jugador de golpe,
        // sin habérselo pedido, es la clase de sorpresa que no gusta; que elija él en la tienda.
        val nuevos = _unlockedCosmetics.value + packs.STARTER_SKIN_IDS
        _unlockedCosmetics.value = nuevos
        viewModelScope.launch { prefs.saveUnlockedCosmetics(nuevos) }
        grantInfiniteLives(packs.STARTER_INFINITE_LIVES_MS)
        if (packs.STARTER_COMPANION_ID !in _claimedCharacterIds.value) {
            claimCharacter(packs.STARTER_COMPANION_ID)
        }

        val estela = com.cukiti.teikafusion.model.NamedTeikaRegistry.all
            .firstOrNull { it.id == packs.STARTER_COMPANION_ID }
        emitReveal(
            title = "¡PAQUETE INICIAL!",
            accentArgb = 0xFFFFD700,
            items = buildList {
                add(
                    com.cukiti.teikafusion.model.RewardItem(
                        kind = com.cukiti.teikafusion.model.RewardKind.TEIKOINS,
                        label = "${packs.STARTER_COINS} Teikoins", amount = packs.STARTER_COINS
                    )
                )
                add(
                    com.cukiti.teikafusion.model.RewardItem(
                        kind = com.cukiti.teikafusion.model.RewardKind.INFINITE_LIVES,
                        label = "${packs.STARTER_INFINITE_LIVES_DAYS} días de vidas infinitas",
                        amount = packs.STARTER_INFINITE_LIVES_DAYS * 24
                    )
                )
                packs.STARTER_SKIN_IDS.forEach { id ->
                    add(
                        com.cukiti.teikafusion.model.RewardItem(
                            kind = com.cukiti.teikafusion.model.RewardKind.BLOCK_SKIN,
                            label = "Bloque ${com.cukiti.teikafusion.ui.BlockSkins.byId(id).name}",
                            skinId = id
                        )
                    )
                }
                if (estela != null) {
                    add(
                        com.cukiti.teikafusion.model.RewardItem(
                            kind = com.cukiti.teikafusion.model.RewardKind.TEIKOINS,
                            label = estela.name, amount = 0, bonus = true
                        )
                    )
                }
            }
        )
    }

    // Contador de intentos SEGUIDOS del mismo nivel, solo para el evento `level_start` (no se
    // persiste: interesa la racha de reintentos dentro de una sesión, no el histórico).
    private var lastStartedLevel = -1
    private var lastLevelAttempt = 0

    private val _accountDeletion = MutableStateFlow<AccountDeletionOutcome?>(null)
    val accountDeletion: StateFlow<AccountDeletionOutcome?> = _accountDeletion.asStateFlow()

    /** Ajustes ya mostró el resultado del borrado. */
    fun consumeAccountDeletionOutcome() { _accountDeletion.value = null }

    /**
     * Elimina la cuenta del jugador: primero sus datos en Firestore, después la identidad.
     *
     * **El orden es obligatorio.** Las reglas de las tres colecciones exigen `request.auth.uid`, así
     * que si se borrase el usuario de Auth primero, los documentos quedarían huérfanos y NADIE
     * tendría ya permiso para eliminarlos — justo lo contrario de lo que pide la política de datos.
     * Por eso, si algún borrado de Firestore falla, se aborta sin tocar Auth y se puede reintentar.
     *
     * Se borran los DOS posibles `player_stats` del jugador: el llaveado por UID y el histórico
     * llaveado por ANDROID_ID (ver [PlayerOverrideManager.deleteAllProfilesOf]).
     */
    fun deleteAccount() {
        viewModelScope.launch {
            if (!isOnline()) {
                _accountDeletion.value = AccountDeletionOutcome.OFFLINE
                return@launch
            }
            _accountLoadingKind.value = AccountLoadingKind.DELETING_ACCOUNT
            _accountSyncing.value = true
            try {
                val uid = com.cukiti.teikafusion.FirebaseManager.currentUid()
                if (uid == null) {
                    // Invitado puro: no hay nada en la nube. Se limpia lo local y vuelve al arranque.
                    wipeLocalAndRestart()
                    _accountDeletion.value = AccountDeletionOutcome.DELETED
                    return@launch
                }

                // 1) Datos, mientras todavía hay permiso.
                // Se borran TODOS los ids posibles: el UID actual y el ANDROID_ID con el que las
                // versiones antiguas llaveaban el perfil (ver PlayerOverrideManager.getPlayerId).
                val statsIds = setOfNotNull(
                    uid,
                    _playerId.value.takeIf { it.isNotBlank() },
                    com.cukiti.teikafusion.data.PlayerOverrideManager.legacyAndroidId(appContext)
                )

                val okSave = com.cukiti.teikafusion.CloudSaveRepository.delete(uid)
                val okStats = com.cukiti.teikafusion.data.PlayerOverrideManager
                    .deleteAllProfilesOf(statsIds)
                val okBoard = com.cukiti.teikafusion.LeaderboardRepository.deleteOwnEntry(uid)

                if (!okSave || !okStats || !okBoard) {
                    android.util.Log.e(
                        "GameViewModel",
                        "deleteAccount: fallo borrando datos (save=$okSave stats=$okStats board=$okBoard) " +
                            "→ NO se elimina la identidad para poder reintentar"
                    )
                    _accountDeletion.value = AccountDeletionOutcome.FAILED
                    return@launch
                }

                // 2) Identidad.
                when (com.cukiti.teikafusion.FirebaseManager.deleteAccount()) {
                    com.cukiti.teikafusion.FirebaseManager.DeleteAccountResult.REQUIRES_RECENT_LOGIN -> {
                        // Los datos YA se fueron; solo falta la identidad. El jugador vuelve a entrar
                        // con su proveedor y repite: el segundo intento no encuentra datos y va directo.
                        _accountDeletion.value = AccountDeletionOutcome.REQUIRES_RECENT_LOGIN
                        return@launch
                    }
                    com.cukiti.teikafusion.FirebaseManager.DeleteAccountResult.FAILED -> {
                        _accountDeletion.value = AccountDeletionOutcome.FAILED
                        return@launch
                    }
                    else -> Unit   // DELETED o NO_SESSION: seguimos a la limpieza local
                }

                Analytics.trackAccountDeleted()
                Analytics.setPlayer(null)
                wipeLocalAndRestart()
                _accountDeletion.value = AccountDeletionOutcome.DELETED
            } catch (e: Exception) {
                com.cukiti.teikafusion.OnlineTelemetry.report("GameViewModel", "deleteAccount", e)
                _accountDeletion.value = AccountDeletionOutcome.FAILED
            } finally {
                _accountSyncing.value = false
                _accountLoadingKind.value = AccountLoadingKind.LOADING
            }
        }
    }

    /** Cierra sesión en los proveedores, vacía DataStore y pide un reinicio local limpio. */
    private suspend fun wipeLocalAndRestart() {
        com.cukiti.teikafusion.GoogleManager.logOut(appContext)
        com.cukiti.teikafusion.FirebaseManager.signOut()
        prefs.clearAll()
        _restartRequested.value = true
    }

    fun logOut() {
        viewModelScope.launch {
            _accountLoadingKind.value = AccountLoadingKind.LOGGING_OUT   // "Cerrando sesión…"
            _accountSyncing.value = true
            // Respaldo final antes de salir, para no perder progreso de un usuario vinculado.
            val uid = com.cukiti.teikafusion.FirebaseManager.currentUid()
            // Solo respaldar si ya se había leído la nube esta sesión (evita pisar progreso real) y con
            // timeout, para que sin internet el logout NO se quede colgado esperando el ACK de Firestore.
            if (isCloudAccount() && uid != null && cloudMergedThisSession) {
                try {
                    cloudStateLoaded.await()
                    cloudSyncMutex.withLock {
                        kotlinx.coroutines.withTimeoutOrNull(NET_TIMEOUT_MS) {
                            saveCloudMerged(uid)
                        }
                    }
                } catch (_: Exception) {}
            }
            com.cukiti.teikafusion.GoogleManager.logOut(appContext)
            com.cukiti.teikafusion.FirebaseManager.signOut()
            prefs.clearAll()
            _restartRequested.value = true
        }
    }

    /**
     * Resuelve la identidad Firebase con la credencial del proveedor (el ID token de Google
     * ID token) y baja/fusiona/sube el progreso en Firestore (`cloud_saves`). Lo dispara el arranque
     * cuando hay sesión activa. Para Google que vuelve, `token` puede ser null: la sesión ya está en
     * Firebase y no hace falta re-autenticar.
     */
    fun syncCloudSaveOnSignIn(provider: LinkedProvider, token: String?) {
        viewModelScope.launch {
            pendingProvider = provider
            pendingCloudToken = token
            cloudStateLoaded.await()
            // Detectar conexión DURANTE la pantalla de carga (splash), ANTES de mostrar nada.
            // Offline: NO se muestra "Cargando tu cuenta"; el splash sigue su curso y el jugador entra
            // directo con sus datos locales. Al reconectar se sincroniza automáticamente.
            if (!isOnline()) {
                android.util.Log.w("GameViewModel", "Cuenta $provider offline al iniciar → se juega local; autosync al reconectar")
                registerConnectivityAutoSync()
                _initialAccountSyncFinished.value = true
                markCloudIdentityResolved()
                return@launch
            }
            // Online: ahora sí mostramos "Cargando tu cuenta" mientras se sincroniza. El diálogo de
            // conflicto (si lo hubiera) corre DENTRO con su propia espera.
            _accountSyncing.value = true

            // GUARDIÁN DEL ARRANQUE (2026-09-07): con red mala la sincronización puede tardar más de
            // lo que nadie aguanta mirando una barra. Pasado [STARTUP_SYNC_GRACE_MS] se abre la
            // puerta igual y el jugador entra con lo local — el mismo camino que si no hubiera red.
            // La sincronización sigue corriendo por detrás; si acaba, el `finally` vuelve a poner
            // estas mismas banderas y no pasa nada (son idempotentes).
            val guardian = launch {
                kotlinx.coroutines.delay(STARTUP_SYNC_GRACE_MS)
                android.util.Log.w(
                    "GameViewModel",
                    "Cuenta $provider tarda más de ${STARTUP_SYNC_GRACE_MS}ms → se entra con datos " +
                        "locales; la sincronización sigue en segundo plano"
                )
                startupGraceExpired = true
                registerConnectivityAutoSync()
                _initialAccountSyncFinished.value = true
                _accountSyncing.value = false
                markCloudIdentityResolved()
            }
            try {
                val synced = performCloudSync(provider, token, allowDialog = true)
                if (!synced) {
                    android.util.Log.w("GameViewModel", "Cuenta $provider no sincronizó → se reintentará al reconectar")
                    registerConnectivityAutoSync()
                }
            } finally {
                guardian.cancel()
                _initialAccountSyncFinished.value = true
                _accountSyncing.value = false
                // Identidad resuelta: a partir de aquí el juego continúa normal.
                markCloudIdentityResolved()
            }
        }
    }

    /**
     * Hace el pull+merge+push de la cuenta con timeouts en cada llamada de red. Devuelve
     * true SOLO si se logró leer la nube (y por tanto subir sin riesgo). Si está offline devuelve false
     * sin subir nada (no se puede pisar el progreso real de la nube con datos locales sin haberla leído).
     */
    private fun isOnline(): Boolean {
        val cm = appContext.getSystemService(android.content.Context.CONNECTIVITY_SERVICE)
            as? android.net.ConnectivityManager ?: return false
        val net = cm.activeNetwork ?: return false
        val caps = cm.getNetworkCapabilities(net) ?: return false
        return caps.hasCapability(android.net.NetworkCapabilities.NET_CAPABILITY_INTERNET) &&
            caps.hasCapability(android.net.NetworkCapabilities.NET_CAPABILITY_VALIDATED)
    }

    private suspend fun performCloudSync(
        provider: LinkedProvider,
        token: String?,
        allowDialog: Boolean
    ): Boolean {
        // Sin conexión confirmada: no esperar timeouts de red → arranque instantáneo en modo offline.
        if (!isOnline()) {
            android.util.Log.w("GameViewModel", "Cloud sync: dispositivo offline → arranque local inmediato")
            return false
        }
        if (!_remoteConfig.value.cloudSyncEnabled) {
            android.util.Log.w("GameViewModel", "Cloud sync: DESACTIVADO por Remote Config → solo local")
            return false
        }
        return cloudSyncMutex.withLock {
            val preAuthUid = com.cukiti.teikafusion.FirebaseManager.currentUid()
            val canonicalUid: String?
            val switchedToExisting: Boolean
            if (provider == LinkedProvider.GOOGLE && token == null) {
                // Google que vuelve: la sesión ya está persistida en Firebase (google.com), no hace
                // falta re-autenticar. El "switch" (si aplica) se guardó en prefs durante el connect.
                canonicalUid = com.cukiti.teikafusion.FirebaseManager.currentUid()
                switchedToExisting = prefs.pendingCloudConflictPromptFlow.first()
                prefs.savePendingCloudConflictPrompt(false)   // consumir el flag
                if (canonicalUid == null) {
                    android.util.Log.w("GameViewModel", "Cloud sync: sin UID Firebase para Google")
                    return@withLock false
                }
            } else {
                // Para un usuario que vuelve, authenticateWith* resuelve sin red (ya hay sesión); en un
                // primer vínculo necesita internet → timeout para no colgarse.
                val authResult = kotlinx.coroutines.withTimeoutOrNull(NET_TIMEOUT_MS) {
                    com.cukiti.teikafusion.FirebaseManager.authenticateWithGoogle(token ?: "")
                }
                if (authResult == null || !authResult.isSuccess || authResult.uid == null) {
                    android.util.Log.w("GameViewModel", "Cloud sync: auth $provider no disponible (¿sin internet?)")
                    return@withLock false
                }
                canonicalUid = authResult.uid
                switchedToExisting = authResult.switchedToExistingAccount
                // `sign_up` = primer vínculo de este dispositivo (el anónimo se convirtió en cuenta);
                // `login` = una cuenta que ya existía en otro sitio. Son los eventos estándar que
                // alimentan los informes de adquisición.
                if (authResult.linkedAnonymousAccount) {
                    Analytics.trackSignUp(provider.name.lowercase())
                } else {
                    Analytics.trackLogin(provider.name.lowercase())
                }
            }
            canonicalUid ?: return@withLock false
            _currentUid.value = canonicalUid
            _playerId.value = canonicalUid

            if (!preAuthUid.isNullOrBlank() && preAuthUid != canonicalUid) {
                com.cukiti.teikafusion.data.PlayerOverrideManager.deleteProfile(preAuthUid)
            }

            // Leer la nube. Distinguir "offline/error" (failure) de "cuenta nueva vacía" (success(null)).
            val loadResult = kotlinx.coroutines.withTimeoutOrNull(NET_TIMEOUT_MS) {
                com.cukiti.teikafusion.CloudSaveRepository.load(canonicalUid)
            }
            if (loadResult == null || loadResult.isFailure) {
                android.util.Log.w("GameViewModel", "Cloud sync: no se pudo leer la nube (offline) → sin subir")
                return@withLock false
            }
            val cloudJson = loadResult.getOrNull()
            if (cloudJson != null) {
                // Solo se ofrece elegir al ENTRAR a una cuenta que ya existía con progreso (colisión),
                // y solo mientras el jugador NO esté ya jugando: ver [startupGraceExpired]. Fuera de
                // esa ventana se FUSIONA —por máximos, nunca resta— y la pregunta se guarda para el
                // próximo arranque, donde se puede hacer con el splash puesto.
                if (allowDialog && !startupGraceExpired) {
                    resolveCloudVsLocal(cloudJson, promptOnConflict = switchedToExisting)
                } else {
                    // Si había un conflicto pendiente y aquí no se puede preguntar, se REARMA. Sin
                    // esto la marca se consumía igual y la elección se perdía para siempre — lo que
                    // ya pasaba en el autosync por reconexión, que también entra por esta rama.
                    if (switchedToExisting) prefs.savePendingCloudConflictPrompt(true)
                    mergeCloudProgress(cloudJson)
                }
            }
            // La nube quedó leída/fusionada → ya es seguro subir.
            cloudMergedThisSession = true

            // ⚠️ LAS DOS DE ABAJO IBAN SIN TIMEOUT (arreglado 2026-09-07). Son las que colgaban el
            // arranque con red mala: `upsertEntry` es una **Cloud Function**, y una función que no
            // responde no se rinde sola hasta pasado más de un minuto. Ninguna de las dos es
            // imprescindible para jugar —son estadísticas y ranking—, así que si no entran en
            // [NET_TIMEOUT_MS] se abandonan y se reintentan cuando la conexión mejore.
            val state = _gameState.value
            kotlinx.coroutines.withTimeoutOrNull(NET_TIMEOUT_MS) {
                com.cukiti.teikafusion.data.PlayerOverrideManager.pushPlayerStats(
                    context = appContext,
                    coins = state.teikoins,
                    maxLevel = state.maxUnlockedLevel,
                    displayName = _displayName.value
                )
            }
            if (_displayName.value.isNotBlank()) {
                kotlinx.coroutines.withTimeoutOrNull(NET_TIMEOUT_MS) {
                    com.cukiti.teikafusion.LeaderboardRepository.upsertEntry(
                        uid = canonicalUid,
                        displayName = _displayName.value,
                        level = state.maxUnlockedLevel,
                        teikas = state.maxTeikas,
                        avatarType = _avatarType.value,
                        xp = _totalXp.value
                    )
                }
            }
            // El write offline de Firestore se encola y sincroniza solo al reconectar; con timeout
            // para no bloquear si el ACK del servidor tarda.
            kotlinx.coroutines.withTimeoutOrNull(NET_TIMEOUT_MS) {
                saveCloudMerged(canonicalUid)
            }
            true
        }
    }

    /**
     * Registra (una sola vez) un listener de conectividad: cuando vuelve el internet y aún no se ha
     * sincronizado la cuenta de esta sesión, hace pull+merge+push automáticamente para que
     * todo lo conseguido offline quede guardado en la base de datos.
     */
    private fun registerConnectivityAutoSync() {
        if (connectivityCallback != null) return
        val cm = appContext.getSystemService(android.content.Context.CONNECTIVITY_SERVICE)
            as? android.net.ConnectivityManager ?: return
        val request = android.net.NetworkRequest.Builder()
            .addCapability(android.net.NetworkCapabilities.NET_CAPABILITY_INTERNET)
            .build()
        val callback = object : android.net.ConnectivityManager.NetworkCallback() {
            private fun tryAutoSync() {
                // P-25: respaldo que no llegó. Es el caso más común —la nube YA se fusionó en esta
                // sesión y lo único que falló fue la subida—, y antes no lo cubría nadie.
                if (cloudPushPending && cloudMergedThisSession && isCloudAccount()) {
                    android.util.Log.i("GameViewModel", "Internet recuperado → reintento del respaldo")
                    cloudPushPending = false
                    pushCloudSave()
                }
                val provider = pendingProvider ?: return
                if (cloudMergedThisSession) return
                if (!isCloudAccount()) return
                // Google que vuelve puede tener token null: la sesión ya está en Firebase.
                val token = pendingCloudToken
                viewModelScope.launch {
                    android.util.Log.i("GameViewModel", "Internet recuperado → autosync de la cuenta $provider")
                    val ok = performCloudSync(provider, token, allowDialog = false)
                    if (ok) android.util.Log.i("GameViewModel", "✓ autosync OK: progreso offline guardado en la nube")
                }
            }
            // onCapabilitiesChanged dispara cuando la red queda VALIDADA (internet real), que es justo
            // lo que comprueba isOnline() — evita perder el autosync por el desfase de validación.
            override fun onCapabilitiesChanged(
                network: android.net.Network,
                caps: android.net.NetworkCapabilities
            ) {
                if (caps.hasCapability(android.net.NetworkCapabilities.NET_CAPABILITY_VALIDATED)) tryAutoSync()
            }
        }
        connectivityCallback = callback
        try {
            cm.registerNetworkCallback(request, callback)
        } catch (e: Exception) {
            android.util.Log.w("GameViewModel", "No se pudo registrar el listener de conectividad: ${e.message}")
            connectivityCallback = null
        }
    }

    /**
     * Decide qué hacer con el progreso de la nube de la cuenta recién vinculada:
     *  - Local fresco (sin avance) → carga la nube directamente (entrar a la cuenta anterior).
     *  - Nube vacía → conserva el local (luego se sube y "estrena" la cuenta).
     *  - Ambos con avance y DIFERENTES → PREGUNTA al jugador (no se sobrescribe nada solo):
     *      · "entrar a mi cuenta anterior"  → la nube reemplaza el progreso local.
     *      · "mantener mi progreso actual"  → se conserva el local (y al final pisa la nube).
     *  - Iguales o uno contiene al otro → fusión normal por máximos (no se pierde nada).
     */
    private suspend fun resolveCloudVsLocal(cloudJson: String, promptOnConflict: Boolean) {
        val cloud = com.cukiti.teikafusion.model.CloudSaveData.fromJson(cloudJson) ?: run {
            android.util.Log.e("GameViewModel", "resolveCloudVsLocal: JSON inválido")
            return
        }
        val local = localProgressSnapshot()
        val cloudHas = cloud.hasMeaningfulProgress()
        val localHas = local.hasMeaningfulProgress()
        // El eje de la elección es el nivel desbloqueado; si coincide, elegir no cambiaría nada.
        val differ = cloud.maxLevel != local.maxLevel

        when {
            !cloudHas -> {
                // La cuenta no tiene progreso guardado: conservar el local tal cual.
                android.util.Log.i("GameViewModel", "Cloud vacío → se conserva el progreso local")
            }
            !localHas -> {
                // Dispositivo limpio: cargar la cuenta anterior sin preguntar.
                overwriteWithCloudProgress(cloud)
            }
            promptOnConflict && differ -> {
                // Conflicto real: el jugador decide. Ocultamos el loading para que se vea el diálogo.
                val deferred = kotlinx.coroutines.CompletableDeferred<Boolean>()
                pendingCloudChoice = deferred
                _cloudAccountConflict.value = CloudAccountConflict(
                    cloudLevel = cloud.maxLevel,
                    cloudCoins = cloud.teikoins,
                    cloudXp = cloud.totalXp,
                    cloudName = cloud.displayName,
                    localLevel = local.maxLevel,
                    localCoins = local.teikoins,
                    localXp = local.totalXp,
                    localName = local.displayName
                )
                _accountSyncing.value = false
                val useCloud = deferred.await()
                _cloudAccountConflict.value = null
                pendingCloudChoice = null
                _accountSyncing.value = true
                if (useCloud) overwriteWithCloudProgress(cloud) else keepLocalProgress(cloud)
                // En ambos casos las monedas/compras se conservan; solo cambia el progreso de niveles.
                // El save final de syncCloudSaveOnSignIn sube el resultado a la nube.
            }
            else -> mergeCloudProgress(cloudJson)
        }
    }

    /** El jugador eligió en el diálogo de conflicto: true = entrar a su cuenta anterior (nube). */
    fun resolveCloudAccountConflict(useCloudAccount: Boolean) {
        pendingCloudChoice?.complete(useCloudAccount)
    }

    /** Sube el progreso a Firestore si hay sesión de nube. Seguro sin sesión. */
    fun pushCloudSave() {
        viewModelScope.launch {
            if (!isCloudAccount()) return@launch
            // No subir hasta haber LEÍDO/fusionado la nube en esta sesión: si no, datos locales frescos
            // (p. ej. arranque offline) podrían pisar el progreso real guardado. El listener de
            // conectividad hará el pull+merge+push cuando vuelva el internet.
            if (!cloudMergedThisSession) {
                registerConnectivityAutoSync()
                return@launch
            }
            val uid = com.cukiti.teikafusion.FirebaseManager.currentUid() ?: return@launch
            cloudStateLoaded.await()
            val ok = cloudSyncMutex.withLock {
                kotlinx.coroutines.withTimeoutOrNull(NET_TIMEOUT_MS) {
                    saveCloudMerged(uid)
                }
            }
            // P-25: si no subió, queda pendiente y se reintenta al recuperar la red.
            if (ok != true) {
                cloudPushPending = true
                registerConnectivityAutoSync()
            } else {
                cloudPushPending = false
            }
        }
    }

    override fun onCleared() {
        // OJO: `saveScope` NO se cancela aquí a propósito. Es justo lo contrario de lo que se busca —
        // el guardado del `onPause` termina de escribirse aunque la pantalla ya no exista (P-115).
        soundManager.release()
        connectivityCallback?.let { cb ->
            try {
                (appContext.getSystemService(android.content.Context.CONNECTIVITY_SERVICE)
                    as? android.net.ConnectivityManager)?.unregisterNetworkCallback(cb)
            } catch (_: Exception) {}
        }
        connectivityCallback = null
    }
}
